INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Dijo luego Jehová a Noé: Entra tú y toda tu casa en el arca; porque a ti he visto justo delante de mí en esta generación.'),
(v_cap_id, 2, 'De todo animal limpio tomarás siete parejas, macho y su hembra; mas de los animales que no son limpios, una pareja, el macho y su hembra.'),
(v_cap_id, 3, 'También de las aves de los cielos, siete parejas, macho y hembra, para conservar viva la especie sobre la faz de la tierra.'),
(v_cap_id, 4, 'Porque pasados aún siete días, yo haré llover sobre la tierra cuarenta días y cuarenta noches; y raeré de sobre la faz de la tierra a todo ser viviente que hice.'),
(v_cap_id, 5, 'E hizo Noé conforme a todo lo que le mandó Jehová.'),
(v_cap_id, 6, 'Era Noé de seiscientos años cuando el diluvio de las aguas vino sobre la tierra.'),
(v_cap_id, 7, 'Y por causa de las aguas del diluvio entró Noé al arca, y con él sus hijos, su mujer, y las mujeres de sus hijos.'),
(v_cap_id, 8, 'De los animales limpios, y de los animales que no eran limpios, y de las aves, y de todo animal que se arrastra sobre la tierra,'),
(v_cap_id, 9, 'de dos en dos entraron con Noé en el arca, macho y hembra, como mandó Dios a Noé.'),
(v_cap_id, 10, 'Y sucedió que al séptimo día las aguas del diluvio vinieron sobre la tierra.'),
(v_cap_id, 11, 'El año seiscientos de la vida de Noé, en el mes segundo, a los diecisiete días del mes, aquel día fueron rotas todas las fuentes del grande abismo, y las cataratas de los cielos fueron abiertas,'),
(v_cap_id, 12, 'y hubo lluvia sobre la tierra cuarenta días y cuarenta noches.'),
(v_cap_id, 13, 'En ese mismo día entraron Noé, y Sem, Cam y Jafet hijos de Noé, la mujer de Noé, y las tres mujeres de sus hijos, con él en el arca;'),
(v_cap_id, 14, 'ellos, y todos los animales silvestres según sus especies, y todos los animales domesticados según sus especies, y todo reptil que se arrastra sobre la tierra según su especie, y toda ave según su especie, y todo pájaro de toda especie.'),
(v_cap_id, 15, 'Vinieron, pues, con Noé al arca, de dos en dos de toda carne en que había espíritu de vida.'),
(v_cap_id, 16, 'Y los que vinieron, macho y hembra de toda carne vinieron, como le había mandado Dios; y Jehová le cerró la puerta.'),
(v_cap_id, 17, 'Y fue el diluvio cuarenta días sobre la tierra; y las aguas crecieron, y alzaron el arca, y se elevó sobre la tierra.'),
(v_cap_id, 18, 'Y subieron las aguas y crecieron en gran manera sobre la tierra; y flotaba el arca sobre la superficie de las aguas.'),
(v_cap_id, 19, 'Y las aguas subieron mucho sobre la tierra; y todos los montes altos que había debajo de todos los cielos, fueron cubiertos.'),
(v_cap_id, 20, 'Quince codos más alto subieron las aguas, después que fueron cubiertos los montes.'),
(v_cap_id, 21, 'Y murió toda carne que se mueve sobre la tierra, así de aves como de ganado y de bestias, y de todo reptil que se arrastra sobre la tierra, y todo hombre.'),
(v_cap_id, 22, 'Todo lo que tenía aliento de espíritu de vida en sus narices, todo lo que había en la tierra, murió.'),
(v_cap_id, 23, 'Así fue destruido todo ser que vivía sobre la faz de la tierra, desde el hombre hasta la bestia, los reptiles, y las aves del cielo; y fueron raídos de la tierra; y quedó solamente Noé, y los que con él estaban en el arca.'),
(v_cap_id, 24, 'Y prevalecieron las aguas sobre la tierra ciento cincuenta días.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Y se acordó Dios de Noé, y de todos los animales, y de todas las bestias que estaban con él en el arca; e hizo pasar Dios un viento sobre la tierra, y disminuyeron las aguas.'),
(v_cap_id, 2, 'Y se cerraron las fuentes del abismo y las cataratas de los cielos; y la lluvia de los cielos fue detenida.'),
(v_cap_id, 3, 'Y las aguas decrecían gradualmente sobre la tierra; y se retiraron las aguas al cabo de ciento cincuenta días.'),
(v_cap_id, 4, 'Y reposó el arca en el mes séptimo, a los diecisiete días del mes, sobre los montes de Ararat.'),
(v_cap_id, 5, 'Y las aguas fueron decreciendo hasta el mes décimo; en el décimo, al primero del mes, se descubrieron las cimas de los montes.'),
(v_cap_id, 6, 'Sucedió que al cabo de cuarenta días abrió Noé la ventana del arca que había hecho,'),
(v_cap_id, 7, 'y envió un cuervo, el cual salió, y estuvo yendo y volviendo hasta que las aguas se secaron sobre la tierra.'),
(v_cap_id, 8, 'Envió también de sí una paloma, para ver si las aguas se habían retirado de sobre la faz de la tierra.'),
(v_cap_id, 9, 'Y no halló la paloma donde sentar la planta de su pie, y volvió a él al arca, porque las aguas cubrían aún la faz de toda la tierra. Entonces él extendió su mano, y tomándola, la hizo entrar consigo en el arca.'),
(v_cap_id, 10, 'Esperó aún otros siete días, y volvió a enviar la paloma fuera del arca.'),
(v_cap_id, 11, 'Y la paloma volvió a él a la hora de la tarde; y he aquí que traía una hoja de olivo en el pico; y entendió Noé que las aguas se habían retirado de sobre la tierra.'),
(v_cap_id, 12, 'Y esperó aún otros siete días, y envió la paloma, la cual no volvió ya más a él.'),
(v_cap_id, 13, 'Y sucedió que en el año seiscientos uno de Noé, en el mes primero, el día primero del mes, las aguas se secaron sobre la tierra; y quitó Noé la cubierta del arca, y miró, y he aquí que la faz de la tierra estaba seca.'),
(v_cap_id, 14, 'Y en el mes segundo, a los veintisiete días del mes, se secó la tierra.'),
(v_cap_id, 15, 'Entonces habló Dios a Noé, diciendo:'),
(v_cap_id, 16, 'Sal del arca tú, y tu mujer, y tus hijos, y las mujeres de tus hijos contigo.'),
(v_cap_id, 17, 'Todos los animales que están contigo de toda carne, de aves y de bestias y de todo reptil que se arrastra sobre la tierra, sacarás contigo; y proliferen en la tierra, y fructifiquen y multiplíquense sobre la tierra.'),
(v_cap_id, 18, 'Entonces salió Noé, y sus hijos, su mujer, y las mujeres de sus hijos con él;'),
(v_cap_id, 19, 'todos los animales, y todo reptil y toda ave, todo lo que se mueve sobre la tierra según sus especies, salieron del arca.'),
(v_cap_id, 20, 'Y edificó Noé un altar a Jehová, y tomó de todo animal limpio y de toda ave limpia, y ofreció holocausto en el altar.'),
(v_cap_id, 21, 'Y percibió Jehová olor grato; y dijo Jehová en su corazón: No volveré más a maldecir la tierra por causa del hombre; porque el intento del corazón del hombre es malo desde su juventud; ni volveré más a destruir todo ser viviente, como he hecho.'),
(v_cap_id, 22, 'Mientras la tierra permanezca, no cesarán la sementera y la siega, el frío y el calor, el verano y el invierno, y el día y la noche.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Bendijo Dios a Noé y a sus hijos, y les dijo: Fructificad y multiplicaos, y llenad la tierra.'),
(v_cap_id, 2, 'El temor y el miedo de vosotros estarán sobre todo animal de la tierra, y sobre toda ave de los cielos, en todo lo que se mueva sobre la tierra, y en todos los peces del mar; en vuestra mano son entregados.'),
(v_cap_id, 3, 'Todo lo que se mueve y vive, os será para mantenimiento: así como las legumbres y plantas verdes, os lo he dado todo.'),
(v_cap_id, 4, 'Pero carne con su vida, que es su sangre, no comeréis.'),
(v_cap_id, 5, 'Porque ciertamente demandaré la sangre de vuestras vidas; de mano de todo animal la demandaré, y de mano del hombre; de mano del varón su hermano demandaré la vida del hombre.'),
(v_cap_id, 6, 'El que derramare sangre de hombre, por el hombre su sangre será derramada; porque a imagen de Dios es hecho el hombre.'),
(v_cap_id, 7, 'Mas vosotros fructificad y multiplicaos; procread abundantemente en la tierra, y multiplicaos en ella.'),
(v_cap_id, 8, 'Y habló Dios a Noé y a sus hijos con él, diciendo:'),
(v_cap_id, 9, 'He aquí que yo establezco mi pacto con vosotros, y con vuestra descendencia después de vosotros;'),
(v_cap_id, 10, 'y con todo ser viviente que está con vosotros, aves, ganados y toda bestia de la tierra que está con vosotros; con todos los que salieron del arca, con todo animal de la tierra.'),
(v_cap_id, 11, 'Estableceré mi pacto con vosotros, y no exterminaré ya más toda carne con aguas de diluvio, ni habrá más diluvio para destruir la tierra.'),
(v_cap_id, 12, 'Y dijo Dios: Esta es la señal del pacto que yo establezco entre mí y vosotros y todo ser viviente que está con vosotros, por siglos perpetuos:'),
(v_cap_id, 13, 'Mi arco pondré en las nubes, el cual será por señal del pacto entre mí y la tierra.'),
(v_cap_id, 14, 'Y sucederá que cuando haga venir nubes sobre la tierra, se dejará ver entonces mi arco en las nubes.'),
(v_cap_id, 15, 'Y me acordaré del pacto mío, que hay entre mí y vosotros y todo ser viviente de toda carne; y no habrá más diluvio de aguas para destruir toda carne.'),
(v_cap_id, 16, 'Estará el arco en las nubes, y lo veré, y me acordaré del pacto perpetuo entre Dios y todo ser viviente, con toda carne que hay sobre la tierra.'),
(v_cap_id, 17, 'Dijo, pues, Dios a Noé: Esta es la señal del pacto que he establecido entre mí y toda carne que está sobre la tierra.'),
(v_cap_id, 18, 'Y los hijos de Noé que salieron del arca fueron Sem, Cam y Jafet; y Cam es el padre de Canaán.'),
(v_cap_id, 19, 'Estos tres son los hijos de Noé, y de ellos fue llena toda la tierra.'),
(v_cap_id, 20, 'Y comenzó Noé a labrar la tierra, y plantó una viña;'),
(v_cap_id, 21, 'y bebió del vino, y se embriagó, y estaba descubierto en medio de su tienda.'),
(v_cap_id, 22, 'Y Cam, padre de Canaán, vio la desnudez de su padre, y lo dijo a sus dos hermanos que estaban fuera.'),
(v_cap_id, 23, 'Entonces Sem y Jafet tomaron la ropa, y la pusieron sobre sus propios hombros, y andando hacia atrás, cubrieron la desnudez de su padre, teniendo vueltos sus rostros, y así no vieron la desnudez de su padre.'),
(v_cap_id, 24, 'Y despertó Noé de su embriaguez, y supo lo que había hecho su hijo más joven,'),
(v_cap_id, 25, 'y dijo: Maldito sea Canaán; siervo de siervos será a sus hermanos.'),
(v_cap_id, 26, 'Dijo más: Bendito por Jehová mi Dios sea Sem, y Canaán sea su siervo.'),
(v_cap_id, 27, 'Engrandezca Dios a Jafet, y habite en las tiendas de Sem, y sea Canaán su siervo.'),
(v_cap_id, 28, 'Y vivió Noé después del diluvio trescientos cincuenta años.'),
(v_cap_id, 29, 'Y fueron todos los días de Noé novecientos cincuenta años; y murió.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Estas son las generaciones de los hijos de Noé: Sem, Cam y Jafet, a quienes nacieron hijos después del diluvio.'),
(v_cap_id, 2, 'Los hijos de Jafet: Gomer, Magog, Madai, Javán, Tubal, Mesec y Tiras.'),
(v_cap_id, 3, 'Y los hijos de Gomer: Askenaz, Rifat y Togarma.'),
(v_cap_id, 4, 'Y los hijos de Javán: Elisa, Tarsis, Quitim y Dodanim.'),
(v_cap_id, 5, 'De estos se poblaron las costas, cada cual según su lengua, conforme a sus familias en sus naciones.'),
(v_cap_id, 6, 'Los hijos de Cam: Cus, Mizraim, Fut y Canaán.'),
(v_cap_id, 7, 'Y los hijos de Cus: Seba, Havila, Sabta, Raama y Sabteca. Y los hijos de Raama: Seba y Dedán.'),
(v_cap_id, 8, 'Y Cus engendró a Nimrod, quien llegó a ser poderoso en la tierra.'),
(v_cap_id, 9, 'Este fue vigoroso cazador delante de Jehová; por lo cual se dice: Así como Nimrod, vigoroso cazador delante de Jehová.'),
(v_cap_id, 10, 'Y fue el principio de su reino Babel, Erec, Acad y Calne, en la tierra de Sinar.'),
(v_cap_id, 11, 'De esta tierra salió para Asiria, y edificó Nínive, Rehobot, Cala,'),
(v_cap_id, 12, 'y Resén entre Nínive y Cala, la cual es ciudad grande.'),
(v_cap_id, 13, 'Y Mizraim engendró a Ludim, a Anamim, a Lehabim, a Naftuhim,'),
(v_cap_id, 14, 'a Patrusim, a Casluhim, de donde salieron los filisteos, y a Caftorim.'),
(v_cap_id, 15, 'Y Canaán engendró a Sidón, su primogénito, y a Het,'),
(v_cap_id, 16, 'al jebuseo, al amorreo, al gergeseo,'),
(v_cap_id, 17, 'al heveo, al araceo, al sineo,'),
(v_cap_id, 18, 'al arvadeo, al zemareo y al hamateo; y después se dispersaron las familias de los cananeos.'),
(v_cap_id, 19, 'Y fue el territorio de los cananeos desde Sidón, en dirección a Gerar, hasta Gaza; y en dirección de Sodoma, Gomorra, Adma y Zeboim, hasta Lasa.'),
(v_cap_id, 20, 'Estos son los hijos de Cam por sus familias, por sus lenguas, en sus tierras, en sus naciones.'),
(v_cap_id, 21, 'También le nacieron hijos a Sem, padre de todos los hijos de Heber, y hermano mayor de Jafet.'),
(v_cap_id, 22, 'Los hijos de Sem: Elam, Asur, Arfaxad, Lud y Aram.'),
(v_cap_id, 23, 'Y los hijos de Aram: Uz, Hul, Geter y Mas.'),
(v_cap_id, 24, 'Y Arfaxad engendró a Sala, y Sala engendró a Heber.'),
(v_cap_id, 25, 'Y a Heber nacieron dos hijos: el nombre del uno fue Peleg, porque en sus días fue repartida la tierra; y el nombre de su hermano, Joctán.'),
(v_cap_id, 26, 'Y Joctán engendró a Almodad, a Selef, a Hazarmavet, a Jera,'),
(v_cap_id, 27, 'a Adoram, a Uzal, a Dicla,'),
(v_cap_id, 28, 'a Obal, a Abimael, a Seba,'),
(v_cap_id, 29, 'a Ofir, a Havila y a Jobab; todos estos fueron hijos de Joctán.'),
(v_cap_id, 30, 'Y la habitación de ellos fue desde Mesa hasta Sefar, en la región montañosa del oriente.'),
(v_cap_id, 31, 'Estos son los hijos de Sem por sus familias, por sus lenguas, en sus tierras, en sus naciones.'),
(v_cap_id, 32, 'Estas son las familias de los hijos de Noé por sus descendencias, en sus naciones; y de estos se esparcieron las naciones en la tierra después del diluvio.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Tenía entonces toda la tierra una sola lengua y unas mismas palabras.'),
(v_cap_id, 2, 'Y aconteció que cuando salieron de oriente, hallaron una llanura en la tierra de Sinar, y se establecieron allí.'),
(v_cap_id, 3, 'Y se dijeron unos a otros: Vamos, hagamos ladrillo y cozámoslo con fuego. Y les sirvió el ladrillo en lugar de piedra, y el asfalto en lugar de mezcla.'),
(v_cap_id, 4, 'Y dijeron: Vamos, edifiquémonos una ciudad y una torre, cuya cúspide llegue al cielo; y hagámonos un nombre, por si fuéremos esparcidos sobre la faz de toda la tierra.'),
(v_cap_id, 5, 'Y descendió Jehová para ver la ciudad y la torre que edificaban los hijos de los hombres.'),
(v_cap_id, 6, 'Y dijo Jehová: He aquí el pueblo es uno, y todos estos tienen un solo lenguaje; y han comenzado la obra, y nada les hará desistir ahora de lo que han pensado hacer.'),
(v_cap_id, 7, 'Ahora, pues, descendamos, y confundamos allí su lengua, para que ninguno entienda el habla de su compañero.'),
(v_cap_id, 8, 'Así los esparció Jehová desde allí sobre la faz de toda la tierra, y dejaron de edificar la ciudad.'),
(v_cap_id, 9, 'Por esto fue llamado el nombre de ella Babel, porque allí confundió Jehová el lenguaje de toda la tierra, y desde allí los esparció sobre la faz de toda la tierra.'),
(v_cap_id, 10, 'Estas son las generaciones de Sem: Sem, de edad de cien años, engendró a Arfaxad, dos años después del diluvio.'),
(v_cap_id, 11, 'Y vivió Sem, después que engendró a Arfaxad, quinientos años, y engendró hijos e hijas.'),
(v_cap_id, 12, 'Arfaxad vivió treinta y cinco años, y engendró a Sala.'),
(v_cap_id, 13, 'Y vivió Arfaxad, después que engendró a Sala, cuatrocientos tres años, y engendró hijos e hijas.'),
(v_cap_id, 14, 'Sala vivió treinta años, y engendró a Heber.'),
(v_cap_id, 15, 'Y vivió Sala, después que engendró a Heber, cuatrocientos tres años, y engendró hijos e hijas.'),
(v_cap_id, 16, 'Heber vivió treinta y cuatro años, y engendró a Peleg.'),
(v_cap_id, 17, 'Y vivió Heber, después que engendró a Peleg, cuatrocientos treinta años, y engendró hijos e hijas.'),
(v_cap_id, 18, 'Peleg vivió treinta años, y engendró a Reu.'),
(v_cap_id, 19, 'Y vivió Peleg, después que engendró a Reu, doscientos nueve años, y engendró hijos e hijas.'),
(v_cap_id, 20, 'Reu vivió treinta y dos años, y engendró a Serug.'),
(v_cap_id, 21, 'Y vivió Reu, después que engendró a Serug, doscientos siete años, y engendró hijos e hijas.'),
(v_cap_id, 22, 'Serug vivió treinta años, y engendró a Nacor.'),
(v_cap_id, 23, 'Y vivió Serug, después que engendró a Nacor, doscientos años, y engendró hijos e hijas.'),
(v_cap_id, 24, 'Nacor vivió veintinueve años, y engendró a Taré.'),
(v_cap_id, 25, 'Y vivió Nacor, después que engendró a Taré, ciento diecinueve años, y engendró hijos e hijas.'),
(v_cap_id, 26, 'Y vivió Taré setenta años, y engendró a Abram, a Nacor y a Harán.'),
(v_cap_id, 27, 'Estas son las generaciones de Taré: Taré engendró a Abram, a Nacor y a Harán; y Harán engendró a Lot.'),
(v_cap_id, 28, 'Y murió Harán antes que su padre Taré en la tierra de su nacimiento, en Ur de los caldeos.'),
(v_cap_id, 29, 'Y Abram y Nacor tomaron para sí mujeres; el nombre de la mujer de Abram era Sarai, y el nombre de la mujer de Nacor, Milca, hija de Harán, que fue padre de Milca y de Isca.'),
(v_cap_id, 30, 'Mas Sarai era estéril, y no tenía hijo.'),
(v_cap_id, 31, 'Y tomó Taré a Abram su hijo, y a Lot hijo de Harán, hijo de su hijo, y a Sarai su nuera, mujer de Abram su hijo, y salió con ellos de Ur de los caldeos, para ir a la tierra de Canaán; y vinieron hasta Harán, y se quedaron allí.'),
(v_cap_id, 32, 'Y fueron los días de Taré doscientos cinco años; y murió Taré en Harán.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Pero Jehová había dicho a Abram: Vete de tu tierra y de tu parentela, y de la casa de tu padre, a la tierra que te mostraré.'),
(v_cap_id, 2, 'Y haré de ti una nación grande, y te bendeciré, y engrandeceré tu nombre, y serás bendición.'),
(v_cap_id, 3, 'Bendeciré a los que te bendijeren, y a los que te maldijeren maldeciré; y serán benditas en ti todas las familias de la tierra.'),
(v_cap_id, 4, 'Y se fue Abram, como Jehová le dijo; y Lot fue con él. Y era Abram de edad de setenta y cinco años cuando salió de Harán.'),
(v_cap_id, 5, 'Tomó, pues, Abram a Sarai su mujer, y a Lot hijo de su hermano, y todos sus bienes que habían ganado y las personas que habían adquirido en Harán, y salieron para ir a tierra de Canaán; y a tierra de Canaán llegaron.'),
(v_cap_id, 6, 'Y pasó Abram por aquella tierra hasta el lugar de Siquem, hasta el encino de More; y el cananeo estaba entonces en la tierra.'),
(v_cap_id, 7, 'Y apareció Jehová a Abram, y le dijo: A tu descendencia daré esta tierra. Y edificó allí un altar a Jehová, quien le había aparecido.'),
(v_cap_id, 8, 'Luego se pasó de allí a un monte al oriente de Betel, y levantó su tienda, teniendo a Betel al occidente y a Hai al oriente; y edificó allí altar a Jehová, e invocó el nombre de Jehová.'),
(v_cap_id, 9, 'Y Abram partió de allí, caminando y yendo hacia el Neguev.'),
(v_cap_id, 10, 'Hubo entonces hambre en la tierra, y descendió Abram a Egipto para morar allá; porque era grande el hambre en la tierra.'),
(v_cap_id, 11, 'Y aconteció que cuando estaba para entrar en Egipto, dijo a Sarai su mujer: He aquí, ahora conozco que eres mujer de hermoso aspecto;'),
(v_cap_id, 12, 'y cuando te vean los egipcios, dirán: Su mujer es; y me matarán a mí, y a ti te reservarán la vida.'),
(v_cap_id, 13, 'Ahora, pues, di que eres mi hermana, para que me vaya bien por causa tuya, y viva mi alma por causa de ti.'),
(v_cap_id, 14, 'Y aconteció que cuando entró Abram en Egipto, los egipcios vieron que la mujer era hermosa en gran manera.'),
(v_cap_id, 15, 'También la vieron los príncipes de Faraón, y la alabaron delante de él; y fue llevada la mujer a casa de Faraón.'),
(v_cap_id, 16, 'E hizo bien a Abram por causa de ella; y él tuvo ovejas, vacas, asnos, siervos, siervas, asnas y camellos.'),
(v_cap_id, 17, 'Mas Jehová hirió a Faraón y a su casa con grandes plagas, por causa de Sarai mujer de Abram.'),
(v_cap_id, 18, 'Entonces Faraón llamó a Abram y le dijo: ¿Qué es esto que has hecho conmigo? ¿Por qué no me declaraste que era tu mujer?'),
(v_cap_id, 19, '¿Por qué dijiste: Es mi hermana, poniéndome en ocasión de tomarla para mí por mujer? Ahora, pues, he aquí tu mujer, tómala, y vete.'),
(v_cap_id, 20, 'Entonces Faraón dio orden a su gente acerca de Abram; y le acompañaron, y a su mujer, con todo lo que tenía.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Subió, pues, Abram de Egipto hacia el Neguev, él y su mujer, y todo lo que tenía, y con él Lot.'),
(v_cap_id, 2, 'Y Abram era riquísimo en ganado, en plata y en oro.'),
(v_cap_id, 3, 'Y volvió por sus jornadas desde el Neguev hasta Betel, hasta el lugar donde había estado antes su tienda entre Betel y Hai,'),
(v_cap_id, 4, 'al lugar del altar que había hecho allí antes; e invocó allí Abram el nombre de Jehová.'),
(v_cap_id, 5, 'Y también Lot, que andaba con Abram, tenía ovejas, vacas y tiendas.'),
(v_cap_id, 6, 'Y la tierra no era suficiente para que habitasen juntos, porque sus posesiones eran muchas, y no podían morar en un mismo lugar.'),
(v_cap_id, 7, 'Y hubo contienda entre los pastores del ganado de Abram y los pastores del ganado de Lot; y el cananeo y el ferezeo habitaban entonces en la tierra.'),
(v_cap_id, 8, 'Entonces Abram dijo a Lot: No haya ahora altercado entre mí y ti, entre mis pastores y los tuyos, porque somos hermanos.'),
(v_cap_id, 9, '¿No está toda la tierra delante de ti? Sepárate ahora de mí: si fueres a la mano izquierda, yo iré a la derecha; y si tú a la derecha, yo iré a la izquierda.'),
(v_cap_id, 10, 'Y alzó Lot sus ojos, y vio toda la llanura del Jordán, que toda ella era de riego, como el huerto de Jehová, como la tierra de Egipto, en la dirección de Zoar, antes que destruyese Jehová a Sodoma y a Gomorra.'),
(v_cap_id, 11, 'Entonces Lot escogió para sí toda la llanura del Jordán, y se fue Lot hacia el oriente. Y se apartaron el uno del otro.'),
(v_cap_id, 12, 'Abram acampó en la tierra de Canaán, y Lot habitó en las ciudades de la llanura, y fue poniendo sus tiendas hasta Sodoma.'),
(v_cap_id, 13, 'Y los hombres de Sodoma eran malos y pecadores contra Jehová en gran manera.'),
(v_cap_id, 14, 'Y Jehová dijo a Abram, después que Lot se apartó de él: Alza ahora tus ojos, y mira desde el lugar donde estás hacia el norte y el sur, y al oriente y al occidente.'),
(v_cap_id, 15, 'Porque toda la tierra que ves, la daré a ti y a tu descendencia para siempre.'),
(v_cap_id, 16, 'Haré tu descendencia como el polvo de la tierra; que si alguno puede contar el polvo de la tierra, también tu descendencia será contada.'),
(v_cap_id, 17, 'Levántate, ve por la tierra a lo largo de ella y a su ancho; porque a ti la daré.'),
(v_cap_id, 18, 'Abram, pues, removiendo su tienda, vino y moró en el encinar de Mamre, que está en Hebrón, y edificó allí altar a Jehová.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Aconteció en los días de Amrafel rey de Sinar, Arioc rey de Elasar, Quedorlaomer rey de Elam, y Tidal rey de Goim,'),
(v_cap_id, 2, 'que estos hicieron guerra contra Bera rey de Sodoma, contra Birsa rey de Gomorra, contra Sinab rey de Adma, contra Semeber rey de Zeboim, y contra el rey de Bela, la cual es Zoar.'),
(v_cap_id, 3, 'Todos estos se juntaron en el valle de Sidim, que es el Mar Salado.'),
(v_cap_id, 4, 'Doce años habían servido a Quedorlaomer, y en el decimotercio año se rebelaron.'),
(v_cap_id, 5, 'Y en el año decimocuarto vino Quedorlaomer y los reyes que estaban de su parte, y derrotaron a los refaítas en Astarot Karnaim, a los zuzitas en Ham, a los emitas en Save-quiriataim,'),
(v_cap_id, 6, 'y a los hurritas en el monte de Seir, hasta la llanura de Parán, que está junto al desierto.'),
(v_cap_id, 7, 'Y volvieron y vinieron a En-mispat, que es Cades, y devastaron todo el país de los amalecitas, y también al amorreo que habitaba en Hazezon-tamar.'),
(v_cap_id, 8, 'Y salieron el rey de Sodoma, el rey de Gomorra, el rey de Adma, el rey de Zeboim y el rey de Bela, que es Zoar, y ordenaron batalla contra ellos en el valle de Sidim;'),
(v_cap_id, 9, 'esto es, contra Quedorlaomer rey de Elam, Tidal rey de Goim, Amrafel rey de Sinar, y Arioc rey de Elasar; cuatro reyes contra cinco.'),
(v_cap_id, 10, 'Y el valle de Sidim estaba lleno de pozos de asfalto; y cuando huyeron el rey de Sodoma y el de Gomorra, cayeron allí; y los demás huyeron al monte.'),
(v_cap_id, 11, 'Y tomaron toda la riqueza de Sodoma y de Gomorra, y todas sus provisiones, y se fueron.'),
(v_cap_id, 12, 'También tomaron a Lot, hijo del hermano de Abram, que moraba en Sodoma, y sus bienes, y se fueron.'),
(v_cap_id, 13, 'Y uno de los que escaparon vino y lo anunció a Abram el hebreo, que habitaba en el encinar de Mamre el amorreo, hermano de Escol y hermano de Aner, los cuales eran aliados de Abram.'),
(v_cap_id, 14, 'Oyó Abram que su hermano estaba prisionero, y armó a sus criados, los nacidos en su casa, trescientos dieciocho, y los siguió hasta Dan.'),
(v_cap_id, 15, 'Y los atacó de noche, él y sus siervos, y los derrotó, y los persiguió hasta Hoba, que está al norte de Damasco.'),
(v_cap_id, 16, 'Y recobró todos los bienes, y también a Lot su hermano y sus bienes, y también a las mujeres y demás gente.'),
(v_cap_id, 17, 'Cuando volvía de la derrota de Quedorlaomer y de los reyes que con él estaban, salió el rey de Sodoma a recibirlo al valle de Save, que es el Valle del Rey.'),
(v_cap_id, 18, 'Entonces Melquisedec, rey de Salem, y sacerdote del Dios Altísimo, sacó pan y vino;'),
(v_cap_id, 19, 'y le bendijo, diciendo: Bendito sea Abram del Dios Altísimo, creador de los cielos y de la tierra;'),
(v_cap_id, 20, 'y bendito sea el Dios Altísimo, que entregó tus enemigos en tu mano. Y le dio Abram los diezmos de todo.'),
(v_cap_id, 21, 'Y el rey de Sodoma dijo a Abram: Dame las personas, y toma para ti los bienes.'),
(v_cap_id, 22, 'Y respondió Abram al rey de Sodoma: He alzado mi mano a Jehová Dios Altísimo, creador de los cielos y de la tierra,'),
(v_cap_id, 23, 'que desde un hilo hasta una correa de calzado, nada tomaré de todo lo que es tuyo, para que no digas: Yo enriquecí a Abram.'),
(v_cap_id, 24, 'Solamente lo que comieron los jóvenes, y la porción de los varones que fueron conmigo, Aner, Escol y Mamre, los cuales tomarán su parte.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Después de estas cosas vino la palabra de Jehová a Abram en visión, diciendo: No temas, Abram; yo soy tu escudo, y tu galardón sobremanera grande.'),
(v_cap_id, 2, 'Y respondió Abram: Señor Jehová, ¿qué me darás, siendo así que ando sin hijo, y el mayordomo de mi casa es ese damasceno Eliezer?'),
(v_cap_id, 3, 'Dijo también Abram: Mira que no me has dado descendencia, y he aquí que será mi heredero un esclavo nacido en mi casa.'),
(v_cap_id, 4, 'Luego vino a él palabra de Jehová, diciendo: No te heredará éste, sino que uno que saldrá de tus entrañas será el que te herede.'),
(v_cap_id, 5, 'Y lo llevó fuera, y le dijo: Mira ahora los cielos, y cuenta las estrellas, si las puedes contar. Y le dijo: Así será tu descendencia.'),
(v_cap_id, 6, 'Y creyó a Jehová, y le fue contado por justicia.'),
(v_cap_id, 7, 'Y le dijo: Yo soy Jehová, que te saqué de Ur de los caldeos, para darte a heredar esta tierra.'),
(v_cap_id, 8, 'Y él respondió: Señor Jehová, ¿en qué conoceré que la he de heredar?'),
(v_cap_id, 9, 'Y le dijo: Tráeme una becerra de tres años, y una cabra de tres años, y un carnero de tres años, una tórtola también, y un palomino.'),
(v_cap_id, 10, 'Y tomó él todos estos, y los partió por la mitad, y puso cada mitad una enfrente de la otra; mas no partió las aves.'),
(v_cap_id, 11, 'Y descendían aves de rapiña sobre los cuerpos muertos, y Abram las ahuyentaba.'),
(v_cap_id, 12, 'Mas a la caída del sol sobrecogió el sueño a Abram, y he aquí que el temor de una grande oscuridad cayó sobre él.'),
(v_cap_id, 13, 'Entonces Jehová dijo a Abram: Ten por cierto que tu descendencia morará en tierra ajena, y será esclava allí, y será oprimida cuatrocientos años.'),
(v_cap_id, 14, 'Mas también a la nación a la cuales sirvieren, juzgaré yo; y después de esto saldrán con gran riqueza.'),
(v_cap_id, 15, 'Y tú vendrás a tus padres en paz, y serás sepultado en buena vejez.'),
(v_cap_id, 16, 'Y en la cuarta generación volverán acá; porque aún no ha llegado a su colmo la maldad del amorreo.'),
(v_cap_id, 17, 'Y sucedió que puesto el sol, y ya oscurecido, se veía un horno humeando, y una antorcha de fuego que pasaba por entre los animales divididos.'),
(v_cap_id, 18, 'En aquel día hizo Jehová un pacto con Abram, diciendo: A tu descendencia daré esta tierra, desde el río de Egipto hasta el río grande, el río Eufrates;'),
(v_cap_id, 19, 'la tierra de los ceneos, los cenezeos, los cadmoneos,'),
(v_cap_id, 20, 'los heteos, los ferezeos, los refaítas,'),
(v_cap_id, 21, 'los amorreos, los cananeos, los gergeseos y los jebuseos.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Sarai mujer de Abram no le daba hijos; y ella tenía una sierva egipcia, que se llamaba Agar.'),
(v_cap_id, 2, 'Dijo, pues, Sarai a Abram: Ya ves que Jehová me ha hecho estéril; te ruego, pues, que te llegues a mi sierva; quizá tendré hijos de ella. Y atendió Abram al ruego de Sarai.'),
(v_cap_id, 3, 'Y Sarai, mujer de Abram, tomó a Agar su sierva egipcia, al cabo de diez años que había habitado Abram en la tierra de Canaán, y la dio por mujer a Abram su marido.'),
(v_cap_id, 4, 'Y él se llegó a Agar, la cual concibió; y cuando vio que había concebido, miraba con desprecio a su señora.'),
(v_cap_id, 5, 'Entonces Sarai dijo a Abram: Mi afrenta sea sobre ti: yo puse mi sierva en tu seno, y viéndose encinta, me desprecia; juzgue Jehová entre mí y ti.'),
(v_cap_id, 6, 'Y respondió Abram a Sarai: He aquí, tu sierva está en tu mano; haz con ella lo que bien te parezca. Y cuando Sarai la afligía, ella huyó de su presencia.'),
(v_cap_id, 7, 'Y la halló el ángel de Jehová junto a una fuente de agua en el desierto, junto a la fuente que está en el camino de Shur.'),
(v_cap_id, 8, 'Y le dijo: Agar, sierva de Sarai, ¿de dónde vienes tú, y a dónde vas? Y ella respondió: Huyo de delante de Sarai mi señora.'),
(v_cap_id, 9, 'Y le dijo el ángel de Jehová: Vuélvete a tu señora, y ponte sumisa bajo su mano.'),
(v_cap_id, 10, 'Le dijo también el ángel de Jehová: Multiplicaré tanto tu descendencia, que no podrá ser contada a causa de la multitud.'),
(v_cap_id, 11, 'Además le dijo el ángel de Jehová: Has concebido, y darás a luz un hijo; y llamarás su nombre Ismael, porque Jehová ha oído tu aflicción.'),
(v_cap_id, 12, 'Y él será hombre fiero; su mano será contra todos, y la mano de todos contra él, y delante de todos sus hermanos habitará.'),
(v_cap_id, 13, 'Entonces llamó el nombre de Jehová que con ella hablaba: Tú eres Dios que ve; porque dijo: ¿No he visto también aquí al que me ve?'),
(v_cap_id, 14, 'Por lo cual llamó al pozo: Pozo del Viviente-que-me-ve. He aquí está entre Cades y Bered.'),
(v_cap_id, 15, 'Y Agar dio a luz un hijo a Abram, y llamó Abram el nombre del hijo que le dio Agar, Ismael.'),
(v_cap_id, 16, 'Era Abram de edad de ochenta y seis años, cuando Agar dio a luz a Ismael.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Era Abram de edad de noventa y nueve años, cuando le apareció Jehová y le dijo: Yo soy el Dios Todopoderoso; anda delante de mí y sé perfecto.'),
(v_cap_id, 2, 'Y pondré mi pacto entre mí y ti, y te multiplicaré sobremanera.'),
(v_cap_id, 3, 'Entonces Abram se postró sobre su rostro, y Dios habló con él, diciendo:'),
(v_cap_id, 4, 'He aquí mi pacto es contigo, y serás padre de muchedumbre de gentes.'),
(v_cap_id, 5, 'Y no se llamará más tu nombre Abram, sino que tu nombre será Abraham, porque te he puesto por padre de muchedumbre de gentes.'),
(v_cap_id, 6, 'Y te multiplicaré en gran manera, y haré naciones de ti, y reyes saldrán de ti.'),
(v_cap_id, 7, 'Y estableceré mi pacto entre mí y ti, y tu descendencia después de ti en sus generaciones, por pacto perpetuo, para ser tu Dios, y el de tu descendencia después de ti.'),
(v_cap_id, 8, 'Y te daré a ti, y a tu descendencia después de ti, la tierra en que moras, toda la tierra de Canaán en heredad perpetua; y seré el Dios de ellos.'),
(v_cap_id, 9, 'Dijo de nuevo Dios a Abraham: En cuanto a ti, guardarás mi pacto, tú y tu descendencia después de ti por sus generaciones.'),
(v_cap_id, 10, 'Este es mi pacto, que guardaréis entre mí y vosotros y tu descendencia después de ti: Será circuncidado todo varón de entre vosotros.'),
(v_cap_id, 11, 'Circuncidaréis, pues, la carne de vuestro prepucio, y será por señal del pacto entre mí y vosotros.'),
(v_cap_id, 12, 'Y de edad de ocho días será circuncidado todo varón entre vosotros por vuestras generaciones; el nacido en casa, y el comprado por dinero a cualquier extranjero, que no fuere de tu descendencia.'),
(v_cap_id, 13, 'Deberá ser circuncidado el nacido en tu casa, y el comprado por tu dinero; y estará mi pacto en vuestra carne por pacto perpetuo.'),
(v_cap_id, 14, 'Y el varón incircunciso, el que no hubiere circuncidado la carne de su prepucio, aquella persona será cortada de su pueblo; ha violado mi pacto.'),
(v_cap_id, 15, 'Dijo también Dios a Abraham: A Sarai tu mujer no la llamarás Sarai, mas Sara será su nombre.'),
(v_cap_id, 16, 'Y la bendeciré, y también te daré de ella hijo; sí, la bendeciré, y vendrá a ser madre de naciones; reyes de pueblos vendrán de ella.'),
(v_cap_id, 17, 'Entonces Abraham se postró sobre su rostro, y se rió, y dijo en su corazón: ¿A hombre de cien años ha de nacer hijo? ¿Y Sara, ya de noventa años, ha de concebir?'),
(v_cap_id, 18, 'Y dijo Abraham a Dios: Ojalá Ismael viva delante de ti.'),
(v_cap_id, 19, 'Respondió Dios: Ciertamente Sara tu mujer te dará a luz un hijo, y llamarás su nombre Isaac; y confirmaré el pacto con él como pacto perpetuo para su descendencia después de él.'),
(v_cap_id, 20, 'Y en cuanto a Ismael, también te he oído; he aquí que le bendeciré, y le haré fructificar y multiplicará mucho en gran manera; doce príncipes engendrará, y haré de él una gran nación.'),
(v_cap_id, 21, 'Mas mi pacto lo estableceré con Isaac, el que te dará Sara por hijo este tiempo próximo.'),
(v_cap_id, 22, 'Y acabó de hablar con él, y subió Dios de estar con Abraham.'),
(v_cap_id, 23, 'Entonces Abraham tomó a Ismael su hijo, y a todos los siervos nacidos en su casa, y a todos los comprados por su dinero, a todo varón entre los domésticos de la casa de Abraham, y circuncidó la carne del prepucio de ellos en aquel mismo día, como Dios le había dicho.'),
(v_cap_id, 24, 'Era Abraham de edad de noventa y nueve años cuando circuncidó la carne de su prepucio.'),
(v_cap_id, 25, 'E Ismael su hijo era de trece años, cuando fue circuncidada la carne de su prepucio.'),
(v_cap_id, 26, 'En el mismo día fueron circuncidados Abraham e Ismael su hijo.'),
(v_cap_id, 27, 'Y todos los varones de su casa, el siervo nacido en casa, y el comprado del extranjero por dinero, fueron circuncidados con él.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Después le apareció Jehová en el encinar de Mamre, estando él sentado a la puerta de su tienda en el calor del día.'),
(v_cap_id, 2, 'Y alzó sus ojos y miró, y he aquí tres varones que estaban junto a él; y cuando los vio, salió corriendo de la puerta de su tienda a recibirlos, y se postró en tierra,'),
(v_cap_id, 3, 'y dijo: Señor, si ahora he hallado gracia en tus ojos, te ruego que no pases de tu siervo.'),
(v_cap_id, 4, 'Que se traiga ahora un poco de agua, y lavad vuestros pies; y recostaos debajo de un árbol,'),
(v_cap_id, 5, 'y traeré un bocado de pan, y sustentad vuestro corazón, y después pasaréis; pues por eso habéis pasado cerca de vuestro siervo. Y ellos dijeron: Haz así como has dicho.'),
(v_cap_id, 6, 'Entonces Abraham fue de prisa a la tienda a Sara, y le dijo: Toma pronto tres medidas de flor de harina, y amasa y haz panes cocidos debajo del rescoldo.'),
(v_cap_id, 7, 'Y corrió Abraham a las vacas, y tomó un becerro tierno y bueno, y lo dio al criado, y éste se dio prisa a aderezarlo.'),
(v_cap_id, 8, 'Tomó también mantequilla y leche, y el becerro que había aderezado, y lo puso delante de ellos; y él estaba junto a ellos debajo del árbol; y comieron.'),
(v_cap_id, 9, 'Y le dijeron: ¿Dónde está Sara tu mujer? Y él respondió: Aquí en la tienda.'),
(v_cap_id, 10, 'Entonces dijo: De cierto volveré a ti; y según el tiempo de la vida, he aquí que Sara tu mujer tendrá un hijo. Y Sara escuchaba a la puerta de la tienda, que estaba detrás de él.'),
(v_cap_id, 11, 'Y Abraham y Sara eran viejos, de edad avanzada; y a Sara le había cesado ya la costumbre de las mujeres.'),
(v_cap_id, 12, 'Se rió, pues, Sara entre sí, diciendo: ¿Después que he envejecido tendré deleite, siendo también mi señor viejo?'),
(v_cap_id, 13, 'Entonces Jehová dijo a Abraham: ¿Por qué se ha reído Sara diciendo: ¿Será cierto que he de dar a luz siendo ya vieja?'),
(v_cap_id, 14, '¿Hay para Dios alguna cosa difícil? Al tiempo señalado volveré a ti, y según el tiempo de la vida, Sara tendrá un hijo.'),
(v_cap_id, 15, 'Entonces Sara negó, diciendo: No me reí; porque tuvo miedo. Y él dijo: No es así, sino que te has reído.'),
(v_cap_id, 16, 'Y los varones se levantaron de allí, y miraron hacia Sodoma; y Abraham iba con ellos acompañándolos.'),
(v_cap_id, 17, 'Y Jehová dijo: ¿Encubriré yo a Abraham lo que voy a hacer,'),
(v_cap_id, 18, 'habiendo de ser Abraham una nación grande y fuerte, y habiendo de ser benditas en él todas las naciones de la tierra?'),
(v_cap_id, 19, 'Porque yo lo he conocido, sé que mandará a sus hijos y a su casa después de sí, que guarden el camino de Jehová, haciendo justicia y juicio, para que haga venir Jehová sobre Abraham lo que ha hablado acerca de él.'),
(v_cap_id, 20, 'Entonces Jehová le dijo: Por cuanto el clamor contra Sodoma y Gomorra se aumenta más y más, y el pecado de ellos se ha agravado en extremo,'),
(v_cap_id, 21, 'descenderé ahora, y veré si han consumado su obra según el clamor que ha venido hasta mí; y si no, lo sabré.'),
(v_cap_id, 22, 'Y se apartaron de allí los varones, y fueron hacia Sodoma; pero Abraham estaba aún delante de Jehová.'),
(v_cap_id, 23, 'Y se acercó Abraham y dijo: ¿Destruirás también al justo con el impío?'),
(v_cap_id, 24, 'Quizá haya cincuenta justos dentro de la ciudad; ¿destruirás también y no perdonarás el lugar por amor a los cincuenta justos que están dentro de él?'),
(v_cap_id, 25, 'Lejos de ti el hacer tal, que hagas morir al justo con el impío, y que sea el justo tratado como el impío; nunca tal hagas. El juez de toda la tierra, ¿no ha de hacer lo que es justo?'),
(v_cap_id, 26, 'Entonces respondió Jehová: Si hallare en Sodoma cincuenta justos dentro de la ciudad, perdonaré a todo este lugar por amor a ellos.'),
(v_cap_id, 27, 'Y Abraham replicó y dijo: He aquí ahora que he comenzado a hablar a mi Señor, siendo polvo y ceniza;'),
(v_cap_id, 28, 'quizá faltarán de cincuenta justos cinco; ¿destruirás por aquellos cinco toda la ciudad? Y dijo: No la destruiré, si hallare allí cuarenta y cinco.'),
(v_cap_id, 29, 'Y volvió a hablarle, y dijo: Quizá se hallarán allí cuarenta. Y respondió: No lo haré por amor a los cuarenta.'),
(v_cap_id, 30, 'Y dijo: No se enoje ahora mi Señor, si hablare: quizá se hallarán allí treinta. Y respondió: No lo haré si hallare allí treinta.'),
(v_cap_id, 31, 'Y dijo: He aquí ahora que he emprendido el hablar a mi Señor: quizá se hallarán allí veinte. Y respondió: No la destruiré por amor a los veinte.'),
(v_cap_id, 32, 'Y dijo: No se enoje ahora mi Señor, si hablare solamente una vez: quizá se hallarán allí diez. Y respondió: No la destruiré por amor a los diez.'),
(v_cap_id, 33, 'Y Jehová se fue, luego que acabó de hablar a Abraham; y Abraham volvió a su lugar.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Llegaron, pues, los dos ángeles a Sodoma a la caída de la tarde; y Lot estaba sentado a la puerta de Sodoma. Y viéndolos Lot, se levantó a recibirlos, y se inclinó hacia el suelo,'),
(v_cap_id, 2, 'y dijo: Ahora, mis señores, os ruego que vengáis a casa de vuestro siervo para que os hospedéis, y lavaréis vuestros pies; y por la mañana os levantaréis y seguiréis vuestro camino. Y ellos respondieron: No, que en la calle nos quedaremos esta noche.'),
(v_cap_id, 3, 'Mas él porfió con ellos mucho, y fueron con él, y entraron en su casa; y les hizo banquete, e hizo cocer panes sin levadura, y comieron.'),
(v_cap_id, 4, 'Pero antes que se acostasen, rodearon la casa los hombres de la ciudad, los varones de Sodoma, todo el pueblo junto, desde el más joven hasta el más viejo.'),
(v_cap_id, 5, 'Y llamaron a Lot, y le dijeron: ¿Dónde están los varones que vinieron a ti esta noche? Sácalos, para que los conozcamos.'),
(v_cap_id, 6, 'Entonces Lot salió a ellos a la puerta, y cerró la puerta tras sí,'),
(v_cap_id, 7, 'y dijo: Os ruego, hermanos míos, que no hagáis tal maldad.'),
(v_cap_id, 8, 'He aquí ahora yo tengo dos hijas que no han conocido varón; os las sacaré fuera, y haced de ellas como bien os pareciere; solamente que a estos varones no hagáis nada, pues que vinieron a la sombra de mi tejado.'),
(v_cap_id, 9, 'Y ellos respondieron: Quita allá; y añadieron: Vino este extraño para morar entre nosotros, ¿y habrá de erigirse en juez? Ahora te haremos más mal que a ellos. Y hacían gran violencia al varón, a Lot, y se acercaron para romper la puerta.'),
(v_cap_id, 10, 'Entonces los varones extendieron la mano, y metieron a Lot en casa con ellos, y cerraron la puerta.'),
(v_cap_id, 11, 'Y a los hombres que estaban a la puerta de la casa hirieron con ceguera desde el menor hasta el mayor, de manera que se fatigaban por hallar la puerta.'),
(v_cap_id, 12, 'Y dijeron los varones a Lot: ¿Tienes aquí alguno más? Yernos, y tus hijos y tus hijas, y todo lo que tienes en la ciudad, sácalo de este lugar;'),
(v_cap_id, 13, 'porque vamos a destruir este lugar, por cuanto el clamor contra ellos ha subido de punto delante de Jehová; por tanto, Jehová nos ha enviado para destruirlo.'),
(v_cap_id, 14, 'Entonces salió Lot y habló a sus yernos, los que habían de tomar sus hijas, y les dijo: Levantaos, salid de este lugar; porque Jehová va a destruir esta ciudad. Mas pareció a sus yernos como que se burlaba.'),
(v_cap_id, 15, 'Y al rayar el alba, los ángeles daban prisa a Lot, diciendo: Levántate, toma tu mujer, y tus dos hijas que se hallan aquí, para que no perezcas en el castigo de la ciudad.'),
(v_cap_id, 16, 'Y deteniéndose él, los varones asieron de su mano, y de la mano de su mujer, y de las manos de sus dos hijas, según la misericordia de Jehová para con él; y lo sacaron y lo pusieron fuera de la ciudad.'),
(v_cap_id, 17, 'Y cuando lo hubieron llevado fuera, dijeron: Escapa por tu vida; no mires tras ti, ni pares en toda la llanura; escapa al monte, no sea que perezcas.'),
(v_cap_id, 18, 'Pero Lot les dijo: No, yo os ruego, señores míos.'),
(v_cap_id, 19, 'He aquí ahora ha hallado tu siervo gracia en tus ojos, y has engrandecido tu misericordia que has hecho conmigo dándome la vida; mas yo no podré escapar al monte, no sea que me alcance el mal, y muera.'),
(v_cap_id, 20, 'He aquí ahora esta ciudad está cerca para huir allá, la cual es pequeña; déjame escapar ahora allá (¿no es ella pequeña?), y salvaré mi vida.'),
(v_cap_id, 21, 'Y le respondió: He aquí, he recibido también tu súplica acerca de esto, y no destruiré la ciudad de que has hablado.'),
(v_cap_id, 22, 'Date prisa, escápate allá; porque nada puedo hacer hasta que hayas llegado allí. Por eso fue llamado el nombre de la ciudad, Zoar.'),
(v_cap_id, 23, 'El sol salía sobre la tierra, cuando Lot llegó a Zoar.'),
(v_cap_id, 24, 'Entonces Jehová hizo llover sobre Sodoma y sobre Gomorra azufre y fuego de parte de Jehová desde los cielos;'),
(v_cap_id, 25, 'y destruyó las ciudades, y toda aquella llanura, con todos los moradores de aquellas ciudades, y el fruto de la tierra.'),
(v_cap_id, 26, 'Entonces la mujer de Lot miró atrás, a espaldas de él, y se volvió estatua de sal.'),
(v_cap_id, 27, 'Y subió Abraham por la mañana al lugar donde había estado delante de Jehová.'),
(v_cap_id, 28, 'Y miró hacia Sodoma y Gomorra, y hacia toda la tierra de aquella llanura; y vio, y he aquí que el humo subía de la tierra como el humo de un horno.'),
(v_cap_id, 29, 'Así, cuando destruyó Dios las ciudades de la llanura, Dios se acordó de Abraham, y envió fuera a Lot de en medio de la destrucción, al asolar las ciudades donde Lot estaba.'),
(v_cap_id, 30, 'Pero Lot subió de Zoar y moró en el monte, y sus dos hijas con él; porque tuvo miedo de quedarse en Zoar, y habitó en una cueva él y sus dos hijas.'),
(v_cap_id, 31, 'Entonces la mayor dijo a la menor: Nuestro padre es viejo, y no queda varón en la tierra que entre a nosotras conforme a la costumbre de toda la tierra.'),
(v_cap_id, 32, 'Ven, demos a beber vino a nuestro padre, y durmamos con él, y conservaremos de nuestro padre descendencia.'),
(v_cap_id, 33, 'Y dieron a beber vino a su padre aquella noche, y entró la mayor, y durmió con su padre; y él no sintió cuándo ella se acostó, ni cuándo se levantó.'),
(v_cap_id, 34, 'El día siguiente, dijo la mayor a la menor: He aquí, yo dormí la noche pasada con mi padre; démosle a beber vino también esta noche, y entra y duerme con él, y conservaremos de nuestro padre descendencia.'),
(v_cap_id, 35, 'Y dieron a beber vino a su padre también aquella noche, y se levantó la menor y durmió con él; y él no supo cuándo ella se acostó, ni cuándo se levantó.'),
(v_cap_id, 36, 'Y las dos hijas de Lot concibieron de su padre.'),
(v_cap_id, 37, 'Y dio a luz la mayor un hijo, y llamó su nombre Moab, el cual es padre de los moabitas hasta hoy.'),
(v_cap_id, 38, 'Y la menor también dio a luz un hijo, y llamó su nombre Ben-ammí, el cual es padre de los amonitas hasta hoy.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'De allí partió Abraham a la tierra del Neguev, y acampó entre Cades y Shur, y habitó como forastero en Gerar.'),
(v_cap_id, 2, 'Y dijo Abraham de Sara su mujer: Es mi hermana. Y Abimelec rey de Gerar envió y tomó a Sara.'),
(v_cap_id, 3, 'Pero Dios vino a Abimelec en sueños de noche, y le dijo: He aquí, muerto eres a causa de la mujer que has tomado, la cual es casada con marido.'),
(v_cap_id, 4, 'Mas Abimelec no se había llegado a ella, y dijo: Señor, ¿matarás también al justo?'),
(v_cap_id, 5, '¿No me dijo él: Mi hermana es; y ella también dijo: Es mi hermano? Con integridad de mi corazón y con limpieza de mis manos he hecho esto.'),
(v_cap_id, 6, 'Y le dijo Dios en sueños: Yo también sé que con integridad de tu corazón has hecho esto; y yo también te detuve de pecar contra mí, y así no te permití que la tocases.'),
(v_cap_id, 7, 'Ahora, pues, devuelve la mujer a su marido, porque es profeta, y orará por ti, y vivirás. Y si no la devolvieres, sabe que de cierto morirás tú y todos los tuyos.'),
(v_cap_id, 8, 'Entonces Abimelec se levantó de mañana, y llamó a todos sus siervos, y dijo todas estas palabras en los oídos de ellos; y los hombres temieron en gran manera.'),
(v_cap_id, 9, 'Después llamó Abimelec a Abraham, y le dijo: ¿Qué nos has hecho? ¿En qué pequé yo contra ti, que has traído sobre mí y sobre mi reino tan grande pecado? Lo que no debiste hacer, has hecho conmigo.'),
(v_cap_id, 10, 'Y dijo también Abimelec a Abraham: ¿Qué pensabas, para que hicieses esto?'),
(v_cap_id, 11, 'Y Abraham respondió: Porque dije para mí: Ciertamente no hay temor de Dios en este lugar, y me matarán por causa de mi mujer.'),
(v_cap_id, 12, 'Y a la verdad también es mi hermana, hija de mi padre, mas no hija de mi madre, y la tomé por mujer.'),
(v_cap_id, 13, 'Y cuando Dios me hizo salir errante de la casa de mi padre, yo le dije: Esta es la misericordia que tú harás conmigo: en todos los lugares donde lleguemos, dirás de mí: Mi hermano es.'),
(v_cap_id, 14, 'Entonces Abimelec tomó ovejas y vacas, y siervos y siervas, y se los dio a Abraham, y le devolvió a Sara su mujer.'),
(v_cap_id, 15, 'Y dijo Abimelec: He aquí mi tierra está delante de ti; habita donde bien te parezca.'),
(v_cap_id, 16, 'Y a Sara dijo: He aquí he dado mil monedas de plata a tu hermano; mira que él te es como velo para los ojos de todos los que están contigo, y para con todos; así fue vindicada.'),
(v_cap_id, 17, 'Entonces Abraham oró a Dios; y Dios sanó a Abimelec y a su mujer, y a sus siervas, y tuvieron hijos.'),
(v_cap_id, 18, 'Porque Jehová había cerrado totalmente toda matriz de la casa de Abimelec, a causa de Sara mujer de Abraham.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Visitó Jehová a Sara, como había dicho, e hizo Jehová con Sara como había hablado.'),
(v_cap_id, 2, 'Y Sara concibió y dio a Abraham un hijo en su vejez, en el tiempo que Dios le había dicho.'),
(v_cap_id, 3, 'Y llamó Abraham el nombre de su hijo que le nació, que le dio Sara, Isaac.'),
(v_cap_id, 4, 'Y circuncidó Abraham a su hijo Isaac de ocho días, como Dios le había mandado.'),
(v_cap_id, 5, 'Y era Abraham de cien años cuando le nació Isaac su hijo.'),
(v_cap_id, 6, 'Entonces dijo Sara: Dios me ha hecho reír, y cualquiera que lo oyere, se reirá conmigo.'),
(v_cap_id, 7, 'Y añadió: ¿Quién dijera a Abraham que Sara había de dar de mamar a hijos? Pues bien, le he dado un hijo en su vejez.'),
(v_cap_id, 8, 'Y creció el niño, y fue destetado; e hizo Abraham gran banquete el día que fue destetado Isaac.'),
(v_cap_id, 9, 'Y vio Sara que el hijo de Agar la egipcia, el cual había nacido de Abraham, se burlaba.'),
(v_cap_id, 10, 'Por tanto, dijo a Abraham: Echa a esta sierva y a su hijo, porque el hijo de esta sierva no ha de heredar con Isaac mi hijo.'),
(v_cap_id, 11, 'Esto dolió en gran manera a Abraham por causa de su hijo.'),
(v_cap_id, 12, 'Entonces dijo Dios a Abraham: No te parezca grave a causa del muchacho y de tu sierva; en todo lo que Sara te ha dicho, oye su voz, porque en Isaac te será llamada descendencia.'),
(v_cap_id, 13, 'Y también del hijo de la sierva haré una nación, porque es tu descendiente.'),
(v_cap_id, 14, 'Entonces Abraham se levantó muy de mañana, y tomó pan y un odre de agua, y lo dio a Agar, poniéndolo sobre su hombro, y le entregó al muchacho, y la despidió. Y ella anduvo y erró por el desierto de Beerseba.'),
(v_cap_id, 15, 'Y se acabó el agua del odre, y ella puso al muchacho debajo de un arbusto,'),
(v_cap_id, 16, 'y fue y se sentó enfrente, a distancia de un tiro de arco, porque decía: No veré cuando el muchacho muera. Y se sentó enfrente, y alzó su voz y lloró.'),
(v_cap_id, 17, 'Y oyó Dios la voz del muchacho; y el ángel de Dios llamó a Agar desde el cielo, y le dijo: ¿Qué tienes, Agar? No temas; porque Dios ha oído la voz del muchacho en donde está.'),
(v_cap_id, 18, 'Levántate, alza al muchacho, y sosténlo con tu mano, porque haré de él una gran nación.'),
(v_cap_id, 19, 'Entonces Dios le abrió los ojos, y vio una fuente de agua; y fue y llenó el odre de agua, y dio de beber al muchacho.'),
(v_cap_id, 20, 'Y Dios estaba con el muchacho; y creció, y habitó en el desierto, y fue tirador de arco.'),
(v_cap_id, 21, 'Y habitó en el desierto de Parán; y su madre le tomó mujer de la tierra de Egipto.'),
(v_cap_id, 22, 'Aconteció en aquel mismo tiempo que habló Abimelec, y Ficol príncipe de su ejército, a Abraham, diciendo: Dios está contigo en todo cuanto haces.'),
(v_cap_id, 23, 'Ahora, pues, júrame aquí por Dios que no faltarás a mí, ni a mi hijo ni a mi nieto; sino que conforme a la bondad que yo hice contigo, harás tú conmigo, y con la tierra en donde has morado.'),
(v_cap_id, 24, 'Y respondió Abraham: Yo juraré.'),
(v_cap_id, 25, 'Y Abraham reconvino a Abimelec a causa de un pozo de agua, que los siervos de Abimelec le habían quitado.'),
(v_cap_id, 26, 'Y respondió Abimelec: No sé quién haya hecho esto, ni tampoco tú me lo hiciste saber, ni yo lo he oído hasta hoy.'),
(v_cap_id, 27, 'Y tomó Abraham ovejas y vacas, y dio a Abimelec; e hicieron ambos pacto.'),
(v_cap_id, 28, 'Entonces puso Abraham siete corderas del rebaño aparte.'),
(v_cap_id, 29, 'Y dijo Abimelec a Abraham: ¿Qué significan esas siete corderas que has puesto aparte?'),
(v_cap_id, 30, 'Y él respondió: Que estas siete corderas tomarás de mi mano, para que me sirvan de testimonio de que yo cavé este pozo.'),
(v_cap_id, 31, 'Por eso llamó a aquel lugar Beerseba, porque allí juraron ambos.'),
(v_cap_id, 32, 'Así hicieron pacto en Beerseba; y se levantó Abimelec, y Ficol príncipe de su ejército, y volvieron a tierra de los filisteos.'),
(v_cap_id, 33, 'Y plantó Abraham un árbol tamarisco en Beerseba, e invocó allí el nombre de Jehová Dios eterno.'),
(v_cap_id, 34, 'Y moró Abraham en tierra de los filisteos muchos días.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Aconteció después de estas cosas, que probó Dios a Abraham, y le dijo: Abraham. Y él respondió: Heme aquí.'),
(v_cap_id, 2, 'Y dijo: Toma ahora tu hijo, tu único, Isaac, a quien amas, y vete a tierra de Moriah, y ofrécelo allí en holocausto sobre uno de los montes que yo te diré.'),
(v_cap_id, 3, 'Y Abraham se levantó muy de mañana, y enalbardó su asno, y tomó consigo dos siervos suyos, y a Isaac su hijo; y cortó leña para el holocausto, y se levantó y fue al lugar que Dios le dijo.'),
(v_cap_id, 4, 'Al tercer día alzó Abraham sus ojos, y vio el lugar de lejos.'),
(v_cap_id, 5, 'Entonces dijo Abraham a sus siervos: Esperad aquí con el asno, y yo y el muchacho iremos hasta allí y adoraremos, y volveremos a vosotros.'),
(v_cap_id, 6, 'Y tomó Abraham la leña del holocausto, y la puso sobre Isaac su hijo, y él tomó en su mano el fuego y el cuchillo; y fueron ambos juntos.'),
(v_cap_id, 7, 'Entonces habló Isaac a Abraham su padre, y dijo: Padre mío. Y él respondió: Heme aquí, mi hijo. Y dijo: He aquí el fuego y la leña; mas ¿dónde está el cordero para el holocausto?'),
(v_cap_id, 8, 'Y respondió Abraham: Dios se proveerá de cordero para el holocausto, hijo mío. E iban juntos.'),
(v_cap_id, 9, 'Y cuando llegaron al lugar que Dios le había dicho, edificó allí Abraham un altar, y compuso la leña, y ató a Isaac su hijo, y lo puso en el altar sobre la leña.'),
(v_cap_id, 10, 'Y extendió Abraham su mano y tomó el cuchillo para degollar a su hijo.'),
(v_cap_id, 11, 'Entonces el ángel de Jehová le dio voces desde el cielo, y dijo: Abraham, Abraham. Y él respondió: Heme aquí.'),
(v_cap_id, 12, 'Y dijo: No extiendas tu mano sobre el muchacho, ni le hagas nada; porque ya conozco que temes a Dios, por cuanto no me rehusaste tu hijo, tu único.'),
(v_cap_id, 13, 'Entonces alzó Abraham sus ojos y miró, y he aquí a sus espaldas un carnero trabado en un zarzal por sus cuernos; y fue Abraham y tomó el carnero, y lo ofreció en holocausto en lugar de su hijo.'),
(v_cap_id, 14, 'Y llamó Abraham el nombre de aquel lugar, Jehová proveerá. Por tanto se dice hoy: En el monte de Jehová será provisto.'),
(v_cap_id, 15, 'Y llamó el ángel de Jehová a Abraham por segunda vez desde el cielo,'),
(v_cap_id, 16, 'y dijo: Por mí mismo he jurado, dice Jehová, que por cuanto has hecho esto, y no me has rehusado tu hijo, tu único,'),
(v_cap_id, 17, 'de cierto te bendeciré, y multiplicaré tu descendencia como las estrellas del cielo y como la arena que está a la orilla del mar; y tu descendencia poseerá las puertas de sus enemigos.'),
(v_cap_id, 18, 'En tu simiente serán benditas todas las naciones de la tierra, por cuanto obedeciste a mi voz.'),
(v_cap_id, 19, 'Y volvió Abraham a sus siervos, y se levantaron y se fueron juntos a Beerseba; y habitó Abraham en Beerseba.'),
(v_cap_id, 20, 'Después de estas cosas sucedió que fue dada noticia a Abraham, diciendo: He aquí que también Milca ha dado a luz hijos a Nacor tu hermano:'),
(v_cap_id, 21, 'a Uz su primogénito, a Buz su hermano, a Kemuel padre de Aram,'),
(v_cap_id, 22, 'a Quesed, a Hazo, a Pildas, a Jidlaf y a Betuel.'),
(v_cap_id, 23, 'Y Betuel engendró a Rebeca. Estos ocho hijos dio a luz Milca de Nacor, hermano de Abraham.'),
(v_cap_id, 24, 'Y su concubina, que se llamaba Reúma, dio a luz también a Tebah, a Gaham, a Tahas y a Maaca.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Fue la vida de Sara ciento veintisiete años; tantos fueron los años de la vida de Sara.'),
(v_cap_id, 2, 'Y murió Sara en Quiriat-arba, que es Hebrón, en la tierra de Canaán; y vino Abraham a hacer duelo por Sara, y a llorarla.'),
(v_cap_id, 3, 'Y se levantó Abraham de delante de su muerta, y habló a los hijos de Het, diciendo:'),
(v_cap_id, 4, 'Extranjero y forastero soy entre vosotros; dadme en propiedad una sepultura entre vosotros, para que sepulte a mi muerta de delante de mí.'),
(v_cap_id, 5, 'Y los hijos de Het respondieron a Abraham, diciéndole:'),
(v_cap_id, 6, 'Oyenos, señor nuestro; eres un príncipe de Dios entre nosotros; en lo mejor de nuestras sepulturas sepulta a tu muerta; ninguno de nosotros te negará su sepultura para que sepultes a tu muerta.'),
(v_cap_id, 7, 'Y Abraham se levantó, y se inclinó al pueblo de aquella tierra, a los hijos de Het;'),
(v_cap_id, 8, 'y habló con ellos, diciendo: Si es vuestra voluntad que yo sepulte a mi muerta de delante de mí, oídme, e interceded por mí con Efrón hijo de Zohar,'),
(v_cap_id, 9, 'para que me dé la cueva de Macpela, que tiene al extremo de su heredad; que por su justo precio me la dé, para posesión de sepultura en medio de vosotros.'),
(v_cap_id, 10, 'Efrón el heteo estaba sentado entre los hijos de Het; y respondió Efrón el heteo a Abraham, en oídos de los hijos de Het, de todos los que entraban por la puerta de su ciudad, diciendo:'),
(v_cap_id, 11, 'No, señor mío, óyeme: te doy la heredad, y también te doy la cueva que está en ella; en presencia de los hijos de mi pueblo te la doy; sepulta a tu muerta.'),
(v_cap_id, 12, 'Entonces Abraham se inclinó delante del pueblo de la tierra,'),
(v_cap_id, 13, 'y respondió a Efrón en oídos del pueblo de la tierra, diciendo: Antes, si te place, te ruego que me oigas; yo pagaré el precio de la heredad, tómalo de mí, y sepultaré en ella a mi muerta.'),
(v_cap_id, 14, 'Y respondió Efrón a Abraham, diciéndole:'),
(v_cap_id, 15, 'Señor mío, escúchame: la tierra vale cuatrocientos siclos de plata; ¿qué es eso entre tú y yo? Sepulta, pues, a tu muerta.'),
(v_cap_id, 16, 'Entonces Abraham se convino con Efrón, y pesó Abraham a Efrón el dinero que dijo, en oídos de los hijos de Het, cuatrocientos siclos de plata, de buena ley entre mercaderes.'),
(v_cap_id, 17, 'Y quedó la heredad de Efrón que estaba en Macpela, al oriente de Mamre, la heredad con la cueva que estaba en ella, y todos los árboles que en la heredad había, en todo su derredor,'),
(v_cap_id, 18, 'como propiedad de Abraham, en presencia de los hijos de Het, de todos los que entraban por la puerta de la ciudad.'),
(v_cap_id, 19, 'Después de esto sepultó Abraham a Sara su mujer en la cueva de la heredad de Macpela al oriente de Mamre, que es Hebrón, en la tierra de Canaán.'),
(v_cap_id, 20, 'Y quedó la heredad y la cueva que en ella hay, como propiedad de Abraham, para sepultura, adquirida de los hijos de Het.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Era Abraham ya viejo, y bien avanzado en años; y Jehová había bendecido a Abraham en todo.'),
(v_cap_id, 2, 'Y dijo Abraham a un criado suyo, el más viejo de su casa, que era el que gobernaba en todo lo que tenía: Pon ahora tu mano debajo de mi muslo,'),
(v_cap_id, 3, 'y te juramentaré por Jehová, Dios de los cielos y Dios de la tierra, que no tomarás mujer para mi hijo de las hijas de los cananeos, entre los cuales yo habito,'),
(v_cap_id, 4, 'sino que irás a mi tierra y a mi parentela, y tomarás mujer para mi hijo Isaac.'),
(v_cap_id, 5, 'El criado le respondió: Quizá la mujer no querrá venir en pos de mí a esta tierra. ¿Volveré, pues, tu hijo a la tierra de donde saliste?'),
(v_cap_id, 6, 'Y Abraham le dijo: Guárdate que no vuelvas a mi hijo allá.'),
(v_cap_id, 7, 'Jehová, Dios de los cielos, que me tomó de la casa de mi padre y de la tierra de mi parentela, y me habló y me juró, diciendo: A tu descendencia daré esta tierra; él enviará su ángel delante de ti, y tú traerás de allá mujer para mi hijo.'),
(v_cap_id, 8, 'Y si la mujer no quisiere venir contigo, tú quedarás libre de este juramento; solamente que no vuelvas allá a mi hijo.'),
(v_cap_id, 9, 'Entonces el criado puso su mano debajo del muslo de Abraham su señor, y le juró sobre este negocio.'),
(v_cap_id, 10, 'Y el criado tomó diez camellos de los camellos de su señor, y se fue, tomando toda clase de regalos escogidos de su señor; y puesto en camino, llegó a Mesopotamia, a la ciudad de Nacor.'),
(v_cap_id, 11, 'E hizo arrodillar los camellos fuera de la ciudad, junto a un pozo de agua, a la hora de la tarde, la hora en que salen las doncellas por agua.'),
(v_cap_id, 12, 'Y dijo: Oh Jehová, Dios de mi señor Abraham, dame, te ruego, el tener hoy buen encuentro, y haz misericordia con mi señor Abraham.'),
(v_cap_id, 13, 'He aquí yo estoy junto a la fuente de agua, y las hijas de los varones de esta ciudad salen por agua.'),
(v_cap_id, 14, 'Sea, pues, que la doncella a quien yo dijere: Baja tu cántaro, te ruego, para que beba, y ella respondiere: Bebe, y también daré de beber a tus camellos; que sea ésta la que tú has destinado para tu siervo Isaac; y en esto conoceré que habrás hecho misericordia con mi señor.'),
(v_cap_id, 15, 'Y aconteció que antes que él acabase de hablar, he aquí Rebeca, que había nacido a Betuel, hijo de Milca mujer de Nacor hermano de Abraham, la cual salía con su cántaro sobre su hombro.'),
(v_cap_id, 16, 'Y la doncella era de hermoso aspecto, virgen, a quien varón no había conocido; la cual descendió a la fuente, y llenó su cántaro, y subió.'),
(v_cap_id, 17, 'Entonces el criado corrió hacia ella, y dijo: Te ruego que me des a beber un poco de agua de tu cántaro.'),
(v_cap_id, 18, 'Ella respondió: Bebe, señor mío; y se dio prisa a bajar su cántaro sobre su mano, y le dio de beber.'),
(v_cap_id, 19, 'Y cuando acabó de darle de beber, dijo: También para tus camellos sacaré agua, hasta que acaben de beber.'),
(v_cap_id, 20, 'Y se dio prisa, y vació su cántaro en el abrevadero, y corrió otra vez al pozo para sacar agua, y sacó para todos sus camellos.'),
(v_cap_id, 21, 'Y el hombre estaba maravillado de ella, callando, para saber si Jehová había prosperado su viaje o no.'),
(v_cap_id, 22, 'Y cuando los camellos acabaron de beber, le dio el hombre un pendiente de oro que pesaba medio siclo, y dos brazaletes para sus manos que pesaban diez siclos de oro.'),
(v_cap_id, 23, 'Y dijo: ¿De quién eres hija? Te ruego que me digas: ¿hay en casa de tu padre lugar para posar?'),
(v_cap_id, 24, 'Y ella respondió: Soy hija de Betuel, hijo de Milca, el cual ella dio a luz a Nacor.'),
(v_cap_id, 25, 'Y añadió: También en nuestra casa hay paja y mucho forraje, y lugar para posar.'),
(v_cap_id, 26, 'El hombre entonces se inclinó y adoró a Jehová.'),
(v_cap_id, 27, 'Y dijo: Bendito sea Jehová, Dios de mi señor Abraham, que no apartó su misericordia y su verdad de mi señor, guiándome Jehová en el camino a casa de los hermanos de mi señor.'),
(v_cap_id, 28, 'Y la doncella corrió, e hizo saber en casa de su madre estas cosas.'),
(v_cap_id, 29, 'Y Rebeca tenía un hermano que se llamaba Labán, el cual corrió hacia el hombre, a la fuente.'),
(v_cap_id, 30, 'Y cuando vio el pendiente y los brazaletes en las manos de su hermana, y oyó las palabras de Rebeca su hermana, que decía: Así me habló el hombre; vino a él; y he aquí que estaba junto a los camellos, a la fuente.'),
(v_cap_id, 31, 'Y le dijo: Ven, bendito de Jehová; ¿por qué estás fuera? He preparado la casa, y lugar para los camellos.'),
(v_cap_id, 32, 'Entonces el hombre vino a la casa, y Labán desató los camellos, les dio paja y forraje, y agua para lavar los pies de él, y los pies de los hombres que con él venían.'),
(v_cap_id, 33, 'Y le pusieron delante qué comer; mas él dijo: No comeré hasta que haya dicho mi mensaje. Y él le dijo: Habla.'),
(v_cap_id, 34, 'Entonces dijo: Yo soy criado de Abraham.'),
(v_cap_id, 35, 'Y Jehová ha bendecido mucho a mi señor, y él se ha engrandecido; le ha dado ovejas, vacas, plata, oro, siervos, siervas, camellos y asnos.'),
(v_cap_id, 36, 'Y Sara, la mujer de mi señor, dio a luz un hijo a mi señor después de su vejez, y le ha dado todo cuanto tiene.'),
(v_cap_id, 37, 'Y mi señor me hizo jurar, diciendo: No tomarás mujer para mi hijo de las hijas de los cananeos, en cuya tierra habito,'),
(v_cap_id, 38, 'sino que irás a la casa de mi padre y a mi parentela, y tomarás mujer para mi hijo.'),
(v_cap_id, 39, 'Y yo dije: Quizá la mujer no querrá seguirme.'),
(v_cap_id, 40, 'Entonces él me respondió: Jehová, en cuya presencia he andado, enviará su ángel contigo, y prosperará tu camino; y tomarás mujer para mi hijo de mi familia y de la casa de mi padre.'),
(v_cap_id, 41, 'Entonces serás libre de mi juramento, cuando fueres a mi familia; y si no te la dieren, serás libre de mi juramento.'),
(v_cap_id, 42, 'Llegué, pues, hoy a la fuente, y dije: Oh Jehová, Dios de mi señor Abraham, si tú prosperas ahora mi camino por el cual ando,'),
(v_cap_id, 43, 'he aquí yo estoy junto a la fuente; sea, pues, que la doncella que saliere por agua, a la cual dijere: Dame de beber, te ruego, un poco de agua de tu cántaro,'),
(v_cap_id, 44, 'y ella me respondiere: Bebe tú, y también para tus camellos sacaré agua; sea ésta la mujer que Jehová ha destinado para el hijo de mi señor.'),
(v_cap_id, 45, 'Y antes que acabase de hablar en mi corazón, he aquí Rebeca salía con su cántaro sobre su hombro; y descendió a la fuente, y sacó agua; y le dije: Te ruego que me des de beber.'),
(v_cap_id, 46, 'Y ella se dio prisa, y bajó su cántaro de sobre sí, y dijo: Bebe, y también daré de beber a tus camellos. Y bebí, y dio también de beber a los camellos.'),
(v_cap_id, 47, 'Entonces le pregunté, y dije: ¿De quién eres hija? Y ella respondió: La hija de Betuel, hijo de Nacor, que le dio a luz Milca. Entonces le puse un pendiente en la nariz y brazaletes en sus manos.'),
(v_cap_id, 48, 'Y me incliné y adoré a Jehová, y bendije a Jehová Dios de mi señor Abraham, que me había guiado por camino de verdad para tomar la hija del hermano de mi señor para su hijo.'),
(v_cap_id, 49, 'Ahora, pues, si vosotros hacéis misericordia y verdad con mi señor, decídmelo; y si no, decídmelo; y yo miraré a la derecha o a la izquierda.'),
(v_cap_id, 50, 'Entonces Labán y Betuel respondieron y dijeron: De Jehová ha salido esto; no podemos hablarte malo ni bueno.'),
(v_cap_id, 51, 'He ahí Rebeca delante de ti; tómala y vete, y sea mujer del hijo de tu señor, como lo ha dicho Jehová.'),
(v_cap_id, 52, 'Y cuando el criado de Abraham oyó sus palabras, se inclinó en tierra ante Jehová.'),
(v_cap_id, 53, 'Y sacó el criado alhajas de plata y alhajas de oro, y vestidos, y dio a Rebeca; también dio cosas preciosas a su hermano y a su madre.'),
(v_cap_id, 54, 'Y comieron y bebieron él y los varones que venían con él, y durmieron; y levantándose de mañana, dijo: Enviadme a mi señor.'),
(v_cap_id, 55, 'Entonces respondieron su hermano y su madre: Espere la doncella con nosotros a lo menos diez días, y después irá.'),
(v_cap_id, 56, 'Y él les dijo: No me detengáis, pues Jehová ha prosperado mi camino; despachadme para que me vaya a mi señor.'),
(v_cap_id, 57, 'Ellos respondieron entonces: Llamemos a la doncella y preguntémosle.'),
(v_cap_id, 58, 'Y llamaron a Rebeca, y le dijeron: ¿Irás tú con este varón? Y ella respondió: Sí, iré.'),
(v_cap_id, 59, 'Entonces dejaron ir a Rebeca su hermana, y a su nodriza, y al criado de Abraham y a sus hombres.'),
(v_cap_id, 60, 'Y bendijeron a Rebeca, y le dijeron: Hermana nuestra, sé madre de millares de millares, y posean tus descendientes la puerta de sus enemigos.'),
(v_cap_id, 61, 'Entonces se levantó Rebeca y sus doncellas, y montaron en los camellos, y siguieron al hombre; y el criado tomó a Rebeca, y se fue.'),
(v_cap_id, 62, 'Y venía Isaac del pozo del Viviente-que-me-ve; porque él habitaba en el Neguev.'),
(v_cap_id, 63, 'Y había salido Isaac a meditar al campo, a la hora de la tarde; y alzando sus ojos, vio venir los camellos.'),
(v_cap_id, 64, 'Rebeca también alzó sus ojos, y vio a Isaac, y descendió del camello;'),
(v_cap_id, 65, 'porque había preguntado al criado: ¿Quién es este varón que viene por el campo hacia nosotros? Y el criado había respondido: Es mi señor. Entonces ella tomó el velo y se cubrió.'),
(v_cap_id, 66, 'Entonces el criado contó a Isaac todo lo que había hecho.'),
(v_cap_id, 67, 'Y la trajo Isaac a la tienda de su madre Sara, y tomó a Rebeca por mujer; y la amó; y se consoló Isaac después de la muerte de su madre.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Abraham tomó otra mujer, cuyo nombre era Cetura,'),
(v_cap_id, 2, 'la cual le dio a luz a Zimram, a Jocsán, a Medán, a Madián, a Isbac y a Súa.'),
(v_cap_id, 3, 'Y Jocsán engendró a Seba y a Dedán; e hijos de Dedán fueron Asurim, Letusim y Leumim.'),
(v_cap_id, 4, 'E hijos de Madián: Efa, Efer, Hanoc, Abida y Elda. Todos estos fueron hijos de Cetura.'),
(v_cap_id, 5, 'Y Abraham dio todo cuanto tenía a Isaac.'),
(v_cap_id, 6, 'Pero a los hijos de sus concubinas dio Abraham dones, y los envió lejos de Isaac su hijo, mientras él vivía, hacia el oriente, a la tierra oriental.'),
(v_cap_id, 7, 'Y estos fueron los días de vida que vivió Abraham: ciento setenta y cinco años.'),
(v_cap_id, 8, 'Y exhaló el espíritu, y murió Abraham en buena vejez, anciano y lleno de años, y fue reunido a su pueblo.'),
(v_cap_id, 9, 'Y lo sepultaron Isaac e Ismael sus hijos en la cueva de Macpela, en la heredad de Efrón hijo de Zohar el heteo, que está enfrente de Mamre;'),
(v_cap_id, 10, 'heredad que compró Abraham de los hijos de Het; allí fue sepultado Abraham, y Sara su mujer.'),
(v_cap_id, 11, 'Y después de la muerte de Abraham, Dios bendijo a Isaac su hijo; y habitó Isaac junto al pozo del Viviente-que-me-ve.'),
(v_cap_id, 12, 'Estas son las generaciones de Ismael, hijo de Abraham, que le dio Agar la egipcia, sierva de Sara;'),
(v_cap_id, 13, 'estos, pues, son los nombres de los hijos de Ismael, llamados por sus nombres, por su orden: El primogénito de Ismael, Nebaiot; luego Cedar, Adbeel, Mibsam,'),
(v_cap_id, 14, 'Misma, Duma, Massa,'),
(v_cap_id, 15, 'Hadar, Tema, Jetur, Nafis y Cedema.'),
(v_cap_id, 16, 'Estos son los hijos de Ismael, y estos sus nombres, por sus villas y por sus campamentos; doce príncipes por sus familias.'),
(v_cap_id, 17, 'Y los años de la vida de Ismael fueron ciento treinta y siete años; y exhaló el espíritu Ismael, y murió, y fue reunido a su pueblo.'),
(v_cap_id, 18, 'Y habitaron desde Havila hasta Shur, que está enfrente de Egipto, y yendo hacia Asiria; y murió en presencia de todos sus hermanos.'),
(v_cap_id, 19, 'Estas son las generaciones de Isaac, hijo de Abraham: Abraham engendró a Isaac.'),
(v_cap_id, 20, 'Y era Isaac de cuarenta años cuando tomó por mujer a Rebeca, hija de Betuel, arameo de Padan-aram, hermana de Labán el arameo.'),
(v_cap_id, 21, 'Y oró Isaac a Jehová por su mujer, porque era estéril; y lo aceptó Jehová, y concibió Rebeca su mujer.'),
(v_cap_id, 22, 'Y los hijos luchaban dentro de ella; y dijo: Si es así, ¿para qué vivo yo? Y fue a consultar a Jehová.'),
(v_cap_id, 23, 'Y le respondió Jehová: Dos naciones hay en tu seno, y dos pueblos serán divididos desde tus entrañas; el un pueblo será más fuerte que el otro pueblo, y el mayor servirá al menor.'),
(v_cap_id, 24, 'Cuando se cumplieron sus días para dar a luz, he aquí había gemelos en su vientre.'),
(v_cap_id, 25, 'Y salió el primero rubio, y era todo velludo como una pelliza; y llamaron su nombre Esaú.'),
(v_cap_id, 26, 'Después salió su hermano, trabada su mano al calcañar de Esaú; y fue llamado su nombre Jacob. Y era Isaac de edad de sesenta años cuando ella los dio a luz.'),
(v_cap_id, 27, 'Y crecieron los niños, y Esaú fue diestro en la caza, hombre del campo; pero Jacob era varón quieto, que habitaba en tiendas.'),
(v_cap_id, 28, 'Y amó Isaac a Esaú, porque comía de su caza; mas Rebeca amaba a Jacob.'),
(v_cap_id, 29, 'Y guisó Jacob un potaje; y volviendo Esaú del campo, cansado,'),
(v_cap_id, 30, 'dijo a Jacob: Te ruego que me des a comer de ese guiso rojo, pues estoy muy cansado. Por tanto fue llamado su nombre Edom.'),
(v_cap_id, 31, 'Y Jacob respondió: Véndeme en este día tu primogenitura.'),
(v_cap_id, 32, 'Entonces dijo Esaú: He aquí yo me voy a morir; ¿para qué, pues, me servirá la primogenitura?'),
(v_cap_id, 33, 'Y dijo Jacob: Júramelo en este día. Y él le juró, y vendió su primogenitura a Jacob.'),
(v_cap_id, 34, 'Entonces Jacob dio a Esaú pan y del guiso de las lentejas; y él comió y bebió, y se levantó y se fue. Así menospreció Esaú la primogenitura.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Después hubo hambre en la tierra, además de la primera hambre que hubo en los días de Abraham; y se fue Isaac a Abimelec rey de los filisteos, en Gerar.'),
(v_cap_id, 2, 'Y se le apareció Jehová, y le dijo: No desciendas a Egipto; habita en la tierra que yo te diré.'),
(v_cap_id, 3, 'Habita como forastero en esta tierra, y estaré contigo, y te bendeciré; porque a ti y a tu descendencia daré todas estas tierras, y confirmaré el juramento que hice a Abraham tu padre.'),
(v_cap_id, 4, 'Multiplicaré tu descendencia como las estrellas del cielo, y daré a tu descendencia todas estas tierras; y todas las naciones de la tierra serán benditas en tu simiente,'),
(v_cap_id, 5, 'por cuanto oyó Abraham mi voz, y guardó mi precepto, mis mandamientos, mis estatutos y mis leyes.'),
(v_cap_id, 6, 'Habitó, pues, Isaac en Gerar.'),
(v_cap_id, 7, 'Y los hombres de aquel lugar le preguntaron acerca de su mujer; y dijo: Es mi hermana; porque tuvo miedo de decir: Es mi mujer; pensando que tal vez los hombres del lugar lo matarían por causa de Rebeca, pues ella era de hermoso aspecto.'),
(v_cap_id, 8, 'Sucedió que después que él estuvo allí muchos días, Abimelec, rey de los filisteos, mirando por una ventana, vio a Isaac que acariciaba a Rebeca su mujer.'),
(v_cap_id, 9, 'Entonces llamó Abimelec a Isaac, y dijo: He aquí, de cierto ella es tu mujer. ¿Cómo, pues, dijiste: Es mi hermana? E Isaac le respondió: Porque pensé: Quizá moriría por causa de ella.'),
(v_cap_id, 10, 'Y Abimelec dijo: ¿Qué es esto que nos has hecho? Por poco hubiera dormido alguno del pueblo con tu mujer, y hubieras traído sobre nosotros el pecado.'),
(v_cap_id, 11, 'Entonces Abimelec mandó a todo el pueblo, diciendo: El que tocare a este hombre o a su mujer, de cierto morirá.'),
(v_cap_id, 12, 'Y sembró Isaac en aquella tierra, y cosechó aquel año ciento por medida; y le bendijo Jehová.'),
(v_cap_id, 13, 'El varón se enriqueció, y fue prosperado, y se engrandeció hasta hacerse muy poderoso.'),
(v_cap_id, 14, 'Y tuvo hato de ovejas, y hato de vacas, y mucha labranza; y los filisteos le tuvieron envidia.'),
(v_cap_id, 15, 'Y todos los pozos que habían abierto los siervos de Abraham su padre en sus días, los filisteos los cegaron y llenaron de tierra.'),
(v_cap_id, 16, 'Entonces dijo Abimelec a Isaac: Apártate de nosotros, porque mucho más poderoso que nosotros te has hecho.'),
(v_cap_id, 17, 'E Isaac se fue de allí, y acampó en el valle de Gerar, y habitó allí.'),
(v_cap_id, 18, 'Y volvió Isaac a abrir los pozos de agua que habían abierto en los días de Abraham su padre, y que los filisteos habían cegado después de la muerte de Abraham; y los llamó por los mismos nombres que su padre los había llamado.'),
(v_cap_id, 19, 'Y los siervos de Isaac cavaron en el valle, y hallaron allí un pozo de aguas vivas.'),
(v_cap_id, 20, 'Y los pastores de Gerar riñeron con los pastores de Isaac, diciendo: El agua es nuestra. Por eso llamó el nombre del pozo Esek, porque habían altercado con él.'),
(v_cap_id, 21, 'Y cavaron otro pozo, y también riñeron sobre él; y llamó su nombre Sitna.'),
(v_cap_id, 22, 'Y se apartó de allí, y cavó otro pozo, y no riñeron sobre él; y llamó su nombre Rehobot, y dijo: Porque ahora Jehová nos ha hecho ensanchar, y fructificaremos en la tierra.'),
(v_cap_id, 23, 'Y de allí subió a Beerseba.'),
(v_cap_id, 24, 'Y se le apareció Jehová aquella noche, y le dijo: Yo soy el Dios de Abraham tu padre; no temas, porque yo estoy contigo, y te bendeciré, y multiplicaré tu descendencia por amor de Abraham mi siervo.'),
(v_cap_id, 25, 'Y edificó allí un altar, e invocó el nombre de Jehová, y plantó allí su tienda; y abrieron allí los siervos de Isaac un pozo.'),
(v_cap_id, 26, 'Y Abimelec fue a él desde Gerar, con Ahuzat, su amigo, y Ficol, capitán de su ejército.'),
(v_cap_id, 27, 'Y les dijo Isaac: ¿Por qué venís a mí, pues que me habéis aborrecido y me echasteis de entre vosotros?'),
(v_cap_id, 28, 'Y ellos respondieron: Hemos visto claramente que Jehová está contigo; y dijimos: Haya ahora juramento entre nosotros, entre tú y nosotros, y haremos pacto contigo,'),
(v_cap_id, 29, 'que no nos hagas mal, así como nosotros no te hemos tocado, y como solamente te hemos hecho bien, y te enviamos en paz; tú eres ahora bendito de Jehová.'),
(v_cap_id, 30, 'Entonces él les hizo banquete, y comieron y bebieron.'),
(v_cap_id, 31, 'Y se levantaron de madrugada, y juraron el uno al otro; e Isaac los despidió, y ellos se despidieron de él en paz.'),
(v_cap_id, 32, 'En aquel día sucedió que vinieron los siervos de Isaac, y le dieron nuevas acerca del pozo que habían abierto, y le dijeron: Hemos hallado agua.'),
(v_cap_id, 33, 'Y lo llamó Seba; por esta causa el nombre de aquella ciudad es Beerseba hasta hoy.'),
(v_cap_id, 34, 'Y cuando Esaú era de cuarenta años, tomó por mujer a Judit, hija de Beeri heteo, y a Basemat, hija de Elón heteo;'),
(v_cap_id, 35, 'y fueron amargura de espíritu para Isaac y para Rebeca.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Aconteció que cuando Isaac envejeció, y sus ojos se oscurecieron quedando sin vista, llamó a Esaú su hijo mayor, y le dijo: Hijo mío. Y él respondió: Heme aquí.'),
(v_cap_id, 2, 'Y él dijo: He aquí ya soy viejo, no sé el día de mi muerte.'),
(v_cap_id, 3, 'Toma, pues, ahora tus armas, tu aljaba y tu arco, y sal al campo, y tráeme caza,'),
(v_cap_id, 4, 'y hazme un guisado como a mí me gusta, y tráemelo, y comeré, para que yo te bendiga antes que muera.'),
(v_cap_id, 5, 'Y Rebeca estaba oyendo, cuando hablaba Isaac a Esaú su hijo; y se fue Esaú al campo a traer la caza.'),
(v_cap_id, 6, 'Entonces Rebeca habló a Jacob su hijo, diciendo: He aquí, yo he oído a tu padre que hablaba con Esaú tu hermano, diciendo:'),
(v_cap_id, 7, 'Tráeme caza y hazme un guisado, para que coma, y te bendiga en presencia de Jehová antes que muera.'),
(v_cap_id, 8, 'Ahora, pues, hijo mío, obedece a mi voz en lo que te mando.'),
(v_cap_id, 9, 'Ve ahora al ganado, y tráeme de allí dos buenos cabritos de las cabras, y haré de ellos un guisado para tu padre, como a él le gusta;'),
(v_cap_id, 10, 'y tú lo llevarás a tu padre, y él comerá, para que él te bendiga antes de su muerte.'),
(v_cap_id, 11, 'Y Jacob dijo a Rebeca su madre: He aquí, Esaú mi hermano es hombre velloso, y yo lampiño.'),
(v_cap_id, 12, 'Quizá me palpará mi padre, y me tendrá por engañador, y traeré sobre mí maldición y no bendición.'),
(v_cap_id, 13, 'Y su madre respondió: Sea sobre mí tu maldición, hijo mío; solamente obedece a mi voz y ve y tráemelos.'),
(v_cap_id, 14, 'Entonces él fue, y los tomó, y los trajo a su madre; y su madre hizo un guisado, como a su padre le gustaba.'),
(v_cap_id, 15, 'Y tomó Rebeca los vestidos de Esaú su hijo mayor, los preciosos, que ella tenía en casa, y vistió a Jacob su hijo menor;'),
(v_cap_id, 16, 'y con las pieles de los cabritos cubrió sus manos y lo descubierto de su cuello.'),
(v_cap_id, 17, 'Y puso en manos de Jacob su hijo el guisado y el pan que había preparado.'),
(v_cap_id, 18, 'Entonces él fue a su padre y dijo: Padre mío. E Isaac respondió: Heme aquí; ¿quién eres, hijo mío?'),
(v_cap_id, 19, 'Y Jacob dijo a su padre: Yo soy Esaú tu primogénito; he hecho como me dijiste; levántate ahora, y siéntate, y come de mi caza, para que me bendigas.'),
(v_cap_id, 20, 'Entonces Isaac dijo a su hijo: ¿Cómo es que la hallaste tan pronto, hijo mío? Y él respondió: Porque Jehová tu Dios hizo que la encontrase delante de mí.'),
(v_cap_id, 21, 'E Isaac dijo a Jacob: Acércate ahora, y te palparé, hijo mío, por si eres mi hijo Esaú o no.'),
(v_cap_id, 22, 'Y se acercó Jacob a su padre Isaac; quien le palpó y dijo: La voz es la voz de Jacob, pero las manos, las manos de Esaú.'),
(v_cap_id, 23, 'Y no le conoció, porque sus manos eran vellosas como las manos de Esaú; y le bendijo.'),
(v_cap_id, 24, 'Y dijo: ¿Eres tú mi hijo Esaú? Y Jacob respondió: Yo soy.'),
(v_cap_id, 25, 'Entonces dijo: Acércamelo, y comeré de la caza de mi hijo, para que yo te bendiga; y se lo acercó, y comió; y le trajo vino, y bebió.'),
(v_cap_id, 26, 'Y le dijo Isaac su padre: Acércate ahora, y bésame, hijo mío.'),
(v_cap_id, 27, 'Y se acercó, y le besó; y olió Isaac el olor de sus vestidos, y le bendijo, diciendo: Mira, el olor de mi hijo, como el olor del campo que Jehová ha bendecido;'),
(v_cap_id, 28, 'Dios, pues, te dé del rocío del cielo, y de las grosuras de la tierra, y abundancia de trigo y de mosto.'),
(v_cap_id, 29, 'Sírvante pueblos, y naciones se inclinen a ti; sé señor de tus hermanos, e inclínense a ti los hijos de tu madre; malditos los que te maldijeren, y benditos los que te bendijeren.'),
(v_cap_id, 30, 'Y aconteció, luego que Isaac acabó de bendecir a Jacob, y apenas había salido Jacob de delante de Isaac su padre, que Esaú su hermano volvió de la caza.'),
(v_cap_id, 31, 'E hizo también él un guisado, y lo trajo a su padre, y le dijo: Levántese mi padre, y coma de la caza de su hijo, para que me bendiga.'),
(v_cap_id, 32, 'Entonces Isaac su padre le dijo: ¿Quién eres tú? Y él le dijo: Yo soy tu hijo, tu primogénito, Esaú.'),
(v_cap_id, 33, 'Y se estremeció Isaac grandemente, y dijo: ¿Quién, pues, fue el que cazó la caza y me trajo, y yo comí de todo antes que tú vinieses, y le bendije? Será, por tanto, bendito.'),
(v_cap_id, 34, 'Cuando Esaú oyó las palabras de su padre, clamó con una muy grande y amarga exclamación, y le dijo: Bendíceme también a mí, padre mío.'),
(v_cap_id, 35, 'Y él dijo: Vino tu hermano con engaño, y tomó tu bendición.'),
(v_cap_id, 36, 'Y Esaú respondió: Bien llamaron su nombre Jacob, pues ya me ha suplantado dos veces: se apoderó de mi primogenitura, y he aquí ahora ha tomado mi bendición. Y dijo: ¿No has guardado bendición para mí?'),
(v_cap_id, 37, 'Isaac respondió y dijo a Esaú: He aquí yo le he puesto por señor tuyo, y le he dado por siervos a todos sus hermanos; de trigo y de vino le he provisto; ¿qué, pues, haré para ti ahora, hijo mío?'),
(v_cap_id, 38, 'Y Esaú respondió a su padre: ¿No tienes más que una sola bendición, padre mío? Bendíceme también a mí, padre mío. Y alzó Esaú su voz, y lloró.'),
(v_cap_id, 39, 'Entonces Isaac su padre habló y le dijo: He aquí, lejos de las grosuras de la tierra será tu morada, y sin el rocío de los cielos.'),
(v_cap_id, 40, 'Por tu espada vivirás, y a tu hermano servirás; mas sucederá que cuando te fortalezcas, quitarás su yugo de tu cerviz.'),
(v_cap_id, 41, 'Y aborreció Esaú a Jacob por la bendición con que su padre le había bendecido, y dijo en su corazón: Llegarán los días del luto por mi padre, y yo mataré a Jacob mi hermano.'),
(v_cap_id, 42, 'Y fueron dichas a Rebeca las palabras de Esaú su hijo mayor; y ella envió y llamó a Jacob su hijo menor, y le dijo: He aquí, Esaú tu hermano se consuela acerca de ti con la idea de matarte.'),
(v_cap_id, 43, 'Ahora pues, hijo mío, obedece a mi voz; levántate y huye a casa de Labán mi hermano, a Harán,'),
(v_cap_id, 44, 'y mora con él algunos días, hasta que el enojo de tu hermano se mitigue;'),
(v_cap_id, 45, 'hasta que se aplaque la ira de tu hermano contra ti, y se olvide de lo que le has hecho; yo enviaré entonces, y te traeré de allá; ¿por qué seré privada de vosotros ambos en un mismo día?'),
(v_cap_id, 46, 'Y dijo Rebeca a Isaac: Fastidio tengo de mi vida, a causa de las hijas de Het. Si Jacob toma mujer de las hijas de Het, como estas, de las hijas de esta tierra, ¿para qué quiero la vida?')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Entonces Isaac llamó a Jacob, y lo bendijo, y le mandó, diciendo: No tomes mujer de las hijas de Canaán.'),
(v_cap_id, 2, 'Levántate, ve a Padan-aram, a casa de Betuel, padre de tu madre, y toma allí mujer de las hijas de Labán, hermano de tu madre.'),
(v_cap_id, 3, 'Y el Dios omnipotente te bendiga, y te haga fructificar y te multiplique, hasta llegar a ser multitud de pueblos;'),
(v_cap_id, 4, 'y te dé la bendición de Abraham, y a tu descendencia contigo, para que heredes la tierra en que moras, que ha dado Dios a Abraham.'),
(v_cap_id, 5, 'Así envió Isaac a Jacob, el cual fue a Padan-aram, a Labán, hijo de Betuel arameo, hermano de Rebeca, madre de Jacob y de Esaú.'),
(v_cap_id, 6, 'Y vio Esaú cómo Isaac había bendecido a Jacob, y le había enviado a Padan-aram, para tomar allí mujer; y que cuando le bendijo, le mandó, diciendo: No tomarás mujer de las hijas de Canaán;'),
(v_cap_id, 7, 'y que Jacob había obedecido a su padre y a su madre, y se había ido a Padan-aram.'),
(v_cap_id, 8, 'Vio asimismo Esaú que las hijas de Canaán parecían mal a Isaac su padre.'),
(v_cap_id, 9, 'Y fue Esaú a Ismael, y tomó además de sus mujeres a Mahalat, hija de Ismael hijo de Abraham, hermana de Nebaiot, por mujer.'),
(v_cap_id, 10, 'Salió, pues, Jacob de Beerseba, y fue a Harán.'),
(v_cap_id, 11, 'Y llegó a un cierto lugar, y durmió allí, porque ya el sol se había puesto; y tomó de las piedras de aquel lugar y puso a su cabecera, y se acostó en aquel lugar.'),
(v_cap_id, 12, 'Y soñó, y he aquí una escalera que estaba apoyada en tierra, y su extremo tocaba en el cielo; y he aquí ángeles de Dios que subían y descendían por ella.'),
(v_cap_id, 13, 'Y he aquí, Jehová estaba en lo alto de ella, y dijo: Yo soy Jehová, el Dios de Abraham tu padre, y el Dios de Isaac; la tierra en que estás acostado te la daré a ti y a tu descendencia.'),
(v_cap_id, 14, 'Será tu descendencia como el polvo de la tierra, y te extenderás al occidente, y al oriente, al norte y al sur; y todas las familias de la tierra serán benditas en ti y en tu simiente.'),
(v_cap_id, 15, 'He aquí, yo estoy contigo, y te guardaré por dondequiera que fueres, y volveré a traerte a esta tierra; porque no te dejaré hasta que haya hecho lo que te he dicho.'),
(v_cap_id, 16, 'Y despertó Jacob de su sueño, y dijo: Ciertamente Jehová está en este lugar, y yo no lo sabía.'),
(v_cap_id, 17, 'Y tuvo miedo, y dijo: ¡Cuán terrible es este lugar! No es otra cosa que casa de Dios, y puerta del cielo.'),
(v_cap_id, 18, 'Y se levantó Jacob de mañana, y tomó la piedra que había puesto de cabecera, y la alzó por señal, y derramó aceite encima de ella.'),
(v_cap_id, 19, 'Y llamó el nombre de aquel lugar Betel, aunque Luz era el nombre de la ciudad primero.'),
(v_cap_id, 20, 'E hizo Jacob voto, diciendo: Si fuere Dios conmigo, y me guardare en este viaje en que voy, y me diere pan para comer y vestido para vestir,'),
(v_cap_id, 21, 'y si volviere en paz a casa de mi padre, Jehová será mi Dios.'),
(v_cap_id, 22, 'Y esta piedra que he puesto por señal, será casa de Dios; y de todo lo que me dieres, el diezmo apartaré para ti.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Siguió luego Jacob su viaje, y fue a la tierra de los orientales.'),
(v_cap_id, 2, 'Y miró, y vio un pozo en el campo; y he aquí tres rebaños de ovejas que yacían junto a él; porque de aquel pozo abrevaban los rebaños, y había una gran piedra sobre la boca del pozo.'),
(v_cap_id, 3, 'Y juntaban allí todos los rebaños; y revolvían la piedra de la boca del pozo, y abrevaban las ovejas, y volvían la piedra sobre la boca del pozo a su lugar.'),
(v_cap_id, 4, 'Y les dijo Jacob: Hermanos míos, ¿de dónde sois? Y ellos respondieron: De Harán somos.'),
(v_cap_id, 5, 'Y él les dijo: ¿Conocéis a Labán hijo de Nacor? Y ellos dijeron: Sí, le conocemos.'),
(v_cap_id, 6, 'Y él les dijo: ¿Está bien? Y ellos dijeron: Bien, y he aquí Raquel su hija viene con las ovejas.'),
(v_cap_id, 7, 'Y él dijo: He aquí es aún muy de día; no es tiempo todavía de recoger el ganado; abrevad las ovejas, e id a apacentarlas.'),
(v_cap_id, 8, 'Y ellos respondieron: No podemos, hasta que se junten todos los rebaños, y remuevan la piedra de la boca del pozo, para que abrevemos las ovejas.'),
(v_cap_id, 9, 'Mientras él aún hablaba con ellos, vino Raquel con las ovejas de su padre, porque ella las apacentaba.'),
(v_cap_id, 10, 'Y sucedió que cuando Jacob vio a Raquel, hija de Labán hermano de su madre, y las ovejas de Labán el hermano de su madre, se acercó Jacob y removió la piedra de la boca del pozo, y abrevó el rebaño de Labán hermano de su madre.'),
(v_cap_id, 11, 'Y Jacob besó a Raquel, y alzó su voz y lloró.'),
(v_cap_id, 12, 'Y Jacob dijo a Raquel que él era hermano de su padre, e hijo de Rebeca; y ella corrió, y dio las nuevas a su padre.'),
(v_cap_id, 13, 'Y así que oyó Labán las nuevas de Jacob, hijo de su hermana, corrió a recibirlo, y lo abrazó, lo besó, y lo trajo a su casa; y él contó a Labán todas estas cosas.'),
(v_cap_id, 14, 'Y Labán le dijo: Ciertamente hueso mío y carne mía eres. Y estuvo con él durante un mes.'),
(v_cap_id, 15, 'Entonces dijo Labán a Jacob: ¿Por ser tú mi hermano, me servirás de balde? Dime cuál será tu salario.'),
(v_cap_id, 16, 'Y Labán tenía dos hijas: el nombre de la mayor era Lea, y el nombre de la menor, Raquel.'),
(v_cap_id, 17, 'Y los ojos de Lea eran tiernos, pero Raquel era de hermoso semblante y de hermoso parecer.'),
(v_cap_id, 18, 'Y Jacob amó a Raquel, y dijo: Yo te serviré siete años por Raquel tu hija menor.'),
(v_cap_id, 19, 'Y Labán respondió: Mejor es que te la dé a ti, que no que la dé a otro hombre; quédate conmigo.'),
(v_cap_id, 20, 'Así sirvió Jacob por Raquel siete años; y le parecieron como pocos días, porque la amaba.'),
(v_cap_id, 21, 'Entonces dijo Jacob a Labán: Dame mi mujer, porque mi tiempo se ha cumplido, para que me llegue a ella.'),
(v_cap_id, 22, 'Entonces Labán juntó a todos los varones de aquel lugar, e hizo banquete.'),
(v_cap_id, 23, 'Pero sucedió que a la noche tomó a Lea su hija, y se la trajo; y él se llegó a ella.'),
(v_cap_id, 24, 'Y Labán dio su sierva Zilpa a su hija Lea por criada.'),
(v_cap_id, 25, 'Y cuando fue de mañana, he aquí que era Lea; y Jacob dijo a Labán: ¿Qué es esto que me has hecho? ¿No te he servido por Raquel? ¿Por qué, pues, me has engañado?'),
(v_cap_id, 26, 'Y Labán respondió: No se hace así en nuestro lugar, que se dé la menor antes que la mayor.'),
(v_cap_id, 27, 'Cumple la semana de esta, y se te dará también la otra, por el servicio que hicieres conmigo otros siete años.'),
(v_cap_id, 28, 'E hizo Jacob así, y cumplió la semana de aquella; y él le dio a Raquel su hija por mujer.'),
(v_cap_id, 29, 'Y Labán dio su sierva Bilha a su hija Raquel por criada.'),
(v_cap_id, 30, 'Y se llegó también a Raquel, y la amó también más que a Lea; y sirvió a Labán aún otros siete años.'),
(v_cap_id, 31, 'Y vio Jehová que Lea era menospreciada, y le concedió hijos; pero Raquel era estéril.'),
(v_cap_id, 32, 'Y concibió Lea, y dio a luz un hijo, y llamó su nombre Rubén, porque dijo: Ha mirado Jehová mi aflicción; ahora, por tanto, me amará mi marido.'),
(v_cap_id, 33, 'Concibió otra vez, y dio a luz un hijo, y dijo: Por cuanto oyó Jehová que era menospreciada, me ha dado también éste. Y llamó su nombre Simeón.'),
(v_cap_id, 34, 'Y concibió otra vez, y dio a luz un hijo, y dijo: Ahora esta vez se unirá mi marido conmigo, porque le he dado tres hijos. Por tanto llamó su nombre Leví.'),
(v_cap_id, 35, 'Y concibió otra vez, y dio a luz un hijo, y dijo: Esta vez alabaré a Jehová; por esto llamó su nombre Judá; y dejó de dar a luz.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Viendo Raquel que no daba hijos a Jacob, tuvo envidia de su hermana, y dijo a Jacob: Dame hijos, o si no, me muero.'),
(v_cap_id, 2, 'Y Jacob se enojó contra Raquel, y dijo: ¿Soy yo acaso Dios, que te impidió el fruto de tu vientre?'),
(v_cap_id, 3, 'Y ella dijo: He aquí mi sierva Bilha; llégate a ella, y dará a luz sobre mis rodillas, y yo también tendré hijos de ella.'),
(v_cap_id, 4, 'Así le dio a Bilha su sierva por mujer; y Jacob se llegó a ella.'),
(v_cap_id, 5, 'Y concibió Bilha, y dio a luz un hijo a Jacob.'),
(v_cap_id, 6, 'Dijo entonces Raquel: Me juzgó Dios, y también oyó mi voz, y me dio un hijo. Por tanto llamó su nombre Dan.'),
(v_cap_id, 7, 'Y concibió otra vez Bilha la sierva de Raquel, y dio a luz un segundo hijo a Jacob.'),
(v_cap_id, 8, 'Y dijo Raquel: Con luchas de Dios he luchado con mi hermana, y he vencido. Y llamó su nombre Neftalí.'),
(v_cap_id, 9, 'Viendo, pues, Lea que había dejado de dar a luz, tomó a Zilpa su sierva, y la dio a Jacob por mujer.'),
(v_cap_id, 10, 'Y Zilpa, sierva de Lea, dio a luz un hijo a Jacob.'),
(v_cap_id, 11, 'Y dijo Lea: Vino la ventura. Y llamó su nombre Gad.'),
(v_cap_id, 12, 'Y Zilpa la sierva de Lea dio a luz otro hijo a Jacob.'),
(v_cap_id, 13, 'Y dijo Lea: Para dicha mía; porque las mujeres me dirán dichosa. Y llamó su nombre Aser.'),
(v_cap_id, 14, 'Fue Rubén en tiempo de la siega de los trigos, y halló mandrágoras en el campo, y las trajo a Lea su madre; y dijo Raquel a Lea: Te ruego que me des de las mandrágoras de tu hijo.'),
(v_cap_id, 15, 'Y ella respondió: ¿Te parece que es poco haber tomado mi marido, sino que también te has de llevar las mandrágoras de mi hijo? Y dijo Raquel: Pues dormirá contigo esta noche por las mandrágoras de tu hijo.'),
(v_cap_id, 16, 'Cuando, pues, Jacob volvía del campo a la tarde, salió Lea a él, y le dijo: Llégate a mí, porque a la verdad te he alquilado por las mandrágoras de mi hijo. Y durmió con ella aquella noche.'),
(v_cap_id, 17, 'Y oyó Dios a Lea, y concibió, y dio a luz el quinto hijo a Jacob.'),
(v_cap_id, 18, 'Y dijo Lea: Dios me ha dado mi recompensa, por cuanto di mi sierva a mi marido; por lo llamó su nombre Isacar.'),
(v_cap_id, 19, 'Y concibió Lea otra vez, y dio a luz el sexto hijo a Jacob.'),
(v_cap_id, 20, 'Y dijo Lea: Dios me ha dado una buena dote; ahora morará conmigo mi marido, porque le he dado seis hijos; y llamó su nombre Zabulón.'),
(v_cap_id, 21, 'Después dio a luz una hija, y llamó su nombre Dina.'),
(v_cap_id, 22, 'Y se acordó Dios de Raquel, y la oyó Dios, y le concedió hijos.'),
(v_cap_id, 23, 'Y concibió, y dio a luz un hijo, y dijo: Dios ha quitado mi afrenta;'),
(v_cap_id, 24, 'y llamó su nombre José, diciendo: Añádame Jehová otro hijo.'),
(v_cap_id, 25, 'Aconteció cuando Raquel hubo dado a luz a José, que Jacob dijo a Labán: Envíame, e iré a mi lugar, y a mi tierra.'),
(v_cap_id, 26, 'Dame mis mujeres y mis hijos, por las cuales he servido, y déjame ir; pues tú sabes los servicios que te he hecho.'),
(v_cap_id, 27, 'Y Labán le respondió: Halle yo ahora gracia en tus ojos, y quédate; experiencia tengo que Jehová me ha bendecido por tu causa.'),
(v_cap_id, 28, 'Y dijo: Señálame tu salario, y yo lo daré.'),
(v_cap_id, 29, 'Y él respondió: Tú sabes cómo te he servido, y cómo ha estado tu ganado conmigo.'),
(v_cap_id, 30, 'Porque poco tenías antes de mi venida, y ha crecido en gran número, y Jehová te ha bendecido con mi llegada; y ahora, ¿cuándo trabajaré también por mi propia casa?'),
(v_cap_id, 31, 'Y él dijo: ¿Qué te daré? Y respondió Jacob: No me des nada; si hicieres por mí esto, volveré a apacentar tus rebaños.'),
(v_cap_id, 32, 'Pasaré hoy por todo tu rebaño, poniendo aparte todas las ovejas manchadas y de color, y todas las ovejas de color oscuro, y las manchadas y de color entre las cabras; y eso será mi salario.'),
(v_cap_id, 33, 'Así responderá por mí mi honradez mañana, cuando vengas a reconocer mi salario; toda la que no fuere manchada ni de color entre las cabras, ni oscura entre las ovejas, o sea de color, se me ha de tener como hurto.'),
(v_cap_id, 34, 'Y dijo Labán: Sea, conforme a tu dicho.'),
(v_cap_id, 35, 'Y apartó aquel mismo día los machos cabríos rayados y manchados, y todas las cabras manchadas y de color, y toda oveja oscura, y todas las manchadas y de color, y las puso en mano de sus hijos.'),
(v_cap_id, 36, 'Y puso tres días de camino entre sí y Jacob; y Jacob apacentaba las otras ovejas de Labán.'),
(v_cap_id, 37, 'Y tomó Jacob varas verdes de álamo, de avellano y de castaño, y descortezó en ellas mondaduras blancas, descubriendo así lo blanco de las varas.'),
(v_cap_id, 38, 'Y puso las varas que había mondado delante del ganado, en los abrevaderos, en los canales de agua, donde venían a beber las ovejas, las cuales se calentaban cuando venían a beber.'),
(v_cap_id, 39, 'Y concebían las ovejas delante de las varas, y parían borregos listados, manchados y salpicados.'),
(v_cap_id, 40, 'Y apartaba Jacob los corderos, y ponía con su propio rebaño los listados y todo lo que era oscuro en el hato de Labán. Y ponía su rebaño aparte, y no lo ponía con las ovejas de Labán.'),
(v_cap_id, 41, 'Y sucedía que cuantas veces se calentaban las ovejas fuertes, Jacob ponía las varas delante de las ovejas en los abrevaderos, para que concibiesen a la vista de las varas.'),
(v_cap_id, 42, 'Pero cuando las ovejas eran débiles, no las ponía; así, las débiles eran para Labán, y las fuertes para Jacob.'),
(v_cap_id, 43, 'Y el varón se enriqueció muchísimo, y tuvo muchas ovejas, y siervas y siervos, y camellos y asnos.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Y oía Jacob las palabras de los hijos de Labán, que decían: Jacob ha tomado todo lo que era de nuestro padre, y de lo que era de nuestro padre ha adquirido toda esta riqueza.'),
(v_cap_id, 2, 'Miraba también Jacob el semblante de Labán, y veía que no era para con él como había sido antes.'),
(v_cap_id, 3, 'También Jehová dijo a Jacob: Vuélvete a la tierra de tus padres, y a tu parentela, y yo estaré contigo.'),
(v_cap_id, 4, 'Envió, pues, Jacob, y llamó a Raquel y a Lea al campo donde estaban sus ovejas,'),
(v_cap_id, 5, 'y les dijo: Veo que el semblante de vuestro padre no es para conmigo como era antes; mas el Dios de mi padre ha estado conmigo.'),
(v_cap_id, 6, 'Vosotras sabéis que con todas mis fuerzas he servido a vuestro padre;'),
(v_cap_id, 7, 'y vuestro padre me ha engañado, y me ha cambiado el salario diez veces; pero Dios no le ha permitido que me hiciese mal.'),
(v_cap_id, 8, 'Si él decía así: Los pintados serán tu salario, entonces todas las ovejas parían pintados; y si decía así: Los listados serán tu salario, entonces todas las ovejas parían listados.'),
(v_cap_id, 9, 'Así quitó Dios el ganado de vuestro padre, y me lo dio a mí.'),
(v_cap_id, 10, 'Y sucedió que al tiempo que las ovejas estaban encendidas, alcé yo mis ojos y vi en sueños, y he aquí los machos que montaban a las ovejas eran listados, pintados y abigarrados.'),
(v_cap_id, 11, 'Y me dijo el ángel de Dios en sueños: Jacob. Y yo dije: Heme aquí.'),
(v_cap_id, 12, 'Y él dijo: Alza ahora tus ojos, y ve todos los machos que montan a las ovejas, que son listados, pintados y abigarrados; porque he visto todo lo que Labán te ha hecho.'),
(v_cap_id, 13, 'Yo soy el Dios de Betel, donde tú ungiste la piedra, y donde me hiciste un voto. Levántate ahora y sal de esta tierra, y vuélvete a la tierra de tu nacimiento.'),
(v_cap_id, 14, 'Respondieron Raquel y Lea, y le dijeron: ¿Tenemos todavía parte o heredad en la casa de nuestro padre?'),
(v_cap_id, 15, '¿No nos tiene ya como por extrañas, pues que nos vendió, y aun se ha comido del todo nuestro precio?'),
(v_cap_id, 16, 'Porque toda la riqueza que Dios ha quitado a nuestro padre, nuestra es y de nuestros hijos; ahora, pues, haz todo lo que Dios te ha dicho.'),
(v_cap_id, 17, 'Entonces se levantó Jacob, y subió sus hijos y sus mujeres sobre los camellos,'),
(v_cap_id, 18, 'y puso en camino todo su ganado, y todo cuanto había adquirido, el ganado de su ganancia que había obtenido en Padan-aram, para volverse a Isaac su padre en la tierra de Canaán.'),
(v_cap_id, 19, 'Pero Labán había ido a trasquilar sus ovejas; y Raquel hurtó los ídolos de su padre.'),
(v_cap_id, 20, 'Y Jacob engañó a Labán arameo, no haciéndole saber que se iba.'),
(v_cap_id, 21, 'Huyó, pues, con todo lo que tenía; y se levantó, y pasó el Eufrates, y se dirigió al monte de Galaad.'),
(v_cap_id, 22, 'Y al tercer día fue dicho a Labán que Jacob había huido.'),
(v_cap_id, 23, 'Entonces tomó a sus parientes consigo, y fue tras él camino de siete días, y le alcanzó en el monte de Galaad.'),
(v_cap_id, 24, 'Y vino Dios a Labán arameano en sueños aquella noche, y le dijo: Guárdate que no hables a Jacob descomedidamente.'),
(v_cap_id, 25, 'Alcanzó, pues, Labán a Jacob; y Jacob había fijado su tienda en el monte; y Labán acampó con sus parientes en el monte de Galaad.'),
(v_cap_id, 26, 'Y dijo Labán a Jacob: ¿Qué has hecho, que me engañaste, y has traído a mis hijas como prisioneras de guerra?'),
(v_cap_id, 27, '¿Por qué te escondiste para huir, y me engañaste, y no me lo hiciste saber para que yo te despidiera con alegría y con cantos, con tamborín y arpa?'),
(v_cap_id, 28, 'Pues ni aun me dejaste besar a mis hijos y a mis hijas. Ahora, locamente has hecho.'),
(v_cap_id, 29, 'Poder hay en mi mano para haceros mal; mas el Dios de tu padre me habló anoche, diciendo: Guárdate que no hables a Jacob descomedidamente.'),
(v_cap_id, 30, 'Y ya te fueses, porque tenías deseo de la casa de tu padre; ¿por qué hurtaste mis dioses?'),
(v_cap_id, 31, 'Respondió Jacob y dijo a Labán: Porque tuve miedo; pues pensé que quizá me quitarías por fuerza tus hijas.'),
(v_cap_id, 32, 'Aquel en quien hallares tus dioses, no viva; reconoce delante de nuestros hermanos lo que tuyo se halle conmigo, y tómalo. Jacob no sabía que Raquel los había hurtado.'),
(v_cap_id, 33, 'Entonces Labán entró en la tienda de Jacob, y en la tienda de Lea, y en la tienda de las dos siervas, y no los halló; y salió de la tienda de Lea, y entró en la tienda de Raquel.'),
(v_cap_id, 34, 'Pero tomó Raquel los ídolos, y los puso en una albarda de un camello, y se sentó sobre ellos; y registró Labán toda la tienda, y no los halló.'),
(v_cap_id, 35, 'Y ella dijo a su padre: No se enoje mi señor, porque no me puedo levantar delante de ti; pues estoy con la costumbre de las mujeres. Y él buscó, pero no halló los ídolos.'),
(v_cap_id, 36, 'Entonces Jacob se enojó, y riñó con Labán; y respondió Jacob y dijo a Labán: ¿Cuál es mi delito? ¿Cuál es mi pecado, para que con tanto ardor hayas perseguido?'),
(v_cap_id, 37, 'Pues que has registrado todas mis alhajas, ¿qué has hallado de todos los enseres de tu casa? Ponlo aquí delante de mis hermanos y de los tuyos, y juzguen entre nosotros dos.'),
(v_cap_id, 38, 'Estos veinte años he estado contigo; tus ovejas y tus cabras nunca abortaron, ni yo comí carneros de tus rebaños.'),
(v_cap_id, 39, 'Nunca te traje lo arrebatado por las fieras: yo pagaba el daño; lo hurtado así de día como de noche, a mí me lo cobrabas.'),
(v_cap_id, 40, 'De día me consumía el calor, y de noche la helada, y el sueño huía de mis ojos.'),
(v_cap_id, 41, 'Así he estado veinte años en tu casa; catorce años te serví por tus dos hijas, y seis años por tu ganado, y has cambiado mi salario diez veces.'),
(v_cap_id, 42, 'Si el Dios de mi padre, Dios de Abraham, y el temor de Isaac, no estuviera conmigo, de cierto me enviarías ahora con las manos vacías; pero Dios vio mi aflicción y el trabajo de mis manos, y anoche sentenció.'),
(v_cap_id, 43, 'Respondió Labán y dijo a Jacob: Las hijas son hijas mías, y los hijos son hijos míos, y las ovejas son mis ovejas, y todo lo que ves es mío; ¿y qué puedo yo hacer hoy a estas mis hijas, o a sus hijos que ellas han dado a luz?'),
(v_cap_id, 44, 'Ven, pues, ahora, hagamos pacto tú y yo, y sea por testimonio entre nosotros dos.'),
(v_cap_id, 45, 'Entonces Jacob tomó una piedra, y la levantó por señal.'),
(v_cap_id, 46, 'Y dijo Jacob a sus parientes: Recoged piedras. Y tomaron piedras e hicieron un montón, y comieron allí sobre el montón.'),
(v_cap_id, 47, 'Y llamó Labán aquel montón Jegar Sahaduta; y lo llamó Jacob Galeed.'),
(v_cap_id, 48, 'Porque Labán dijo: Este montón es testigo hoy entre nosotros dos; por eso fue llamado Galeed;'),
(v_cap_id, 49, 'también Mizpa, por cuanto dijo: Atalaye Jehová entre tú y yo, cuando nos apartemos el uno del otro.'),
(v_cap_id, 50, 'Si afligieres a mis hijas, o si tomares otras mujeres además de mis hijas, aunque nadie esté con nosotros, mira, Dios es testigo entre nosotros dos.'),
(v_cap_id, 51, 'Dijo más Labán a Jacob: He aquí este montón, y he aquí esta señal que he levantado entre tú y yo.'),
(v_cap_id, 52, 'Testigo sea este montón, y testigo sea esta señal, que ni yo pasaré de este montón contra ti, ni tú pasarás de este montón ni de esta señal contra mí, para mal.'),
(v_cap_id, 53, 'El Dios de Abraham y el Dios de Nacor juzgue entre nosotros, el Dios de sus padres. Y Jacob juró por el temor de Isaac su padre.'),
(v_cap_id, 54, 'Entonces Jacob ofreció un sacrificio en el monte, y llamó a sus parientes a comer pan; y comieron pan, y durmieron aquella noche en el monte.'),
(v_cap_id, 55, 'Y se levantó Labán de mañana, y besó a sus hijos y a sus hijas, y los bendijo; y luego partió y se volvió a su lugar.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Jacob siguió su camino, y le salieron al encuentro ángeles de Dios.'),
(v_cap_id, 2, 'Y dijo Jacob cuando los vio: Campamento de Dios es esto; y llamó el nombre de aquel lugar Mahanaim.'),
(v_cap_id, 3, 'Y envió Jacob mensajeros delante de sí a Esaú su hermano, a la tierra de Seir, campo de Edom.'),
(v_cap_id, 4, 'Y les mandó diciendo: Así diréis a mi señor Esaú: Así dice tu siervo Jacob: Con Labán he morado y me he detenido hasta ahora;'),
(v_cap_id, 5, 'y tengo vacas, asnos, ovejas, siervos y siervas; y envío a decírselo a mi señor, para hallar gracia en tus ojos.'),
(v_cap_id, 6, 'Y los mensajeros volvieron a Jacob, diciendo: Fuimos a tu hermano Esaú, y él también viene a recibirte, y cuatrocientos hombres con él.'),
(v_cap_id, 7, 'Entonces Jacob tuvo gran temor, y se angustió; y partió el pueblo que tenía consigo, y las ovejas y las vacas y los camellos, en dos campamentos;'),
(v_cap_id, 8, 'y dijo: Si viene Esaú contra un campamento y lo ataca, el otro campamento escapará.'),
(v_cap_id, 9, 'Y dijo Jacob: Dios de mi padre Abraham, y Dios de mi padre Isaac, oh Jehová, que me dijiste: Vuélvete a tu tierra y a tu parentela, y yo te haré bien;'),
(v_cap_id, 10, 'menor soy que todas las misericordias y que toda la verdad que has usado para con tu siervo; pues con mi cayado pasé este Jordán, y ahora estoy sobre dos campamentos.'),
(v_cap_id, 11, 'Líbrame ahora de la mano de mi hermano, de la mano de Esaú, porque le temo; no venga acaso y me hiera la madre con los hijos.'),
(v_cap_id, 12, 'Y tú has dicho: Yo te haré bien, y tu descendencia será como la arena del mar, que no se puede contar por la multitud.'),
(v_cap_id, 13, 'Y durmió allí aquella noche, y tomó de lo que tenía consigo un presente para su hermano Esaú:'),
(v_cap_id, 14, 'doscientas cabras y veinte machos cabríos, doscientas ovejas y veinte carneros,'),
(v_cap_id, 15, 'treinta camellas paridas con sus hijuelos, cuarenta vacas y diez novillos, veinte asnas y diez asnos.'),
(v_cap_id, 16, 'Y los entregó a sus siervos, cada manada por separado, y dijo a sus siervos: Pasad delante de mí, y poned espacio entre manada y manada.'),
(v_cap_id, 17, 'Y mandó al primero, diciendo: Si Esaú mi hermano te encontrare, y te preguntare, diciendo: ¿De quién eres, y adónde vas, y de quién son estos que van delante de ti?'),
(v_cap_id, 18, 'entonces dirás: De tu siervo Jacob; que es presente enviado a mi señor Esaú; y he aquí también él viene tras nosotros.'),
(v_cap_id, 19, 'Mandó también al segundo, y al tercero, y a todos los que iban tras aquellas manadas, diciendo: Conforme a esto hablaréis a Esaú cuando le halléis.'),
(v_cap_id, 20, 'Y diréis también: He aquí tu siervo Jacob viene tras nosotros. Porque pensó: Apaciguaré su ira con el presente que va delante de mí, y después veré su rostro; quizá me aceptará.'),
(v_cap_id, 21, 'Pasó, pues, el presente delante de él; y él durmió aquella noche en el campamento.'),
(v_cap_id, 22, 'Y se levantó aquella noche, y tomó sus dos mujeres, y sus dos siervas, y sus once hijos, y pasó el vado de Jaboc.'),
(v_cap_id, 23, 'Los tomó, pues, y los hizo pasar el arroyo, e hizo pasar todo lo que tenía.'),
(v_cap_id, 24, 'Así se quedó Jacob solo; y luchó con él un varón hasta que rayaba el alba.'),
(v_cap_id, 25, 'Y cuando el varón vio que no podía con él, tocó en el encaje de su muslo, y se descoyuntó el muslo de Jacob mientras con él luchaba.'),
(v_cap_id, 26, 'Y dijo: Déjame, porque raya el alba. Y Jacob respondió: No te dejaré, si no me bendices.'),
(v_cap_id, 27, 'Y el varón le dijo: ¿Cuál es tu nombre? Y él respondió: Jacob.'),
(v_cap_id, 28, 'Y el varón le dijo: No se dirá más tu nombre Jacob, sino Israel; porque has luchado con Dios y con los hombres, y has vencido.'),
(v_cap_id, 29, 'Entonces Jacob le preguntó, y dijo: Declárame ahora tu nombre. Y el varón respondió: ¿Por qué preguntas por mi nombre? Y lo bendijo allí.'),
(v_cap_id, 30, 'Y llamó Jacob el nombre de aquel lugar, Peniel; porque dijo: Vi a Dios cara a cara, y fue librada mi alma.'),
(v_cap_id, 31, 'Y le salió el sol cuando pasaba a Peniel; y cojeaba de su muslo.'),
(v_cap_id, 32, 'Por esto no comen los hijos de Israel, hasta hoy, del tendón que se contrajo, el cual está en el encaje del muslo; porque tocó a Jacob en el encaje de su muslo en el tendón que se contrajo.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Alzó Jacob sus ojos, y miró, y he aquí venía Esaú, y cuatrocientos hombres con él; entonces repartió él los niños entre Lea y Raquel y las dos siervas.'),
(v_cap_id, 2, 'Y puso las siervas y sus niños delante, luego a Lea y sus niños, y a Raquel y a José los últimos.'),
(v_cap_id, 3, 'Y él pasó delante de ellos, y se inclinó a tierra siete veces, hasta que llegó a su hermano.'),
(v_cap_id, 4, 'Pero Esaú corrió a su encuentro, y le abrazó, y se echó sobre su cuello, y le besó, y lloraron.'),
(v_cap_id, 5, 'Y alzó sus ojos y vio a las mujeres y los niños, y dijo: ¿Qué te tocan éstos? Y él respondió: Son los niños que Dios ha dado a tu siervo.'),
(v_cap_id, 6, 'Entonces se acercaron las siervas, ellas y sus niños, y se inclinaron.'),
(v_cap_id, 7, 'Y se acercó también Lea con sus niños, y se inclinaron; y después se acercó José y Raquel, y también se inclinaron.'),
(v_cap_id, 8, 'Y Esaú dijo: ¿Qué te propones con todas estas cuadrillas que he encontrado? Y Jacob respondió: El hallar gracia en los ojos de mi señor.'),
(v_cap_id, 9, 'Y dijo Esaú: Suficiente tengo yo, hermano mío; sea para ti lo que es tuyo.'),
(v_cap_id, 10, 'Y Jacob respondió: No, yo te ruego, si he hallado ahora gracia en tus ojos, acepta mi presente, porque he visto tu rostro, como si hubiera visto el rostro de Dios, pues que tú me has recibido favorablemente.'),
(v_cap_id, 11, 'Acepta, te ruego, mi presente que te he traído, porque Dios me ha hecho merced, y todo lo que hay aquí es mío. Y le insistió, y él tomó.'),
(v_cap_id, 12, 'Y Esaú dijo: Anda, vamos; y yo iré delante de ti.'),
(v_cap_id, 13, 'Y Jacob le dijo: Mi señor sabe que los niños son tiernos, y que tengo ovejas y vacas paridas; si las fatigan, en un día morirán todas las ovejas.'),
(v_cap_id, 14, 'Pase ahora mi señor delante de su siervo, y yo me iré poco a poco al paso del ganado que va delante de mí, y al paso de los niños, hasta que llegue a mi señor a Seir.'),
(v_cap_id, 15, 'Y Esaú dijo: Dejaré ahora contigo de la gente que viene conmigo. Y Jacob dijo: ¿Para qué esto? Halle yo gracia en los ojos de mi señor.'),
(v_cap_id, 16, 'Así volvió Esaú aquel día por su camino a Seir.'),
(v_cap_id, 17, 'Y Jacob fue a Sucot, y edificó allí casa para sí, e hizo cabañas para su ganado; por tanto, llamó el nombre de aquel lugar Sucot.'),
(v_cap_id, 18, 'Después Jacob llegó sano y salvo a la ciudad de Siquem, que está en la tierra de Canaán, cuando venía de Padan-aram; y acampó delante de la ciudad.'),
(v_cap_id, 19, 'Y compró una parte del campo, donde plantó su tienda, de mano de los hijos de Hamor, padre de Siquem, por cien monedas.'),
(v_cap_id, 20, 'Y erigió allí un altar, y lo llamó El-Elohe-Israel.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Salió Dina la hija de Lea, la cual había dado a luz a Jacob, a ver a las hijas del país.'),
(v_cap_id, 2, 'Y la vio Siquem hijo de Hamor heveo, príncipe de aquella tierra, y la tomó, y se acostó con ella, y la deshonró.'),
(v_cap_id, 3, 'Mas su alma se apegó a Dina, la hija de Lea, y se enamoró de la joven, y habló al corazón de ella.'),
(v_cap_id, 4, 'Y habló Siquem a su padre Hamor, diciendo: Tómame por mujer a esta joven.'),
(v_cap_id, 5, 'Oyó Jacob que Siquem había amancillado a Dina su hija; y estando sus hijos con su ganado en el campo, calló Jacob hasta que viniesen.'),
(v_cap_id, 6, 'Y se dirigió Hamor padre de Siquem a Jacob, para hablar con él.'),
(v_cap_id, 7, 'Y los hijos de Jacob vinieron del campo cuando lo supieron; y se entristecieron los varones, y se enojaron mucho, porque hizo vileza en Israel acostándose con la hija de Jacob, lo que no se debía haber hecho.'),
(v_cap_id, 8, 'Y Hamor habló con ellos, diciendo: El alma de mi hijo Siquem se ha apegado a vuestra hija; os ruego que se la deis por mujer.'),
(v_cap_id, 9, 'Y emparentad con nosotros; dadnos vuestras hijas, y tomad vosotros las nuestras.'),
(v_cap_id, 10, 'Y habitad con nosotros; porque la tierra estará delante de vosotros; morad y negociad en ella, y tomad en ella posesión.'),
(v_cap_id, 11, 'Siquem también dijo al padre de Dina y a los hermanos de ella: Halle yo gracia en vuestros ojos, y daré lo que me dijereis.'),
(v_cap_id, 12, 'Aumentad a cargo mío mucha dote y dones, y yo daré cuanto me dijereis, y dadme la joven por mujer.'),
(v_cap_id, 13, 'Y respondieron los hijos de Jacob a Siquem y a Hamor su padre, con palabras engañosas, por cuanto había amancillado a Dina su hermana.'),
(v_cap_id, 14, 'Y les dijeron: No podemos hacer esto, el dar nuestra hermana a hombre incircunciso, porque entre nosotros es abominación.'),
(v_cap_id, 15, 'Mas con esta condición os complaceremos: si habéis de ser como nosotros, que se circuncide entre vosotros todo varón.'),
(v_cap_id, 16, 'Entonces os daremos nuestras hijas, y tomaremos nosotros las vuestras; y habitaremos con vosotros, y seremos un pueblo.'),
(v_cap_id, 17, 'Mas si no nos prestareis oídos para circuncidaros, tomaremos nuestra hija y nos iremos.'),
(v_cap_id, 18, 'Y parecieron bien sus palabras a Hamor y a Siquem hijo de Hamor.'),
(v_cap_id, 19, 'Y no tardó el joven en hacer aquello, porque la hija de Jacob le había agradado; y él era el más distinguido de toda la casa de su padre.'),
(v_cap_id, 20, 'Entonces Vinieron Hamor y Siquem su hijo a la puerta de su ciudad, y hablaron a los varones de su ciudad, diciendo:'),
(v_cap_id, 21, 'Estos varones son pacíficos con nosotros, y habitarán en el país, y negociarán en él; pues he aquí la tierra es bastante ancha para ellos; nosotros tomaremos sus hijas por mujeres, y les daremos las nuestras.'),
(v_cap_id, 22, 'Mas con esta condición consentirán estos varones en habitar con nosotros, para que seamos un pueblo: que se circuncide todo varón entre nosotros, así como ellos son circuncidados.'),
(v_cap_id, 23, 'Sus ganados, sus bienes y todas sus bestias, ¿no serán nuestros? Convengamos, pues, con ellos, y habitarán con nosotros.'),
(v_cap_id, 24, 'Y obedecieron a Hamor y a Siquem su hijo todos los que salían a la puerta de la ciudad, y circuncidaron a todo varón, a cuantos salían a la puerta de la ciudad.'),
(v_cap_id, 25, 'Pero sucedió que al tercer día, cuando sentían ellos el mayor dolor, dos de los hijos de Jacob, Simeón y Leví, hermanos de Dina, tomaron cada uno su espada, y vinieron contra la ciudad, que estaba desprevenida, y mataron a todo varón.'),
(v_cap_id, 26, 'Y a Hamor y a Siquem su hijo los mataron a filo de espada; y tomaron a Dina de casa de Siquem, y se fueron.'),
(v_cap_id, 27, 'Y los hijos de Jacob vinieron a los muertos, y saquearon la ciudad, por cuanto habían amancillado a su hermana.'),
(v_cap_id, 28, 'Tomaron sus ovejas y sus vacas y sus asnos, y lo que había en la ciudad y en el campo,'),
(v_cap_id, 29, 'y todo cuanto tenían, y todos sus niños y sus mujeres tomaron cautivos, y saquearon todo lo que había en las casas.'),
(v_cap_id, 30, 'Entonces dijo Jacob a Simeón y a Leví: Me habéis turbado con hacerme abominable a los moradores de esta tierra, al cananeo y al ferezeo; y teniendo yo pocos hombres, se juntarán contra mí y me atacarán, y seré destruido yo y mi casa.'),
(v_cap_id, 31, 'Y ellos respondieron: ¿Había él de tratar a nuestra hermana como a una ramera?')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Dijo Dios a Jacob: Levántate y sube a Betel, y quédate allí; y haz allí un altar al Dios que te apareció cuando huías de tu hermano Esaú.'),
(v_cap_id, 2, 'Entonces Jacob dijo a su familia y a todos los que con él estaban: Quitad los dioses ajenos que hay entre vosotros, y limpiaos, y mudad vuestros vestidos.'),
(v_cap_id, 3, 'Y levantémonos, y subamos a Betel; y haré allí altar al Dios que me respondió en el día de mi angustia, y ha estado conmigo en el camino que he andado.'),
(v_cap_id, 4, 'Así entregaron a Jacob todos los dioses ajenos que había en poder de ellos, y los zarcillos que estaban en sus orejas; y Jacob los escondió debajo de una encina que estaba junto a Siquem.'),
(v_cap_id, 5, 'Y salieron, y el terror de Dios estuvo sobre las ciudades que había en sus alrededores, y no persiguieron a los hijos de Jacob.'),
(v_cap_id, 6, 'Y llegó Jacob a Luz, que está en tierra de Canaán (esta es Betel), él y todo el pueblo que con él estaba.'),
(v_cap_id, 7, 'Y edificó allí un altar, y llamó al lugar El-betel, porque allí le había aparecido Dios, cuando huía de su hermano.'),
(v_cap_id, 8, 'Entonces murió Débora, ama de Rebeca, y fue sepultada al pie de Betel, debajo de una encina, la cual fue llamada Alón-bacut.'),
(v_cap_id, 9, 'Y se apareció otra vez Dios a Jacob, cuando había vuelto de Padan-aram, y le bendijo.'),
(v_cap_id, 10, 'Y le dijo Dios: Tu nombre es Jacob; no se llamará más tu nombre Jacob, sino Israel será tu nombre; y llamó su nombre Israel.'),
(v_cap_id, 11, 'También le dijo Dios: Yo soy el Dios omnipotente; crece y multiplícate; una nación y un conjunto de naciones procederán de ti, y reyes saldrán de tus lomos.'),
(v_cap_id, 12, 'La tierra que he dado a Abraham y a Isaac, la daré a ti, y a tu descendencia después de ti daré la tierra.'),
(v_cap_id, 13, 'Y se fue Dios de él, del lugar donde con él había hablado.'),
(v_cap_id, 14, 'Entonces Jacob erigió una señal de piedra en el lugar donde había hablado con él, una señal de piedra, y derramó sobre ella libación, y echó sobre ella aceite.'),
(v_cap_id, 15, 'Y llamó Jacob el nombre de aquel lugar donde Dios había hablado con él, Betel.'),
(v_cap_id, 16, 'Después partieron de Betel, y hubo aún como media legua de tierra para llegar a Efrata, y dio a luz Raquel, y hubo trabajo en su parto.'),
(v_cap_id, 17, 'Y aconteció que como había trabajo en su parto, le dijo la partera: No temas, que también tendrás este hijo.'),
(v_cap_id, 18, 'Y aconteció que al salírsele el alma (pues murió), le llamó Benoni; mas su padre lo llamó Benjamín.'),
(v_cap_id, 19, 'Así murió Raquel, y fue sepultada en el camino de Efrata, la cual es Belén.'),
(v_cap_id, 20, 'Y levantó Jacob una señal sobre su sepultura; esta es la señal de la sepultura de Raquel hasta hoy.'),
(v_cap_id, 21, 'Y salió Israel, y plantó su tienda más allá de Migdal-eder.'),
(v_cap_id, 22, 'Y aconteció que morando Israel en aquella tierra, fue Rubén y durmió con Bilha, la concubina de su padre; lo cual llegó a saber Israel. Ahora bien, los hijos de Israel fueron doce:'),
(v_cap_id, 23, 'Los hijos de Lea: Rubén, el primogénito de Jacob; Simeón, Leví, Judá, Isacar y Zabulón.'),
(v_cap_id, 24, 'Los hijos de Raquel: José y Benjamín.'),
(v_cap_id, 25, 'Los hijos de Bilha, sierva de Raquel: Dan y Neftalí.'),
(v_cap_id, 26, 'Los hijos de Zilpa, sierva de Lea: Gad y Aser. Estos fueron los hijos de Jacob que le nacieron en Padan-aram.'),
(v_cap_id, 27, 'Después vino Jacob a Isaac su padre a Mamre, a la ciudad de Arba, que es Hebrón, donde habitaron Abraham e Isaac.'),
(v_cap_id, 28, 'Y fueron los días de Isaac ciento ochenta años.'),
(v_cap_id, 29, 'Y exhaló el espíritu Isaac, y murió, y fue reunido a su pueblo, viejo y lleno de días; y lo sepultaron Esaú y Jacob sus hijos.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Estas son las generaciones de Esaú, el cual es Edom.'),
(v_cap_id, 2, 'Esaú tomó sus mujeres de las hijas de Canaán: a Ada, hija de Elón heteo; a Aholibama, hija de Aná, hijo de Zibeón heveo;'),
(v_cap_id, 3, 'y a Basemat, hija de Ismael, hermana de Nebaiot.'),
(v_cap_id, 4, 'Ada dio a luz a Elifaz; Basemat dio a luz a Reuel;'),
(v_cap_id, 5, 'y Aholibama dio a luz a Jeús, a Jaalam y a Coré. Estos son los hijos de Esaú, que le nacieron en la tierra de Canaán.'),
(v_cap_id, 6, 'Y Esaú tomó sus mujeres, sus hijos y sus hijas, y todas las personas de su casa, y sus ganados, y todas sus bestias, y todo cuanto había adquirido en la tierra de Canaán, y se fue a otra tierra, alejándose de su hermano Jacob.'),
(v_cap_id, 7, 'Porque los bienes de ellos eran demasiados para habitar juntos, y la tierra donde moraban no podía sostenerlos a causa de sus ganados.'),
(v_cap_id, 8, 'Y Esaú habitó en el monte de Seir; Esaú es Edom.'),
(v_cap_id, 9, 'Estas son las generaciones de Esaú, padre de Edom, en el monte de Seir.'),
(v_cap_id, 10, 'Estos son los nombres de los hijos de Esaú: Elifaz, hijo de Ada, mujer de Esaú; Reuel, hijo de Basemat, mujer de Esaú.'),
(v_cap_id, 11, 'Y los hijos de Elifaz fueron: Temán, Omar, Zefo, Gatam y Cenaz.'),
(v_cap_id, 12, 'Y Timna fue concubina de Elifaz hijo de Esaú, y ella le dio a luz a Amalec. Estos son los hijos de Ada, mujer de Esaú.'),
(v_cap_id, 13, 'Los hijos de Reuel: Nahat, Zera, Sama y Miza. Estos son los hijos de Basemat, mujer de Esaú.'),
(v_cap_id, 14, 'Estos fueron los hijos de Aholibama, mujer de Esaú, hija de Aná, hijo de Zibeón: ella dio a luz a Jeús, Jaalam y Coré.'),
(v_cap_id, 15, 'Estos son los jefes de los hijos de Esaú: de los hijos de Elifaz, primogénito de Esaú, los jefes: Temán, Omar, Zefo, Cenaz,'),
(v_cap_id, 16, 'Coré, Gatam y Amalec. Estos son los jefes de Elifaz en la tierra de Edom; estos fueron los hijos de Ada.'),
(v_cap_id, 17, 'Y estos son los hijos de Reuel, hijo de Esaú: los jefes Nahat, Zera, Sama y Miza; estos son los jefes de Reuel en la tierra de Edom; estos hijos vinieron de Basemat, mujer de Esaú.'),
(v_cap_id, 18, 'Y estos son los hijos de Aholibama, mujer de Esaú: los jefes Jeús, Jaalam y Coré; estos fueron los jefes que salieron de Aholibama, mujer de Esaú, hija de Aná.'),
(v_cap_id, 19, 'Estos, pues, son los hijos de Esaú, y estos sus jefes; él es Edom.'),
(v_cap_id, 20, 'Estos son los hijos de Seir horeo, habitantes de aquella tierra: Lotán, Sobal, Zibeón, Aná,'),
(v_cap_id, 21, 'Disón, Ezer y Disán; estos son los jefes de los horeos, hijos de Seir, en la tierra de Edom.'),
(v_cap_id, 22, 'Los hijos de Lotán fueron: Hori y Hemam; y la hermana de Lotán fue Timna.'),
(v_cap_id, 23, 'Y los hijos de Sobal: Alván, Manahat, Ebal, Sefo y Onam.'),
(v_cap_id, 24, 'Y los hijos de Zibeón: Aja y Aná. Este Aná es el que descubrió manantiales en el desierto, cuando apacentaba los asnos de Zibeón su padre.'),
(v_cap_id, 25, 'Los hijos de Aná: Disón, y Aholibama, hija de Aná.'),
(v_cap_id, 26, 'Y los hijos de Disón: Hemdán, Esbán, Itrán y Querán.'),
(v_cap_id, 27, 'Y los hijos de Ezer: Bilhán, Zaaván y Acán.'),
(v_cap_id, 28, 'Y los hijos de Disán: Uz y Arán.'),
(v_cap_id, 29, 'Y estos fueron los jefes de los horeos: los jefes Lotán, Sobal, Zibeón, Aná,'),
(v_cap_id, 30, 'Disón, Ezer y Disán; estos fueron los jefes de los horeos, por sus mandos en la tierra de Seir.'),
(v_cap_id, 31, 'Y estos son los reyes que reinaron en la tierra de Edom, antes que reinara rey sobre los hijos de Israel:'),
(v_cap_id, 32, 'Bela hijo de Beor reinó en Edom; y el nombre de su ciudad era Dinaba.'),
(v_cap_id, 33, 'Murió Bela, y reinó en su lugar Jobab, hijo de Zera, de Bosra.'),
(v_cap_id, 34, 'Murió Jobab, y reinó en su lugar Husam, de tierra de Temán.'),
(v_cap_id, 35, 'Murió Husam, y reinó en su lugar Hadad, hijo de Bedad, el que derrotó a Madián en el campo de Moab; y el nombre de su ciudad era Avit.'),
(v_cap_id, 36, 'Murió Hadad, y reinó en su lugar Samla, de Masreca.'),
(v_cap_id, 37, 'Murió Samla, y reinó en su lugar Saúl, de Rehobot, que está junto al Eufrates.'),
(v_cap_id, 38, 'Murió Saúl, y reinó en su lugar Baal-hanán, hijo de Acbor.'),
(v_cap_id, 39, 'Murió Baal-hanán, hijo de Acbor, y reinó en su lugar Hadar, y el nombre de su ciudad fue Pau; y el nombre de su mujer fue Mehetabel, hija de Matred, hija de Mezaab.'),
(v_cap_id, 40, 'Estos, pues, son los nombres de los jefes de Esaú por sus linajes, por sus lugares, y por sus nombres: Timna, Alva, Jetet,'),
(v_cap_id, 41, 'Aholibama, Ela, Pinón,'),
(v_cap_id, 42, 'Cenaz, Temán, Mibzar,'),
(v_cap_id, 43, 'Magdiel e Iram. Estos fueron los jefes de Edom según sus moradas en la tierra de su posesión. Edom es el mismo Esaú, padre de los edomitas.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Habitó Jacob en la tierra donde había morado su padre, en la tierra de Canaán.'),
(v_cap_id, 2, 'Esta es la historia de la familia de Jacob: José, siendo de diecisiete años, apacentaba las ovejas con sus hermanos; y el joven estaba con los hijos de Bilha y con los hijos de Zilpa, mujeres de su padre; y notaba José la mala fama de ellos, y la daba a su padre.'),
(v_cap_id, 3, 'Y amaba Israel a José más que a todos sus hijos, porque era el hijo de su vejez; y le hizo una túnica de diversos colores.'),
(v_cap_id, 4, 'Y viendo sus hermanos que su padre lo amaba más que a todos sus hermanos, le aborrecían, y no podían hablarle pacíficamente.'),
(v_cap_id, 5, 'Y soñó José un sueño, y lo contó a sus hermanos; y ellos llegaron a aborrecerle más todavía.'),
(v_cap_id, 6, 'Y él les dijo: Oíd ahora este sueño que he soñado:'),
(v_cap_id, 7, 'He aquí que atábamos manojos en medio del campo, y he aquí que mi manojo se levantaba y estaba derecho, y que vuestros manojos estaban alrededor y se inclinaban al mío.'),
(v_cap_id, 8, 'Y le respondieron sus hermanos: ¿Has de reinar tú sobre nosotros, o señorearás sobre nosotros? Y le aborrecieron aun más a causa de sus sueños y sus palabras.'),
(v_cap_id, 9, 'Soñó aun otro sueño, y lo contó a sus hermanos, diciendo: He aquí que he soñado otro sueño, y he aquí que el sol y la luna y once estrellas se inclinaban a mí.'),
(v_cap_id, 10, 'Y lo contó a su padre y a sus hermanos; y su padre le reprendió, y le dijo: ¿Qué sueño es este que soñaste? ¿Acaso vendremos yo y tu madre y tus hermanos a postrarnos en tierra ante ti?'),
(v_cap_id, 11, 'Y sus hermanos le tenían envidia, mas su padre meditaba en esto.'),
(v_cap_id, 12, 'Después fueron sus hermanos a apacentar las ovejas de su padre en Siquem.'),
(v_cap_id, 13, 'Y dijo Israel a José: Tus hermanos apacientan las ovejas en Siquem: ven, y te enviaré a ellos. Y él respondió: Heme aquí.'),
(v_cap_id, 14, 'E Israel le dijo: Ve ahora, mira cómo están tus hermanos y cómo están las ovejas, y tráeme la respuesta. Y lo envió del valle de Hebrón, y llegó a Siquem.'),
(v_cap_id, 15, 'Y lo halló un hombre, andando él errante por el campo, y le preguntó aquel hombre, diciendo: ¿Qué buscas?'),
(v_cap_id, 16, 'Y José respondió: Busco a mis hermanos; te ruego que me muestres dónde están apacentando.'),
(v_cap_id, 17, 'Y aquel hombre respondió: Ya se han ido de aquí; y yo les oí decir: Vámonos a Dotán. Entonces José fue tras de sus hermanos, y los halló en Dotán.'),
(v_cap_id, 18, 'Y ellos lo vieron de lejos, y antes que llegara cerca de ellos, conspiraron contra él para matarle.'),
(v_cap_id, 19, 'Y dijeron el uno al otro: He aquí viene el soñador.'),
(v_cap_id, 20, 'Ahora pues, venid, y matémosle, y echémosle en una cisterna, y diremos: Alguna mala bestia lo devoró; y veremos qué será de sus sueños.'),
(v_cap_id, 21, 'Cuando Rubén oyó esto, lo libró de sus manos, y dijo: No lo matemos.'),
(v_cap_id, 22, 'Y les dijo Rubén: No derraméis sangre; echadlo en esta cisterna que está en el desierto, y no pongáis mano sobre él; por librarlo así de sus manos, para hacerlo volver a su padre.'),
(v_cap_id, 23, 'Sucedió, pues, que cuando llegó José a sus hermanos, ellos quitaron a José su túnica, la túnica de diversos colores que llevaba,'),
(v_cap_id, 24, 'y le tomaron y le echaron en la cisterna; pero la cisterna estaba vacía, no había en ella agua.'),
(v_cap_id, 25, 'Y se sentaron a comer pan; y alzando los ojos miraron, y he aquí una compañía de ismaelitas que venía de Galaad, con sus camellos que traían aromas, bálsamo y mirra, y llevaban a Egipto.'),
(v_cap_id, 26, 'Entonces Judá dijo a sus hermanos: ¿Qué provecho el que matemos a nuestro hermano y encubramos su muerte?'),
(v_cap_id, 27, 'Venid, y vendámosle a los ismaelitas, y no sea nuestra mano sobre él; porque él es nuestro hermano, nuestra propia carne. Y sus hermanos convinieron con él.'),
(v_cap_id, 28, 'Y cuando pasaban los madianitas mercaderes, sacaron ellos a José de la cisterna, y le trajeron arriba, y le vendieron a los ismaelitas por veinte piezas de plata. Y ellos llevaron a José a Egipto.'),
(v_cap_id, 29, 'Cuando Rubén volvió a la cisterna, y no halló a José dentro, rasgó sus vestidos,'),
(v_cap_id, 30, 'y volvió a sus hermanos, y dijo: El joven no aparece; y yo, ¿adónde iré yo?'),
(v_cap_id, 31, 'Entonces tomaron ellos la túnica de José, y degollaron un cabrito de las cabras, y tiñeron la túnica con la sangre;'),
(v_cap_id, 32, 'y enviaron la túnica de diversos colores a su padre, la cual le llevaron, y dijeron: Esto hemos hallado; reconoce ahora si es la túnica de tu hijo, o no.'),
(v_cap_id, 33, 'Y él la reconoció, y dijo: La túnica de mi hijo es; alguna mala bestia lo devoró; José ha sido despedazado.'),
(v_cap_id, 34, 'Entonces Jacob rasgó sus vestidos, y puso cilicio sobre sus lomos, y guardó luto por su hijo muchos días.'),
(v_cap_id, 35, 'Y se levantaron todos sus hijos y todas sus hijas para consolarlo, mas él no quiso recibir consuelo, y dijo: Descenderé enlutado a la sepultura donde mi hijo va. Y lo lloró su padre.'),
(v_cap_id, 36, 'Y los madianitas lo vendieron en Egipto a Potifar, oficial de Faraón, capitán de la guardia.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Aconteció en aquel tiempo, que Judá se apartó de sus hermanos, y se fue a un varón adulamita que se llamaba Hira.'),
(v_cap_id, 2, 'Y vio allí Judá la hija de un cananeo, el cual se llamaba Súa; y la tomó, y se llegó a ella.'),
(v_cap_id, 3, 'Y ella concibió, y dio a luz un hijo, y llamó su nombre Er.'),
(v_cap_id, 4, 'Y volvió a concebir, y dio a luz un hijo, y llamó su nombre Onán.'),
(v_cap_id, 5, 'Y volvió a dar a luz un hijo, y llamó su nombre Sela. Y estaba en Quezib cuando lo dio a luz.'),
(v_cap_id, 6, 'Y Judá tomó mujer para Er su primogénito, la cual se llamaba Tamar.'),
(v_cap_id, 7, 'Y Er, primogénito de Judá, fue malo ante los ojos de Jehová, y le quitó Jehová la vida.'),
(v_cap_id, 8, 'Entonces Judá dijo a Onán: Llégate a la mujer de tu hermano, y despósate con ella, y levanta descendencia a tu hermano.'),
(v_cap_id, 9, 'Y sabiendo Onán que la descendencia no había de ser suya, sucedía que cuando se llegaba a la mujer de su hermano, derramaba en tierra, por no dar descendencia a su hermano.'),
(v_cap_id, 10, 'Y desagradó a Jehová lo que hacía, y a él también le quitó la vida.'),
(v_cap_id, 11, 'Y Judá dijo a Tamar su nuera: Quédate viuda en casa de tu padre, hasta que crezca Sela mi hijo; porque dijo: No sea que muera él también como sus hermanos. Y se fue Tamar, y estuvo en casa de su padre.'),
(v_cap_id, 12, 'Pasaron muchos días, y murió la hija de Súa, mujer de Judá. Después Judá se consoló, y subió a los trasquiladores de sus ovejas a Timnat, él y su amigo Hira el adulamita.'),
(v_cap_id, 13, 'Y fue dado aviso a Tamar, diciendo: He aquí tu suegro va a Timnat a trasquilar sus ovejas.'),
(v_cap_id, 14, 'Entonces ella se quitó los vestidos de su viudez, y se cubrió con un velo, y se arrebozó, y se sentó a la entrada de Enaim que está junto al camino de Timnat; porque veía que Sela había crecido, y ella no le era dada por mujer.'),
(v_cap_id, 15, 'Y la vio Judá, y la tuvo por ramera, porque ella había cubierto su rostro.'),
(v_cap_id, 16, 'Y se apartó del camino hacia ella, y le dijo: Déjame ahora llegarme a ti, pues no sabía que era su nuera; y ella dijo: ¿Qué me darás por llegarte a mí?'),
(v_cap_id, 17, 'Y él respondió: Yo te enviaré un cabrito de las cabras. Y ella dijo: Dame una prenda hasta que lo envíes.'),
(v_cap_id, 18, 'Entonces él dijo: ¿Qué prenda te daré? Ella respondió: Tu sello, tu cordón, y tu báculo que tienes en tu mano. Y él se los dio, y se llegó a ella, y ella concibió de él.'),
(v_cap_id, 19, 'Luego se levantó y se fue, y se quitó el velo de sobre sí, y se puso los vestidos de su viudez.'),
(v_cap_id, 20, 'Y Judá envió el cabrito por medio de su amigo el adulamita, para que recibiese la prenda de mano de la mujer; pero no la halló.'),
(v_cap_id, 21, 'Y preguntó a los hombres de aquel lugar, diciendo: ¿Dónde está la ramera de Enaim que estaba junto al camino? Y ellos le dijeron: No ha estado aquí ramera alguna.'),
(v_cap_id, 22, 'Entonces él se volvió a Judá, y dijo: No la he hallado; y también los hombres del lugar dijeron: Aquí no ha estado ramera alguna.'),
(v_cap_id, 23, 'Y Judá dijo: Téngalo ella, para que no seamos menospreciados; he aquí yo envié este cabrito, y tú no la hallaste.'),
(v_cap_id, 24, 'Sucedió que al cabo de unos tres meses, fue dado aviso a Judá, diciendo: Tamar tu nuera ha fornicado, y ciertamente está encinta a causa de las fornicaciones. Y Judá dijo: Sacadla, y sea quemada.'),
(v_cap_id, 25, 'Y ella, cuando la sacaban, envió a decir a su suegro: Del varón cuyas son estas cosas, estoy encinta. Y dijo: Mira ahora de quién son estas cosas, el sello, el cordón y el báculo.'),
(v_cap_id, 26, 'Entonces Judá los reconoció, y dijo: Más justa es ella que yo, por cuanto no la di a Sela mi hijo. Y nunca más la conoció.'),
(v_cap_id, 27, 'Y aconteció que al tiempo del parto, he aquí había gemelos en su vientre.'),
(v_cap_id, 28, 'Y sucedió cuando daba a luz, que sacó la mano el uno, y la partera tomó y ató a su mano un hilo de grana, diciendo: Este salió primero.'),
(v_cap_id, 29, 'Pero aconteció que él retiró la mano, y he aquí su hermano salió; y ella dijo: ¡Qué brecha te has abierto! Y llamó su nombre Fares.'),
(v_cap_id, 30, 'Después salió su hermano, el que tenía el hilo de grana en su mano, y llamó su nombre Zara.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Llevado, pues, José a Egipto, Potifar, oficial de Faraón, capitán de la guardia, varón egipcio, lo compró de los ismaelitas que lo habían llevado allá.'),
(v_cap_id, 2, 'Mas Jehová estaba con José, y fue varón próspero; y estaba en la casa de su amo el egipcio.'),
(v_cap_id, 3, 'Y vio su amo que Jehová estaba con él, y que todo lo que él hacía, Jehová lo prosperaba en su mano.'),
(v_cap_id, 4, 'Así halló José gracia en sus ojos, y le servía; y él le hizo mayordomo de su casa, y entregó en su poder todo lo que tenía.'),
(v_cap_id, 5, 'Y aconteció que desde cuando le dio el encargo de su casa y de todo lo que tenía, Jehová bendijo la casa del egipcio a causa de José, y la bendición de Jehová estaba sobre todo lo que tenía, así en casa como en el campo.'),
(v_cap_id, 6, 'Y dejó todo lo que tenía en mano de José, y con él no se preocupaba de cosa alguna sino del pan que comía. Y era José de hermoso semblante y bella presencia.'),
(v_cap_id, 7, 'Y aconteció después de esto, que la mujer de su amo puso sus ojos en José, y dijo: Duerme conmigo.'),
(v_cap_id, 8, 'Y él no quiso, y dijo a la mujer de su amo: He aquí que mi señor no se preocupa conmigo de lo que hay en casa, y ha puesto en mi mano todo lo que tiene.'),
(v_cap_id, 9, 'No hay otro mayor que yo en esta casa, y ninguna cosa me ha reservado sino a ti, por cuanto tú eres su mujer; ¿cómo, pues, haría yo este grande mal, y pecaría contra Dios?'),
(v_cap_id, 10, 'Y aconteció que hablaba ella a José cada día, y él no la escuchaba para acostarse al lado de ella, para estar con ella.'),
(v_cap_id, 11, 'Aconteció que entró él un día en casa para hacer su oficio, y no había nadie de los de casa allí.'),
(v_cap_id, 12, 'Y ella lo asió por su ropa, diciendo: Duerme conmigo. Entonces él dejó su ropa en la mano de ella, y huyó y salió.'),
(v_cap_id, 13, 'Cuando vio ella que él había dejado su ropa en sus manos, y había huido fuera,'),
(v_cap_id, 14, 'llamó a los de casa, y les habló diciendo: Mirad, nos ha traído un hebreo para que hiciera burla de nosotros; vino él a mí para dormir conmigo, y yo di grandes voces;'),
(v_cap_id, 15, 'y viendo que yo alzaba la voz y gritaba, dejó su ropa junto a mí, y huyó y salió.'),
(v_cap_id, 16, 'Y ella puso la ropa de José junto a sí, hasta que vino su señor a su casa.'),
(v_cap_id, 17, 'Y le habló semejantes palabras, diciendo: El siervo hebreo que nos trajiste, vino a mí para deshonrarme.'),
(v_cap_id, 18, 'Y cuando yo alcé mi voz y grité, él dejó su ropa junto a mí y huyó fuera.'),
(v_cap_id, 19, 'Y sucedió que cuando oyó su señor las palabras que su mujer le hablaba, diciendo: Así me ha hecho tu siervo, se encendió su ira.'),
(v_cap_id, 20, 'Y tomó su amo a José, y lo puso en la cárcel donde estaban los presos del rey. Y estuvo allí en la cárcel.'),
(v_cap_id, 21, 'Pero Jehová estaba con José, y le extendió su misericordia, y le dio gracia en los ojos del jefe de la cárcel.'),
(v_cap_id, 22, 'Y el jefe de la cárcel entregó en mano de José a todos los presos que había en aquella prisión; todo lo que se hacía allí, él lo hacía.'),
(v_cap_id, 23, 'No necesitaba atender el jefe de la cárcel cosa alguna de las que estaban al cuidado de José, porque Jehová estaba con José, y lo que él hacía, Jehová lo prosperaba.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Aconteció después de estas cosas, que el copero del rey de Egipto y el panadero delinquieron contra su señor el rey de Egipto.'),
(v_cap_id, 2, 'Y se enojó Faraón contra sus dos oficiales, contra el jefe de los coperos y contra el jefe de los panaderos.'),
(v_cap_id, 3, 'Y los puso en prisión en la casa del capitán de la guardia, en la cárcel donde José estaba preso.'),
(v_cap_id, 4, 'Y el capitán de la guardia encargó a José para que estuviese con ellos, y él les servía; y estuvieron algunos días en la prisión.'),
(v_cap_id, 5, 'Y ambos, el copero y el panadero del rey de Egipto, que estaban arrestados en la prisión, tuvieron un sueño, cada uno su propio sueño, y cada sueño con su interpretación.'),
(v_cap_id, 6, 'Vino a ellos José por la mañana y los miró, y he aquí que estaban tristes.'),
(v_cap_id, 7, 'Y él preguntó a aquellos oficiales de Faraón que estaban con él en la prisión de la casa de su señor, diciendo: ¿Por qué parecen hoy tristes vuestros rostros?'),
(v_cap_id, 8, 'Y ellos le dijeron: Hemos tenido un sueño, y no hay quien lo interprete. Entonces les dijo José: ¿No son de Dios las interpretaciones? Contádmelo ahora.'),
(v_cap_id, 9, 'Entonces el jefe de los coperos contó su sueño a José, y le dijo: Yo soñaba que veía una vid delante de mí,'),
(v_cap_id, 10, 'y en la vid tres sarmientos; y ella como que brotaba, y arrojaba su flor, y llegaron a madurar sus racimos uvas.'),
(v_cap_id, 11, 'Y que la copa de Faraón estaba en mi mano, y tomaba yo las uvas, las exprimía en la copa de Faraón, y daba la copa en mano de Faraón.'),
(v_cap_id, 12, 'Y le dijo José: Esta es su interpretación: los tres sarmientos son tres días.'),
(v_cap_id, 13, 'Al cabo de tres días, Faraón te alzará la cabeza, y te restituirá a tu puesto, y darás la copa a Faraón en su mano, como solías hacer cuando eras su copero.'),
(v_cap_id, 14, 'Acuérdate, pues, de mí cuando tengas ese bien, y te ruego que uses conmigo de misericordia, y hagas mención de mí a Faraón, y me saques de esta casa.'),
(v_cap_id, 15, 'Porque fui hurtado de la tierra de los hebreos; y tampoco he hecho aquí por qué me pusiesen en la cárcel.'),
(v_cap_id, 16, 'Viendo el jefe de los panaderos que había interpretado para bien, dijo a José: También yo soñé que veía tres canastillos blancos sobre mi cabeza.'),
(v_cap_id, 17, 'En el canastillo más alto había toda clase de manjares de pastelería para Faraón; y las aves las comían del canastillo de sobre mi cabeza.'),
(v_cap_id, 18, 'Entonces respondió José, y dijo: Esta es su interpretación: Los tres canastillos son tres días.'),
(v_cap_id, 19, 'Al cabo de tres días te quitará Faraón la cabeza, y te hará colgar en una horca, y las aves comerán tu carne de sobre ti.'),
(v_cap_id, 20, 'Al tercer día, que era el día del cumpleaños de Faraón, él hizo banquete a todos sus siervos; y alzó la cabeza al jefe de los coperos y al jefe de los panaderos, en medio de sus siervos.'),
(v_cap_id, 21, 'E hizo volver a su oficio al jefe de los coperos, y dio nuevamente la copa en mano de Faraón.'),
(v_cap_id, 22, 'Mas hizo ahorcar al jefe de los panaderos, como lo había interpretado José.'),
(v_cap_id, 23, 'Y el jefe de los coperos no se acordó de José, sino que le olvidó.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Aconteció que pasados dos años, tuvo Faraón un sueño. Le parecía que estaba junto al Nilo;'),
(v_cap_id, 2, 'y que del Nilo subían siete vacas, hermosas a la vista y muy gordas, y pacían en el prado.'),
(v_cap_id, 3, 'Y que tras ellas subían del mismo río otras siete vacas, de feo aspecto y enflaquecidas, y se pararon cerca de las vacas hermosas a la orilla del Nilo.'),
(v_cap_id, 4, 'Y las vacas de feo aspecto y enflaquecidas devoraron a las siete vacas hermosas y muy gordas. Y despertó Faraón.'),
(v_cap_id, 5, 'Se volvió a dormir, y soñó la segunda vez: y veía que siete espigas llenas y hermosas crecían de una sola caña.'),
(v_cap_id, 6, 'Y que después de ellas brotaban siete espigas menudas y abatidas del viento solano.'),
(v_cap_id, 7, 'Y las siete espigas menudas devoraron a las siete espigas gruesas y llenas. Y despertó Faraón, y fue sueño.'),
(v_cap_id, 8, 'Sucedió que por la mañana estaba agitado su espíritu, y envió e hizo llamar a todos los magos de Egipto, y a todos sus sabios; y les contó Faraón sus sueños, mas no hubo quien los pudiese interpretar a Faraón.'),
(v_cap_id, 9, 'Entonces el jefe de los coperos habló a Faraón, diciendo: Me acuerdo hoy de mis faltas.'),
(v_cap_id, 10, 'Cuando Faraón se enojó contra sus siervos, y nos puso en prisión en la casa del capitán de la guardia, a mí y al jefe de los panaderos,'),
(v_cap_id, 11, 'él y yo tuvimos un sueño en la misma noche, y cada sueño tenía su interpretación.'),
(v_cap_id, 12, 'Y estaba allí con nosotros un joven hebreo, siervo del capitán de la guardia; y se los contamos, y él nos interpretó nuestros sueños, y declaró a cada uno conforme a su sueño.'),
(v_cap_id, 13, 'Y aconteció que como él nos los interpretó, así fue: yo fui restituido a mi puesto, y el otro fue ahorcado.'),
(v_cap_id, 14, 'Entonces Faraón envió y llamó a José. Y lo sacaron apresuradamente de la cárcel, y se afeitó, y mudó sus vestidos, y vino a Faraón.'),
(v_cap_id, 15, 'Y dijo Faraón a José: Yo he tenido un sueño, y no hay quien lo interprete; mas he oído decir de ti, que oyes sueños para interpretarlos.'),
(v_cap_id, 16, 'Respondió José a Faraón, diciendo: No está en mí; Dios será el que dé respuesta propicia a Faraón.'),
(v_cap_id, 17, 'Entonces Faraón dijo a José: En mi sueño, me parecía que estaba a la orilla del Nilo;'),
(v_cap_id, 18, 'y que del Nilo subían siete vacas de gruesas carnes y hermosa apariencia, que pacían en el prado;'),
(v_cap_id, 19, 'y que después de ellas subían otras siete vacas, flacas y de muy feo aspecto; tan extenuadas, que no he visto otras semejantes en fealdad en toda la tierra de Egipto.'),
(v_cap_id, 20, 'Y las siete vacas flacas y feas devoraban a las siete primeras vacas gordas;'),
(v_cap_id, 21, 'y éstas entraban en sus entrañas, mas no se conocía que hubiesen entrado, porque la apariencia de las flacas era aún mala, como al principio. Y yo desperté.'),
(v_cap_id, 22, 'Vi también en sueños, que siete espigas crecían en una misma caña, llenas y hermosas.'),
(v_cap_id, 23, 'Y que siete espigas menudas, marchitas, abatidas del viento solano, crecían después de ellas;'),
(v_cap_id, 24, 'y las espigas menudas devoraban a las siete espigas hermosas; y lo he dicho a los magos, mas no hay quien me lo interprete.'),
(v_cap_id, 25, 'Entonces respondió José a Faraón: El sueño de Faraón es uno mismo; Dios ha mostrado a Faraón lo que va a hacer.'),
(v_cap_id, 26, 'Las siete vacas hermosas siete años son; y las espigas hermosas son siete años: el sueño es uno mismo.'),
(v_cap_id, 27, 'Y las siete vacas flacas y feas que subían tras ellas, son siete años; y las siete espigas menudas y marchitas del viento solano, siete años serán de hambre.'),
(v_cap_id, 28, 'Esto es lo que respondo a Faraón: Lo que Dios va a hacer, lo ha mostrado a Faraón.'),
(v_cap_id, 29, 'He aquí vienen siete años de gran abundancia en toda la tierra de Egipto.'),
(v_cap_id, 30, 'Y tras ellos seguirán siete años de hambre; y toda la abundancia será olvidada en la tierra de Egipto, y el hambre consumirá la tierra.'),
(v_cap_id, 31, 'Y no se sentirá la abundancia en la tierra, a causa del hambre que vendrá después; porque será muy grave.'),
(v_cap_id, 32, 'Y el suceder el sueño a Faraón dos veces, significa que la cosa es firme de parte de Dios, y que Dios se apresura a hacerla.'),
(v_cap_id, 33, 'Por tanto, provéase ahora Faraón de un varón prudente y sabio, y póngalo sobre la tierra de Egipto.'),
(v_cap_id, 34, 'Haga esto Faraón, y ponga gobernadores sobre el país, y quinte la tierra de Egipto en los siete años de la abundancia.'),
(v_cap_id, 35, 'Y junten toda la provisión de estos buenos años que vienen, y recojan el trigo bajo la mano de Faraón para mantenimiento de las ciudades; y guárdenlo.'),
(v_cap_id, 36, 'Y esté aquella provisión en depósito para el país, para los siete años de hambre que vendrán en la tierra de Egipto; y el país no perecerá de hambre.'),
(v_cap_id, 37, 'El asunto pareció bien a Faraón y a sus siervos.'),
(v_cap_id, 38, 'Y dijo Faraón a sus siervos: ¿Acaso hallaremos a otro hombre como éste, en quien esté el espíritu de Dios?'),
(v_cap_id, 39, 'Y dijo Faraón a José: Pues que Dios te ha hecho saber todo esto, no hay entendido ni sabio como tú.'),
(v_cap_id, 40, 'Tú estarás sobre mi casa, y por tu palabra se gobernará todo mi pueblo; solamente en el trono seré yo mayor que tú.'),
(v_cap_id, 41, 'Dijo además Faraón a José: He aquí yo te he puesto sobre toda la tierra de Egipto.'),
(v_cap_id, 42, 'Entonces Faraón quitó su anillo de su mano, y lo puso en la mano de José, y lo hizo vestir de ropas de lino finísimo, y puso un collar de oro en su cuello;'),
(v_cap_id, 43, 'y lo hizo subir en su segundo carro, y pregonaron delante de él: ¡Doblad la rodilla! Y lo puso sobre toda la tierra de Egipto.'),
(v_cap_id, 44, 'Y dijo Faraón a José: Yo soy Faraón; y sin ti ninguno alzará su mano ni su pie en toda la tierra de Egipto.'),
(v_cap_id, 45, 'Y llamó Faraón el nombre de José, Zafnat-panea; y le dio por mujer a Asenat, hija de Potifera, sacerdote de On. Y salió José por toda la tierra de Egipto.'),
(v_cap_id, 46, 'Era José de edad de treinta años cuando fue presentado delante de Faraón rey de Egipto; y salió José de delante de Faraón, y recorrió toda la tierra de Egipto.'),
(v_cap_id, 47, 'En aquellos siete años de abundancia, la tierra produjo a montones.'),
(v_cap_id, 48, 'Y José juntó todo el trigo de los siete años de abundancia en Egipto, y guardó el trigo en las ciudades, poniendo en cada ciudad el trigo del campo de sus alrededores.'),
(v_cap_id, 49, 'Y recogió José trigo como arena del mar, mucho en extremo, hasta no poderse contar, porque no tenía número.'),
(v_cap_id, 50, 'Y nacieron a José dos hijos antes que viniese el primer año de hambre, los cuales le dio a luz Asenat, hija de Potifera, sacerdote de On.'),
(v_cap_id, 51, 'Y llamó José el nombre del primogénito, Manasés; porque dijo: Dios me hizo olvidar todo mi trabajo, y toda la casa de mi padre.'),
(v_cap_id, 52, 'Y llamó el nombre del segundo, Efraín; porque dijo: Dios me hizo fructificar en la tierra de mi aflicción.'),
(v_cap_id, 53, 'Y se cumplieron los siete años de abundancia que hubo en la tierra de Egipto.'),
(v_cap_id, 54, 'Y comenzaron a venir los siete años del hambre, como José había dicho; y hubo hambre en todos los países, mas en toda la tierra de Egipto había pan.'),
(v_cap_id, 55, 'Cuando se sintió el hambre en toda la tierra de Egipto, el pueblo clamó a Faraón por pan. Y dijo Faraón a todos los egipcios: Id a José, y haced lo que él os dijere.'),
(v_cap_id, 56, 'Y el hambre estaba por toda la extensión del país. Entonces José abrió todos los graneros, y vendió a los egipcios; porque había crecido el hambre en la tierra de Egipto.'),
(v_cap_id, 57, 'Y de toda la tierra venían a Egipto para comprar trigo, porque era grande el hambre en toda la tierra.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Viendo Jacob que en Egipto había alimentos, dijo a sus hijos: ¿Por qué os estáis mirando?'),
(v_cap_id, 2, 'Y dijo: He aquí, yo he oído que hay víveres en Egipto; descended allá, y comprad de allí para nosotros, para que podamos vivir y no muramos.'),
(v_cap_id, 3, 'Y descendieron diez hermanos de José a comprar trigo en Egipto.'),
(v_cap_id, 4, 'Pero Jacob no envió a Benjamín, hermano de José, con sus hermanos, porque dijo: No sea que le acontezca algún desastre.'),
(v_cap_id, 5, 'Vinieron los hijos de Israel a comprar entre los que venían; porque había hambre en la tierra de Canaán.'),
(v_cap_id, 6, 'Y José era el señor de la tierra, que le vendía a todo el pueblo de la tierra; y llegaron los hermanos de José, y se inclinaron a él rostro a tierra.'),
(v_cap_id, 7, 'Y José, cuando vio a sus hermanos, los conoció, pero hizo como que no los conocía, y les habló ásperamente, y les dijo: ¿De dónde habéis venido? Ellos respondieron: De la tierra de Canaán, para comprar alimentos.'),
(v_cap_id, 8, 'José, pues, conoció a sus hermanos; pero ellos no le conocieron.'),
(v_cap_id, 9, 'Entonces se acordó José de los sueños que había tenido acerca de ellos, y les dijo: Espías sois; para ver las partes débiles de la tierra habéis venido.'),
(v_cap_id, 10, 'Ellos le respondieron: No, señor nuestro, sino que tus siervos han venido a comprar alimentos.'),
(v_cap_id, 11, 'Todos nosotros somos hijos de un mismo varón; somos hombres pacíficos, y nunca tus siervos han sido espías.'),
(v_cap_id, 12, 'Y José les dijo: No, para ver las partes débiles de la tierra habéis venido.'),
(v_cap_id, 13, 'Y ellos respondieron: Tus siervos somos doce hermanos, hijos de un varón en la tierra de Canaán; y he aquí el menor está hoy con nuestro padre, y uno no parece.'),
(v_cap_id, 14, 'Y José les dijo: Eso es lo que os he dicho, afirmando que sois espías.'),
(v_cap_id, 15, 'En esto seréis probados: Vive Faraón, que no saldréis de aquí sino cuando vuestro hermano menor viniere aquí.'),
(v_cap_id, 16, 'Enviad a uno de vosotros, y traiga a vuestro hermano; y vosotros quedad presos, y vuestras palabras serán probadas, si hay verdad con vosotros; y si no, vive Faraón, que sois espías.'),
(v_cap_id, 17, 'Y los puso juntos en la cárcel por tres días.'),
(v_cap_id, 18, 'Y al tercer día les dijo José: Haced esto, y vivid: Yo temo a Dios.'),
(v_cap_id, 19, 'Si sois hombres pacíficos, quede uno de vuestros hermanos preso en la cárcel; y vosotros id, llevad el trigo para el hambre de vuestra casa.'),
(v_cap_id, 20, 'Pero traeréis a vuestro hermano menor, y serán verificadas vuestras palabras, y no moriréis. Y ellos lo hicieron así.'),
(v_cap_id, 21, 'Y decían el uno al otro: Verdaderamente hemos pecado contra nuestro hermano, pues vimos la angustia de su alma cuando nos rogaba, y no le escuchamos; por eso ha venido sobre nosotros esta angustia.'),
(v_cap_id, 22, 'Entonces Rubén les respondió, diciendo: ¿No os hablé yo y dije: No pequéis contra el joven, y no escuchasteis? He aquí también se nos demanda su sangre.'),
(v_cap_id, 23, 'Pero ellos no sabían que los entendía José, porque había intérprete entre ellos.'),
(v_cap_id, 24, 'Y se apartó José de ellos y lloró; después volvió a ellos, y les habló, y tomó de entre ellos a Simeón, y lo aprisionó a vista de ellos.'),
(v_cap_id, 25, 'Y mandó José que llenaran sus sacos de trigo, y que devolvieran el dinero de cada uno de ellos, poniéndolo en su saco, y que les dieran comida para el camino; y así se hizo.'),
(v_cap_id, 26, 'Y ellos pusieron el trigo sobre sus asnos, y se fueron de allí.'),
(v_cap_id, 27, 'Y abriendo uno de ellos su saco para dar de comer a su asno en el mesón, vio su dinero que estaba en la boca de su costal.'),
(v_cap_id, 28, 'Y dijo a sus hermanos: Mi dinero se me ha devuelto, y helo aquí en mi saco. Se les sobresaltó el corazón, y espantados dijeron el uno al otro: ¿Qué es esto que nos ha hecho Dios?'),
(v_cap_id, 29, 'Y vinieron a Jacob su padre en tierra de Canaán, y le contaron todo lo que les había acontecido, diciendo:'),
(v_cap_id, 30, 'Aquel varón, señor de la tierra, nos habló ásperamente, y nos trató como a espías de la tierra.'),
(v_cap_id, 31, 'Y nosotros le dijimos: Somos hombres pacíficos, no somos espías.'),
(v_cap_id, 32, 'Somos doce hermanos, hijos de nuestro padre; uno no parece, y el menor está hoy con nuestro padre en la tierra de Canaán.'),
(v_cap_id, 33, 'Y aquel varón, señor de la tierra, nos dijo: En esto conoceré que sois hombres pacíficos: dejad conmigo uno de vuestros hermanos, y tomad para el hambre de vuestras casas, y andad,'),
(v_cap_id, 34, 'y traed a vuestro hermano menor a mí; así sabré yo que no sois espías, sino hombres pacíficos, y os daré a vuestro hermano, y negociaréis en la tierra.'),
(v_cap_id, 35, 'Y aconteció que al vaciar ellos sus sacos, he aquí que en cada saco de cada uno estaba el atado de su dinero; y viendo ellos y su padre los atados de su dinero, tuvieron temor.'),
(v_cap_id, 36, 'Entonces su padre Jacob les dijo: Me habéis privado de mis hijos; José no parece, ni Simeón tampoco, y a Benjamín le llevaréis; contra mí son todas estas cosas.'),
(v_cap_id, 37, 'Y Rubén habló a su padre, diciendo: Harás morir a mis dos hijos, si no te lo devolviere; entrégalo en mi mano, y yo lo devolveré a ti.'),
(v_cap_id, 38, 'Y Jacob dijo: No descenderá mi hijo con vosotros; porque su hermano ha muerto, y él solo queda; y si le aconteciere algún desastre en el camino por donde vais, haréis descender mis canas con dolor a la sepultura.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'El hambre era grande en la tierra;'),
(v_cap_id, 2, 'y aconteció que cuando acabaron de comer el trigo que trajeron de Egipto, les dijo su padre: Volved, y comprad para nosotros un poco de alimento.'),
(v_cap_id, 3, 'Y Judá respondió, diciendo: Aquel varón nos protestó con ánimo resuelto, diciendo: No veréis mi rostro si no trajereis a vuestro hermano con vosotros.'),
(v_cap_id, 4, 'Si enviares a nuestro hermano con nosotros, descenderemos y te compraremos alimento.'),
(v_cap_id, 5, 'Pero si no le enviares, no descenderemos; porque aquel varón nos dijo: No veréis mi rostro si no trajereis a vuestro hermano con vosotros.'),
(v_cap_id, 6, 'Dijo entonces Israel: ¿Por qué me hicisteis tanto mal, declarando al varón que teníais otro hermano?'),
(v_cap_id, 7, 'Y ellos respondieron: Aquel varón nos preguntó expresamente por nosotros y por nuestra familia, diciendo: ¿Vive aún vuestro padre? ¿Tenéis otro hermano? Y le declaramos conforme a estas palabras. ¿Acaso podíamos saber que él diría: Haced venir a vuestro hermano?'),
(v_cap_id, 8, 'Entonces Judá dijo a Israel su padre: Envía al joven conmigo, y nos levantaremos e iremos, a fin de que vivamos y no muramos nosotros, ni tú, ni nuestros niños.'),
(v_cap_id, 9, 'Yo te respondo por él; a mí me pedirás cuenta. Si yo no te lo devolviere, y lo pusiere delante de ti, seré para ti el culpable para siempre.'),
(v_cap_id, 10, 'Si no nos hubiéramos detenido, ciertamente ahora hubiéramos ya vuelto dos veces.'),
(v_cap_id, 11, 'Entonces Israel su padre les dijo: Pues que así es, haced esto: tomad de lo mejor de la tierra en vuestros sacos, y llevad a aquel varón un presente, un poco de bálsamo, un poco de miel, aromas y mirra, nueces y almendras.'),
(v_cap_id, 12, 'Y tomad en vuestras manos dinero doble, y llevad en vuestra mano el dinero devuelto en vuestros costales; quizá fue equivocación.'),
(v_cap_id, 13, 'Tomad también a vuestro hermano, y levantaos, y volved a aquel varón.'),
(v_cap_id, 14, 'Y el Dios Omnipotente os dé misericordia delante de aquel varón, para que os suelte al otro vuestro hermano, y a este Benjamín. Y si he de ser privado de mis hijos, séalo.'),
(v_cap_id, 15, 'Entonces tomaron aquellos hombres el presente, y tomaron en su mano dinero doble, y a Benjamín; y se levantaron y descendieron a Egipto, y se presentaron delante de José.'),
(v_cap_id, 16, 'Y vio José a Benjamín con ellos, y dijo al mayordomo de su casa: Lleva a casa a esos hombres, y degüella una res y prepárala, porque estos hombres comerán conmigo al mediodía.'),
(v_cap_id, 17, 'E hizo el mayordomo como José le dijo, y llevó a los hombres a casa de José.'),
(v_cap_id, 18, 'Entonces aquellos hombres tuvieron temor cuando fueron llevados a casa de José, y decían: Por el dinero que fue devuelto en nuestros costales la primera vez nos traen, para derribarnos sobre nosotros, y tendernos lazo, y tomarnos por siervos a nosotros, y a nuestros asnos.'),
(v_cap_id, 19, 'Y se acercaron al mayordomo de la casa de José, y le hablaron a la puerta de la casa,'),
(v_cap_id, 20, 'y dijeron: ¡Ay, señor nuestro! Nosotros en verdad descendimos al principio a comprar alimentos.'),
(v_cap_id, 21, 'Y aconteció que cuando llegamos al mesón y abrimos nuestros costales, he aquí el dinero de cada uno estaba en la boca de su costal, nuestro dinero en su justo peso; y lo hemos vuelto a traer en nuestras manos.'),
(v_cap_id, 22, 'Hemos también traído otro dinero en nuestras manos para comprar alimentos; no sabemos quién haya puesto nuestro dinero en nuestros costales.'),
(v_cap_id, 23, 'Y él respondió: Paz a vosotros, no temáis; vuestro Dios y el Dios de vuestro padre os dio el tesoro en vuestros costales; yo recibí vuestro dinero. Y sacó a Simeón a ellos.'),
(v_cap_id, 24, 'Y llevó aquel varón a los hombres a casa de José; les dio agua, y lavaron sus pies, y dio de comer a sus asnos.'),
(v_cap_id, 25, 'Y ellos prepararon el presente entretanto que José venía a mediodía, porque habían oído que allí comerían.'),
(v_cap_id, 26, 'Y vino José a casa, y ellos le trajeron el presente que tenían en sus manos dentro de la casa, y se inclinaron a él hasta la tierra.'),
(v_cap_id, 27, 'Entonces les preguntó José cómo estaban, y dijo: ¿Vuestro padre, el anciano que dijisteis, lo pasa bien? ¿Vive todavía?'),
(v_cap_id, 28, 'Y ellos respondieron: Tu siervo nuestro padre está bien, vive todavía. Y se inclinaron, e hicieron reverencia.'),
(v_cap_id, 29, 'Y alzando José sus ojos vio a Benjamín su hermano, hijo de su madre, y dijo: ¿Es éste vuestro hermano menor, de quien me hablasteis? Y dijo: Dios tenga misericordia de ti, hijo mío.'),
(v_cap_id, 30, 'Entonces José se apresuró, porque se conmovieron sus entrañas a causa de su hermano, y buscó dónde llorar; y entró en su cámara, y lloró allí.'),
(v_cap_id, 31, 'Después se lavó la cara y salió, y se contuvo, y dijo: Poned pan.'),
(v_cap_id, 32, 'Y pusieron para él aparte, y también para ellos aparte, y para los egipcios que comían con él aparte; porque los egipcios no pueden comer pan con los hebreos, lo cual es abominación a los egipcios.'),
(v_cap_id, 33, 'Y se sentaron delante de él, el mayor conforme a su primogenitura, y el menor conforme a su menoría; y estaban aquellos hombres atónitos mirándose el uno al otro.'),
(v_cap_id, 34, 'Y José tomó viandas de delante de sí para ellos; pero la porción de Benjamín era cinco veces mayor que cualquiera de las de ellos. Y bebieron, y se alegraron con él.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Mandó José al mayordomo de su casa, diciendo: Llena de provisiones los costales de estos hombres, cuanto puedan llevar, y pon el dinero de cada uno en la boca de su costal.'),
(v_cap_id, 2, 'Y pondrás mi copa, la copa de plata, en la boca del costal del menor, con el dinero de su trigo. Y él hizo como dijo José.'),
(v_cap_id, 3, 'Venida la mañana, los hombres fueron despedidos con sus asnos.'),
(v_cap_id, 4, 'Habían ellos salido de la ciudad, y no estaban aún lejos, cuando dijo José a su mayordomo: Levántate, sigue a esos hombres; y cuando los alcances, diles: ¿Por qué habéis vuelto mal por bien?'),
(v_cap_id, 5, '¿No es ésta la copa en que bebe mi señor, y por la que suele adivinar? Habéis hecho mal en lo que hicisteis.'),
(v_cap_id, 6, 'Y cuando él les alcanzó, les dijo estas palabras.'),
(v_cap_id, 7, 'Y ellos le respondieron: ¿Por qué dice mi señor tales cosas? Nunca tal hagan tus siervos.'),
(v_cap_id, 8, 'He aquí, el dinero que hallamos en la boca de nuestros costales, te lo volvimos a traer desde la tierra de Canaán; ¿cómo, pues, habíamos de hurtar de casa de tu señor plata ni oro?'),
(v_cap_id, 9, 'Aquel de tus siervos en quien fuere hallada la copa, que muera, y aun nosotros seremos siervos de mi señor.'),
(v_cap_id, 10, 'Y él dijo: También sea ahora como vosotros decís; aquel en quien se hallare, será mi siervo, y vosotros seréis sin culpa.'),
(v_cap_id, 11, 'Entonces ellos se dieron prisa, y cada uno descendió su costal, y lo abrió.'),
(v_cap_id, 12, 'Y buscó; desde el mayor comenzó, y acabó con el menor; y la copa fue hallada en el costal de Benjamín.'),
(v_cap_id, 13, 'Entonces ellos rasgaron sus vestidos, y cargó cada uno su asno, y volvieron a la ciudad.'),
(v_cap_id, 14, 'Y llegó Judá con sus hermanos a casa de José, que aún estaba allí, y se postraron delante de él en tierra.'),
(v_cap_id, 15, 'Y les dijo José: ¿Qué es esto que habéis hecho? ¿No sabéis que un hombre como yo sabe adivinar?'),
(v_cap_id, 16, 'Entonces Judá dijo: ¿Qué diremos a mi señor? ¿Qué hablaremos? ¿O con qué nos justificaremos? Dios ha hallado la maldad de tus siervos; he aquí, nosotros somos siervos de mi señor, nosotros, y también aquel en quien fue hallada la copa.'),
(v_cap_id, 17, 'Y José respondió: Nunca yo haga tal; el varón en quien fue hallada la copa, ése será mi siervo; vosotros, id en paz a vuestro padre.'),
(v_cap_id, 18, 'Entonces Judá se acercó a él, y dijo: Ay, señor mío, te ruego que permitas que hable tu siervo una palabra a oídos de mi señor, y no se encienda tu ira contra tu siervo, pues tú eres como Faraón.'),
(v_cap_id, 19, 'Mi señor preguntó a sus siervos, diciendo: ¿Tenéis padre o hermano?'),
(v_cap_id, 20, 'Y nosotros respondimos a mi señor: Tenemos un padre anciano, y un hermano joven, hijo de su vejez, pequeño aún; y un hermano suyo murió, y él solo quedó de su madre; y su padre lo ama.'),
(v_cap_id, 21, 'Y tú dijiste a tus siervos: Traédmelo, y yo pondré mis ojos sobre él.'),
(v_cap_id, 22, 'Y nosotros dijimos a mi señor: El joven no puede dejar a su padre, porque si lo dejare, su padre morirá.'),
(v_cap_id, 23, 'Y dijiste a tus siervos: Si vuestro hermano menor no desciende con vosotros, no veréis más mi rostro.'),
(v_cap_id, 24, 'Aconteció, pues, que cuando llegamos a tu siervo mi padre, le contamos las palabras de mi señor.'),
(v_cap_id, 25, 'Y dijo nuestro padre: Volved a comprarnos un poco de alimento.'),
(v_cap_id, 26, 'Y nosotros dijimos: No podemos ir; si nuestro hermano menor va con nosotros, iremos; porque no podremos ver el rostro del varón, si no está con nosotros nuestro hermano menor.'),
(v_cap_id, 27, 'Entonces tu siervo mi padre nos dijo: Vosotros sabéis que dos hijos me dio a luz mi mujer;'),
(v_cap_id, 28, 'y el uno salió de mi lado, y pienso que de cierto fue despedazado, y hasta ahora no lo he visto.'),
(v_cap_id, 29, 'Y si tomáis también a este de delante de mí, y le acontece algún desastre, haréis descender mis canas con dolor a la sepultura.'),
(v_cap_id, 30, 'Ahora, pues, cuando llegue yo a tu siervo mi padre, si el joven no está con nosotros, como su alma está ligada a la suya,'),
(v_cap_id, 31, 'sucederá que cuando no vea al joven, morirá; y tus siervos harán descender las canas de tu siervo nuestro padre con dolor a la sepultura.'),
(v_cap_id, 32, 'Porque tu siervo salió por fiador del joven con mi padre, diciendo: Si no te lo devolviere, entonces yo seré culpable ante mi padre para siempre.'),
(v_cap_id, 33, 'Te ruego, por tanto, que quede ahora tu siervo en lugar del joven por siervo de mi señor, y que el joven suba con sus hermanos.'),
(v_cap_id, 34, 'Porque ¿cómo subiré yo a mi padre sin el joven, para que no vea el mal que sobrevendrá a mi padre?')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'No se podía ya contener José delante de todos los que estaban al lado suyo, y clamó: Haced salir a todos de delante de mí. Y no quedó nadie con él, al darse a conocer José a sus hermanos.'),
(v_cap_id, 2, 'Entonces se dio a llorar a gritos, y oyeron los egipcios, y oyó también la casa de Faraón.'),
(v_cap_id, 3, 'Y dijo José a sus hermanos: Yo soy José; ¿vive aún mi padre? Y sus hermanos no pudieron responderle, porque estaban turbados delante de él.'),
(v_cap_id, 4, 'Entonces dijo José a sus hermanos: Acercaos ahora a mí. Y ellos se acercaron. Y él dijo: Yo soy José vuestro hermano, el que vendisteis a Egipto.'),
(v_cap_id, 5, 'Ahora, pues, no os entristezcáis, ni os pese de haberme vendido acá; porque para preservación de vida me envió Dios delante de vosotros.'),
(v_cap_id, 6, 'Porque ya ha habido dos años de hambre en medio de la tierra, y aún quedan cinco años en los cuales ni habrá arada ni siega.'),
(v_cap_id, 7, 'Y Dios me envió delante de vosotros, para preservaros posteridad sobre la tierra, y para daros vida por medio de gran liberación.'),
(v_cap_id, 8, 'Así, pues, no me enviasteis acá vosotros, sino Dios, que me ha puesto por padre de Faraón, y por señor de toda su casa, y por gobernador en toda la tierra de Egipto.'),
(v_cap_id, 9, 'Daos prisa, id a mi padre, y decidle: Así dice tu hijo José: Dios me ha puesto por señor de todo Egipto; ven a mí, no te detengas.'),
(v_cap_id, 10, 'Habitarás en la tierra de Gosén, y estarás cerca de mí, tú y tus hijos, y los hijos de tus hijos, tus ganados y tus vacas, y todo lo que tienes.'),
(v_cap_id, 11, 'Y allí te alimentaré, porque aún quedan cinco años de hambre, para que no perezcas de pobreza tú y tu casa, y todo lo que tienes.'),
(v_cap_id, 12, 'He aquí, vuestros ojos ven, y los ojos de mi hermano Benjamín, que mi boca os habla.'),
(v_cap_id, 13, 'Haréis, pues, saber a mi padre toda mi gloria en Egipto, y todo lo que habéis visto; y daros prisa y traer a mi padre acá.'),
(v_cap_id, 14, 'Y se echó sobre el cuello de Benjamín su hermano, y lloró; y también Benjamín lloró sobre su cuello.'),
(v_cap_id, 15, 'Y besó a todos sus hermanos, y lloró sobre ellos; y después sus hermanos hablaron con él.'),
(v_cap_id, 16, 'Y se oyó la noticia en la casa de Faraón, diciendo: Los hermanos de José han venido. Y esto pareció bien a Faraón y a sus siervos.'),
(v_cap_id, 17, 'Y dijo Faraón a José: Di a tus hermanos: Haced esto: cargad vuestras bestias, andad, volved a la tierra de Canaán;'),
(v_cap_id, 18, 'y tomad a vuestro padre y a vuestras familias y venid a mí, porque yo os daré lo bueno de la tierra de Egipto, y comeréis de la abundancia de la tierra.'),
(v_cap_id, 19, 'Y tú manda: Haced esto: tomaos de la tierra de Egipto carros para vuestros niños y vuestras mujeres, y traed a vuestro padre, y venid.'),
(v_cap_id, 20, 'No os preocupéis por vuestros enseres, porque la abundancia de toda la tierra de Egipto será vuestra.'),
(v_cap_id, 21, 'E hicieron así los hijos de Israel; y les dio José carros conforme a la orden de Faraón, y les dio víveres para el camino.'),
(v_cap_id, 22, 'A cada uno de todos ellos dio mudas de vestidos, y a Benjamín dio trescientas piezas de plata, y cinco mudas de vestidos.'),
(v_cap_id, 23, 'Y a su padre envió esto: diez asnos cargados de lo mejor de Egipto, y diez asnas cargadas de trigo y pan y comida, para su padre en el camino.'),
(v_cap_id, 24, 'Y despidió a sus hermanos, y fueron ellos, y él les dijo: No riñáis por el camino.'),
(v_cap_id, 25, 'Y subieron de Egipto, y llegaron a la tierra de Canaán a Jacob su padre.'),
(v_cap_id, 26, 'Y le dieron las nuevas, diciendo: José vive aún; y él es señor de toda la tierra de Egipto. Y su corazón se desmayó, pues no les creía.'),
(v_cap_id, 27, 'Y ellos le contaron todas las palabras de José, que él les había hablado; y viendo Jacob los carros que José enviaba para llevarlo, su espíritu revivió.'),
(v_cap_id, 28, 'Entonces dijo Israel: Basta; José mi hijo vive todavía; iré y le veré antes que yo muera.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Salió Israel con todo lo que tenía, y vino a Beerseba, y ofreció sacrificios al Dios de su padre Isaac.'),
(v_cap_id, 2, 'Y habló Dios a Israel en visiones de noche, y dijo: Jacob, Jacob. Y él respondió: Heme aquí.'),
(v_cap_id, 3, 'Y dijo: Yo soy Dios, el Dios de tu padre; no temas de descender a Egipto, porque allí yo haré de ti una gran nación.'),
(v_cap_id, 4, 'Yo descenderé contigo a Egipto, y yo también te haré volver; y la mano de José cerrará tus ojos.'),
(v_cap_id, 5, 'Y se levantó Jacob de Beerseba; y tomaron los hijos de Israel a su padre Jacob, y a sus niños y a sus mujeres, en los carros que Faraón había enviado para llevarlo.'),
(v_cap_id, 6, 'Tomaron también sus ganados y sus bienes que habían adquirido en la tierra de Canaán, y vinieron a Egipto, Jacob y toda su descendencia consigo;'),
(v_cap_id, 7, 'sus hijos, y los hijos de sus hijos consigo; sus hijas, y las hijas de sus hijos, y toda su descendencia trajo consigo a Egipto.'),
(v_cap_id, 8, 'Y estos son los nombres de los hijos de Israel, que entraron en Egipto, Jacob y sus hijos: Rubén, el primogénito de Jacob.'),
(v_cap_id, 9, 'Los hijos de Rubén: Hanoc, Falú, Hezrón y Carmi.'),
(v_cap_id, 10, 'Los hijos de Simeón: Jemuel, Jamín, Ohad, Jaquín, Zohar y Saúl, hijo de la cananea.'),
(v_cap_id, 11, 'Los hijos de Leví: Gersón, Coat y Merari.'),
(v_cap_id, 12, 'Los hijos de Judá: Er, Onán, Sela, Fares y Zara; mas Er y Onán murieron en la tierra de Canaán. Y los hijos de Fares: Hezrón y Hamul.'),
(v_cap_id, 13, 'Los hijos de Isacar: Tola, Fúa, Job y Simrón.'),
(v_cap_id, 14, 'Los hijos de Zabulón: Sered, Elón y Jahleel.'),
(v_cap_id, 15, 'Estos son los hijos de Lea, los que dio a luz a Jacob en Padan-aram, además de su hija Dina; todas las almas de sus hijos y sus hijas, treinta y tres.'),
(v_cap_id, 16, 'Los hijos de Gad: Zifión, Hagui, Eşbón, Suni, Eber, Erodí y Ariel.'),
(v_cap_id, 17, 'Y los hijos de Aser: Imna, Isúa, Isúi, Bería, y la hermana de ellos, Sera. Y los hijos de Bería: Heber y Malquiel.'),
(v_cap_id, 18, 'Estos fueron los hijos de Zilpa, la que Labán dio a su hija Lea, y dio a luz estos a Jacob, en total dieciséis personas.'),
(v_cap_id, 19, 'Los hijos de Raquel, mujer de Jacob: José y Benjamín.'),
(v_cap_id, 20, 'Y nacieron a José en la tierra de Egipto Manasés y Efraín, los que le dio a luz Asenat, hija de Potifera, sacerdote de On.'),
(v_cap_id, 21, 'Los hijos de Benjamín: Bela, Bequer, Asbel, Gera, Naamán, Ehi, Ros, Mupim, Hupim y Ard.'),
(v_cap_id, 22, 'Estos son los hijos de Raquel que nacieron a Jacob; en total, catorce personas.'),
(v_cap_id, 23, 'Los hijos de Dan: Husim.'),
(v_cap_id, 24, 'Los hijos de Neftalí: Jahzeel, Guni, Jezer y Silem.'),
(v_cap_id, 25, 'Estos son los hijos de Bilha, la que dio Labán a Raquel su hija, y dio a luz estos a Jacob; en total, siete personas.'),
(v_cap_id, 26, 'Todas las personas que vinieron con Jacob a Egipto, procedentes de sus lomos, sin las mujeres de los hijos de Jacob, todas las personas fueron sesenta y seis.'),
(v_cap_id, 27, 'Y los hijos de José, que le nacieron en Egipto, dos personas. Todas las personas de la casa de Jacob, que entraron en Egipto, fueron setenta.'),
(v_cap_id, 28, 'Y Jacob envió a Judá delante de sí a José, para que le viniese a ver en Gosén; y llegaron a la tierra de Gosén.'),
(v_cap_id, 29, 'Y José unció su carro y subió a recibir a Israel su padre en Gosén; y se manifestó a él, y se echó sobre su cuello, y lloró sobre su cuello largamente.'),
(v_cap_id, 30, 'Entonces Israel dijo a José: Muera yo ahora, ya que he visto tu rostro, y sé que vives aún.'),
(v_cap_id, 31, 'Y José dijo a sus hermanos y a la casa de su padre: Subiré y lo haré saber a Faraón, y le diré: Mis hermanos y la casa de mi padre, que estaban en la tierra de Canaán, han venido a mí.'),
(v_cap_id, 32, 'Y los hombres son pastores de ovejas, porque son hombres ganaderos; y han traído sus ovejas y sus vacas, y todo lo que tienen.'),
(v_cap_id, 33, 'Y cuando Faraón os llamare y dijere: ¿Cuál es vuestro oficio?'),
(v_cap_id, 34, 'entonces diréis: Hombres ganaderos hemos sido tus siervos desde nuestra juventud hasta ahora, nosotros y nuestros padres; a fin de que moréis en la tierra de Gosén, porque los egipcios abominan a todo pastor de ovejas.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Fue José y lo hizo saber a Faraón, y dijo: Mi padre y mis hermanos, y sus ovejas y sus vacas, con todo lo que tienen, han venido de la tierra de Canaán, y he aquí están en la tierra de Gosén.'),
(v_cap_id, 2, 'Y tomó de sus hermanos cinco de ellos, y los presentó a Faraón.'),
(v_cap_id, 3, 'Y Faraón dijo a sus hermanos: ¿Cuál es vuestro oficio? Y ellos respondieron a Faraón: Pastores de ovejas son tus siervos, así nosotros como nuestros padres.'),
(v_cap_id, 4, 'Dijeron además a Faraón: Para morar en esta tierra hemos venido; porque no hay pasto para las ovejas de tus siervos, pues el hambre es grave en la tierra de Canaán; por tanto, te rogamos que habiten tus siervos en la tierra de Gosén.'),
(v_cap_id, 5, 'Entonces Faraón habló a José, diciendo: Tu padre y tus hermanos han venido a ti.'),
(v_cap_id, 6, 'La tierra de Egipto está delante de ti; haz habitar a tu padre y a tus hermanos en la mejor parte de la tierra; habiten en la tierra de Gosén; y si entiendes que hay entre ellos hombres capaces, ponlos por mayorales del ganado mío.'),
(v_cap_id, 7, 'Y José introdujo a Jacob su padre, y lo presentó delante de Faraón; y Jacob bendijo a Faraón.'),
(v_cap_id, 8, 'Y dijo Faraón a Jacob: ¿Cuántos son los días de los años de tu vida?'),
(v_cap_id, 9, 'Y Jacob respondió a Faraón: Los días de los años de mi peregrinación son ciento treinta años; pocos y malos han sido los días de los años de mi vida, y no han llegado a los días de los años de la vida de mis padres en los días de su peregrinación.'),
(v_cap_id, 10, 'Y Jacob bendijo a Faraón, y salió de delante de Faraón.'),
(v_cap_id, 11, 'Y José hizo habitar a su padre y a sus hermanos, y les dio propiedad en la tierra de Egipto, en lo mejor de la tierra, en la tierra de Ramesés, como mandó Faraón.'),
(v_cap_id, 12, 'Y José alimentó a su padre y a sus hermanos, y a toda la casa de su padre, con pan, según el número de los hijos.'),
(v_cap_id, 13, 'No había entonces pan en toda la tierra, porque el hambre era muy grave, y desfallecía de hambre la tierra de Egipto y la tierra de Canaán.'),
(v_cap_id, 14, 'Y recogió José todo el dinero que había en la tierra de Egipto y en la tierra de Canaán, por el trigo que compraban; y puso José el dinero en la casa de Faraón.'),
(v_cap_id, 15, 'Y cuando se acabó el dinero en la tierra de Egipto y en la tierra de Canaán, vinieron todos los egipcios a José, diciendo: Danos pan; ¿por qué moriremos delante de ti? pues el dinero se ha acabado.'),
(v_cap_id, 16, 'Y José respondió: Dad vuestros ganados, y yo os daré pan por vuestros ganados, si se ha acabado el dinero.'),
(v_cap_id, 17, 'Y ellos trajeron sus ganados a José, y José les dio pan por los caballos, y por el ganado de las ovejas, y por el ganado de las vacas, y por los asnos; y les suministró pan por todos sus ganados aquel año.'),
(v_cap_id, 18, 'Acabado aquel año, vinieron a él el segundo año, y le dijeron: No encubrimos a mi señor que el dinero ciertamente se ha acabado; también los ganados son de mi señor; nada ha quedado delante de mi señor sino nuestros cuerpos y nuestra tierra.'),
(v_cap_id, 19, '¿Por qué moriremos delante de tus ojos, así nosotros como nuestra tierra? Cómprenos a nosotros y a nuestra tierra por pan, y seremos nosotros y nuestra tierra siervos de Faraón; y danos semilla para que vivamos y no muramos, y no quede la tierra desolada.'),
(v_cap_id, 20, 'Entonces compró José toda la tierra de Egipto para Faraón, pues los egipcios vendieron cada uno sus tierras, porque se agravó el hambre sobre ellos; y la tierra vino a ser de Faraón.'),
(v_cap_id, 21, 'Y al pueblo lo hizo pasar a las ciudades, desde un extremo hasta el otro.'),
(v_cap_id, 22, 'Solamente la tierra de los sacerdotes no la compró, pues los sacerdotes tenían ración de Faraón, y vivían de la ración que Faraón les daba; por eso no vendieron sus tierras.'),
(v_cap_id, 23, 'Y José dijo al pueblo: He aquí hoy os he comprado y vuestra tierra para Faraón; ved aquí semilla para vosotros, y sembraréis la tierra.'),
(v_cap_id, 24, 'De los frutos daréis el quinto a Faraón, y las cuatro partes serán vuestras para sembrar la tierra, y para vuestro mantenimiento, y para los que están en vuestras casas, y para que coman vuestros niños.'),
(v_cap_id, 25, 'Y ellos respondieron: Tú nos has dado vida; hallemos gracia en ojos de mi señor, y seamos siervos de Faraón.'),
(v_cap_id, 26, 'Entonces José puso por ley hasta hoy sobre la tierra de Egipto, que de Faraón se llevase la quinta parte; excepto la tierra de los sacerdotes solamente, que no fue de Faraón.'),
(v_cap_id, 27, 'Así habitó Israel en la tierra de Egipto, en la tierra de Gosén; y tomaron posesión de ella, y se aumentaron, y se multiplicaron en gran manera.'),
(v_cap_id, 28, 'Y vivió Jacob en la tierra de Egipto diecisiete años; y fueron los días de Jacob, los años de su vida, ciento cuarenta y siete años.'),
(v_cap_id, 29, 'Y cuando se acercó el tiempo de la muerte de Israel, llamó a José su hijo, y le dijo: Si he hallado ahora gracia en tus ojos, te ruego que pongas tu mano debajo de mi muslo, y harás conmigo misericordia y verdad: te ruego que no me entierres en Egipto.'),
(v_cap_id, 30, 'Cuando haya dormido con mis padres, me llevarás de Egipto, y me sepultarás en el sepulcro de ellos. Y José respondió: Haré como tú dices.'),
(v_cap_id, 31, 'E Israel dijo: Júramelo. Y José le juró. Entonces Israel se inclinó sobre la cabecera de la cama.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Sucedió después de estas cosas que dijeron a José: He aquí tu padre está enfermo. Y él tomó consigo a sus dos hijos, Manasés y Efraín.'),
(v_cap_id, 2, 'Y se le hizo saber a Jacob, diciendo: He aquí tu hijo José viene a ti. Entonces Israel se esforzó, y se sentó sobre la cama.'),
(v_cap_id, 3, 'Y dijo Jacob a José: El Dios Omnipotente me apareció en Luz, en la tierra de Canaán, y me bendijo,'),
(v_cap_id, 4, 'y me dijo: He aquí yo te haré fructificar y te multiplicaré, y te pondré por conjunto de pueblos, y daré esta tierra a tu descendencia después de ti por heredad perpetua.'),
(v_cap_id, 5, 'Y ahora tus dos hijos que te nacieron en la tierra de Egipto, antes que viniese a ti a la tierra de Egipto, míos son; Efraín y Manasés serán míos, como Rubén y Simeón.'),
(v_cap_id, 6, 'Y los que después de ellos has engendrado, serán tuyos; por el nombre de sus hermanos serán llamados en sus heredades.'),
(v_cap_id, 7, 'Porque cuando yo venía de Padan-aram, se me murió Raquel en la tierra de Canaán, en el camino, como a media legua de tierra llegando a Efrata; y la sepulté allí en el camino de Efrata, que es Belén.'),
(v_cap_id, 8, 'Y vio Israel los hijos de José, y dijo: ¿Quiénes son éstos?'),
(v_cap_id, 9, 'Y respondió José a su padre: Son mis hijos, que Dios me ha dado aquí. Y él dijo: Acércalos ahora a mí, y los bendeciré.'),
(v_cap_id, 10, 'Y los ojos de Israel eran tan oscuros por la vejez, que no podía ver. Les hizo, pues, acercarse a él, y él los besó y los abrazó.'),
(v_cap_id, 11, 'Y dijo Israel a José: No pensaba yo ver tu rostro, y he aquí Dios me ha hecho ver también tu descendencia.'),
(v_cap_id, 12, 'Entonces José los sacó de entre las rodillas de él, y se inclinó a tierra.'),
(v_cap_id, 13, 'Y los tomó José a ambos, a Efraín a su derecha, a la izquierda de Israel; y a Manasés a su izquierda, a la derecha de Israel; y los hizo acercarse a él.'),
(v_cap_id, 14, 'Entonces Israel extendió su mano derecha y la puso sobre la cabeza de Efraín, que era el menor, y su mano izquierda sobre la cabeza de Manasés, colocando así sus manos adrede, aunque Manasés era el primogénito.'),
(v_cap_id, 15, 'Y bendijo a José, y dijo: El Dios en cuya presencia anduvieron mis padres Abraham e Isaac, el Dios que me pastorea desde que yo soy hasta este día,'),
(v_cap_id, 16, 'el Ángel que me liberta de todo mal, bendiga a estos jóvenes; y sea perpetuado en ellos mi nombre, y el nombre de mis padres Abraham e Isaac; y multiplíquense en gran manera en medio de la tierra.'),
(v_cap_id, 17, 'Pero José, viendo que su padre ponía la mano derecha sobre la cabeza de Efraín, le causó disgusto; y asió la mano de su padre para quitarla de sobre la cabeza de Efraín y pasarla a la cabeza de Manasés.'),
(v_cap_id, 18, 'Y dijo José a su padre: No así, padre mío, porque éste es el primogénito; pon tu mano derecha sobre su cabeza.'),
(v_cap_id, 19, 'Mas su padre no quiso, y dijo: Lo sé, hijo mío, lo sé; también él vendrá a ser un pueblo, y será también engrandecido; pero su hermano menor será más grande que él, y su descendencia será multitud de naciones.'),
(v_cap_id, 20, 'Y los bendijo aquel día, diciendo: En ti bendecirá Israel, diciendo: Hárate Dios como a Efraín y como a Manasés. Y puso a Efraín delante de Manasés.'),
(v_cap_id, 21, 'Y dijo Israel a José: He aquí, yo muero; mas Dios estará con vosotros, y os hará volver a la tierra de vuestros padres.'),
(v_cap_id, 22, 'Y yo te he dado a ti una parte más que a tus hermanos, la cual tomé yo de mano del amorreo con mi espada y con mi arco.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Y llamó Jacob a sus hijos, y dijo: Juntaos, y os declararé lo que os ha de acontecer en los postreros días.'),
(v_cap_id, 2, 'Juntaos y oíd, hijos de Jacob; escuchad a vuestro padre Israel.'),
(v_cap_id, 3, 'Rubén, tú eres mi primogénito, mi fortaleza, y el principio de mi vigor; principal en dignidad, principal en poder.'),
(v_cap_id, 4, 'Impetuoso como las aguas, no serás el principal, por cuanto subiste al lecho de tu padre; entonces te envileciste, subiendo a mi estrado.'),
(v_cap_id, 5, 'Simeón y Leví son hermanos; armas de iniquidad sus armas.'),
(v_cap_id, 6, 'En su consejo no entre mi alma, ni mi espíritu se junte en su compañía. Porque en su furor mataron hombres, y en su temeridad desjarretaron toros.'),
(v_cap_id, 7, 'Maldito su furor, que fue fiero; y su ira, que fue dura. Yo los apartaré en Jacob, y los esparciré en Israel.'),
(v_cap_id, 8, 'Judá, te alabarán tus hermanos; tu mano en la cerviz de tus enemigos; los hijos de tu padre se inclinarán a ti.'),
(v_cap_id, 9, 'Cachorro de león, Judá; de la presa subiste, hijo mío. Se encorvó, se echó como león, así como león viejo: ¿quién lo despertará?'),
(v_cap_id, 10, 'No será quitado el cetro de Judá, ni el legislador de entre sus pies, hasta que venga Siloh; y a él se congregarán los pueblos.'),
(v_cap_id, 11, 'Atando a la vid su pollino, y a la cepa el hijo de su asna, lavó en el vino su vestido, y en la sangre de uvas su manto.'),
(v_cap_id, 12, 'Sus ojos, rojos del vino, y sus dientes blancos de la leche.'),
(v_cap_id, 13, 'Zabulón en puertos de mar habitará; será para puerto de naves, y su límite hasta Sidón.'),
(v_cap_id, 14, 'Isacar, asno fuerte que se recuesta entre los apriscos;'),
(v_cap_id, 15, 'y vio que el descanso era bueno, y que la tierra era deleitosa; y bajó su hombro para llevar, y sirvió en tributo.'),
(v_cap_id, 16, 'Dan juzgará a su pueblo, como una de las tribus de Israel.'),
(v_cap_id, 17, 'Será Dan serpiente junto al camino, víbora junto a la senda, que muerde los talones del caballo, y hace caer hacia atrás al jinete.'),
(v_cap_id, 18, 'Tu salvación esperé, oh Jehová.'),
(v_cap_id, 19, 'Gad, ejército lo acometerá; mas él acometerá al final.'),
(v_cap_id, 20, 'El pan de Aser será substancioso, y él dará deleites al rey.'),
(v_cap_id, 21, 'Neftalí, cierva suelta, que dirá palabras hermosas.'),
(v_cap_id, 22, 'Ramo fructífero es José, ramo fructífero junto a una fuente, cuyos vástagos se extienden sobre el muro.'),
(v_cap_id, 23, 'Le causaron amargura, le asaetearon, y le aborrecieron los arqueros;'),
(v_cap_id, 24, 'mas su arco se mantuvo firme, y los brazos de sus manos se fortalecieron por las manos del Fuerte de Jacob (de allí es el Pastor, la Roca de Israel),'),
(v_cap_id, 25, 'por el Dios de tu padre, el cual te ayudará, y por el Omnipotente, el cual te bendecirá con bendiciones de los cielos de arriba, con bendiciones del abismo que está abajo, con bendiciones de los pechos y del vientre.'),
(v_cap_id, 26, 'Las bendiciones de tu padre fueron mayores que las bendiciones de mis progenitores; hasta el término de los collados eternos serán sobre la cabeza de José, y sobre la frente del que fue apartado de entre sus hermanos.'),
(v_cap_id, 27, 'Benjamín es lobo arrebatador; a la mañana comerá la presa, y a la noche repartirá los despojos.'),
(v_cap_id, 28, 'Todos estos fueron las doce tribus de Israel, y esto fue lo que su padre les dijo, al bendecirlos; a cada uno por su bendición los bendijo.'),
(v_cap_id, 29, 'Les mandó luego, y les dijo: Yo voy a ser reunido con mi pueblo. Sepultadme con mis padres en la cueva que está en el campo de Efrón el heteo,'),
(v_cap_id, 30, 'en la cueva que está en el campo de Macpela, que está al oriente de Mamre, en la tierra de Canaán, la cual compró Abraham con el mismo campo de Efrón el heteo, para heredad de sepultura.'),
(v_cap_id, 31, 'Allí sepultaron a Abraham y a Sara su mujer; allí sepultaron a Isaac y a Rebeca su mujer; allí también sepulté yo a Lea.'),
(v_cap_id, 32, 'La compra del campo y de la cueva que está en él, fue de los hijos de Het.'),
(v_cap_id, 33, 'Y cuando acabó Jacob de dar mandamientos a sus hijos, encogió sus pies en la cama, y expiró, y fue reunido a su pueblo.')
INSERT INTO versiculos (capitulo_id, numero, texto) VALUES
(v_cap_id, 1, 'Entonces José se echó sobre el rostro de su padre, y lloró sobre él, y lo besó.'),
(v_cap_id, 2, 'Y mandó José a sus siervos los médicos que embalsamasen a su padre; y los médicos embalsamaron a Israel.'),
(v_cap_id, 3, 'Y le cumplieron cuarenta días, porque así cumplían los días de los embalsamados, y lloráronlo los egipcios setenta días.'),
(v_cap_id, 4, 'Y pasados los días del luto, habló José a los de la casa de Faraón, diciendo: Si he hallado ahora gracia en vuestros ojos, os ruego que habléis a Faraón, diciendo:'),
(v_cap_id, 5, 'Mi padre me hizo jurar, diciendo: He aquí voy a morir; en el sepulcro que cavé para mí en la tierra de Canaán, allí me sepultarás; por tanto, subiré ahora para sepultar a mi padre, y volveré.'),
(v_cap_id, 6, 'Y Faraón dijo: Sube, y sepulta a tu padre, como él te hizo jurar.'),
(v_cap_id, 7, 'Entonces José subió a sepultar a su padre; y subieron con él todos los siervos de Faraón, los ancianos de su casa, y todos los ancianos de la tierra de Egipto,'),
(v_cap_id, 8, 'y toda la casa de José, y sus hermanos, y la casa de su padre; solamente dejaron en la tierra de Gosén a sus niños y sus ovejas y sus vacas.'),
(v_cap_id, 9, 'Subieron también con él carros y gente de a caballo, y se hizo un escuadrón muy grande.'),
(v_cap_id, 10, 'Y llegaron hasta la era de Atad, que está al otro lado del Jordán, y endecharon allí con grande y muy doloroso lamento; y José hizo a su padre duelo por siete días.'),
(v_cap_id, 11, 'Y viendo los moradores de la tierra, los cananeos, el llanto en la era de Atad, dijeron: Llanto grande es este de los egipcios; por esto fue llamado su nombre Abel-mizraim, que está al otro lado del Jordán.'),
(v_cap_id, 12, 'Hicieron, pues, sus hijos así como él les había mandado;'),
(v_cap_id, 13, 'y lo llevaron sus hijos a la tierra de Canaán, y lo sepultaron en la cueva del campo de Macpela, la que había comprado Abraham con el mismo campo, para heredad de sepultura, de Efrón el heteo, al oriente de Mamre.'),
(v_cap_id, 14, 'Y volvió José a Egipto, él y sus hermanos, y todos los que subieron con él a sepultar a su padre, después que lo hubo sepultado.'),
(v_cap_id, 15, 'Y viendo los hermanos de José que su padre era muerto, dijeron: Quizá nos aborrecerá José, y nos dará el pago de todo el mal que le hicimos.'),
(v_cap_id, 16, 'Y enviaron a decir a José: Antes que tu padre muriese, mandó diciendo:'),
(v_cap_id, 17, 'Así diréis a José: Te ruego que perdones ahora la maldad de tus hermanos y su pecado, porque mal te trataron; por tanto, ahora te rogamos que perdones la maldad de los siervos del Dios de tu padre. Y José lloró mientras hablaban.'),
(v_cap_id, 18, 'Vinieron también sus hermanos y se postraron delante de él, y dijeron: Henos aquí por siervos tuyos.'),
(v_cap_id, 19, 'Y les respondió José: No temáis; ¿acaso estoy yo en lugar de Dios?'),
(v_cap_id, 20, 'Vosotros pensasteis mal contra mí, mas Dios lo encaminó a bien, para hacer lo que vemos hoy, para mantener en vida a mucho pueblo.'),
(v_cap_id, 21, 'Ahora, pues, no tengáis miedo; yo os sustentaré a vosotros y a vuestros hijos. Así los consoló, y les habló al corazón.'),
(v_cap_id, 22, 'Y estuvo José en Egipto, él y la casa de su padre; y vivió José ciento diez años.'),
(v_cap_id, 23, 'Y vio José los hijos de Efraín hasta la tercera generación; también los hijos de Maquir, hijo de Manasés, fueron criados sobre las rodillas de José.'),
(v_cap_id, 24, 'Y José dijo a sus hermanos: Yo voy a morir; mas Dios ciertamente os visitará, y os hará subir de esta tierra a la tierra que juró a Abraham, a Isaac y a Jacob.'),
(v_cap_id, 25, 'E hizo jurar José a los hijos de Israel, diciendo: Dios ciertamente os visitará, y haréis llevar mis huesos de aquí.'),
(v_cap_id, 26, 'Y murió José de edad de ciento diez años; y lo embalsamaron, y fue puesto en un ataúd en Egipto.')
